window.STEPS=Object.assign(window.STEPS||{},{"ns-0177d2a3c227":{"길":"B 의 크기별로 B 를 고르고 A 를 B 의 부분집합으로 고른다","단계":[{"제목":"B 의 원소 수로 경우 나누기","힌트":"$B$ 를 먼저 정하고 나면 $A$ 는 어떤 집합들 중에서 고르게 될까?","식":["$n(B)=k$ 일 때 $B$ 의 개수: ${}_{4}\\mathrm{C}_{k}$","$A$ 의 개수: $B$ 의 부분집합의 수 $2^{k}$"],"설명":"$A\\subset B$ 이므로 $B$ 가 정해지면 $A$ 는 $B$ 의 부분집합 중 하나이다. 원소가 $k$ 개인 집합의 부분집합은 $2^{k}$ 개이므로 $B$ 의 크기로 경우를 나눈다.","확인":null,"스킬":"C2"},{"제목":"크기별 순서쌍의 개수 구하기","고비":true,"힌트":"$k=4,\\,3,\\,2,\\,1,\\,0$ 일 때 ${}_{4}\\mathrm{C}_{k}\\times 2^{k}$ 은 각각 얼마일까?","식":["$k=4:\\ 1\\times16=16,\\quad k=3:\\ 4\\times8=32$","$k=2:\\ 6\\times4=24,\\quad k=1:\\ 4\\times2=8$","$k=0:\\ 1\\times1=1$"],"설명":"$B$ 를 고르는 수와 $A$ 를 고르는 수를 곱해 크기마다 따로 구한다. $k=0$ 이면 $B$ 가 공집합이라 $A$ 도 공집합뿐이다.","확인":null,"스킬":"P4"},{"제목":"크기별 개수 모두 더하기","힌트":"다섯 경우는 서로 겹치지 않으므로 더하면?","식":["$16+32+24+8+1=81$"],"설명":"$B$ 의 크기가 다르면 서로 다른 순서쌍이므로 경우의 수를 모두 더한다.","확인":"81","스킬":"P4"}]},"ns-022e07231b46":{"길":"의자를 원으로 이어 전체 배치에서 두 사람이 이웃한 배치를 뺀다","단계":[{"제목":"회전을 같게 보고 전체 배치 구하기","힌트":"의자 10개에 5명을 앉히는 순열을 구한 뒤 회전으로 겹치는 배치는 하나로 세면?","식":["${}_{10}\\mathrm{P}_{5}=30240$","$180^{\\circ}$ 회전하면 겹치는 배치가 둘씩이므로 $30240\\div2=15120$"],"설명":"직사각형 탁자는 $180^{\\circ}$ 돌렸을 때만 원래 모양과 겹친다. 5명이 앉은 배치는 돌리면 반드시 다른 자리가 되어 모든 배치가 둘씩 짝지어지므로 순열의 수를 $2$ 로 나눈다.","확인":"15120","스킬":"P3"},{"제목":"이웃한 두 자리와 앉는 순서 세기","고비":true,"힌트":"모서리에 인접한 의자까지 이웃으로 볼 때 이웃한 자리쌍은 몇 개이고, 그 두 자리에 $\\mathrm{A},\\ \\mathrm{B}$ 가 앉는 순서는 몇 가지일까?","식":["변을 따라 이웃한 쌍: $2+2+1+1=6$","모서리에서 이웃한 쌍: $4$","$(6+4)\\times2=20$"],"설명":"위·아래 줄은 의자 3개씩이라 이웃한 쌍이 $2$ 개씩, 양옆은 의자 2개씩이라 $1$ 개씩이다. 모서리에 인접한 의자도 이웃으로 보므로 네 모서리의 쌍을 더하면 10쌍이고, 각 쌍에서 $\\mathrm{A},\\ \\mathrm{B}$ 의 순서가 $2$ 가지이다.","확인":"20","스킬":"P4"},{"제목":"이웃하는 배치의 수 구하기","힌트":"남은 8개 자리에 나머지 3명을 앉히고, 회전으로 겹치는 것은 하나로 세면?","식":["${}_{8}\\mathrm{P}_{3}=336$","$20\\times336=6720$","$6720\\div2=3360$"],"설명":"$\\mathrm{A},\\ \\mathrm{B}$ 가 앉은 두 자리를 뺀 8자리 중 3자리에 나머지 3명을 앉힌다. 전체 배치와 같은 방식으로 회전으로 겹치는 것을 $2$ 로 나눈다.","확인":"3360","스킬":"P4"},{"제목":"여사건으로 이웃하지 않는 경우 구하기","힌트":"전체 배치에서 이웃하는 배치를 빼면?","식":["$15120-3360=11760$"],"설명":"$\\mathrm{A}$ 와 $\\mathrm{B}$ 가 이웃하지 않는 경우는 전체 경우에서 이웃하는 경우를 뺀 것이다.","확인":"11760","스킬":"P2"}]},"ns-05aac6ca70c5":{"길":"방 인원 구성을 나누고 A, B 가 든 방에 따라 센 뒤 방 이름을 붙인다","단계":[{"제목":"가능한 방 인원 구성 찾기","힌트":"각 방에 최소 1명, 최대 4명이 들어가고 합이 $8$ 인 세 수의 묶음은?","식":["$1+3+4=8,\\quad 2+2+4=8,\\quad 2+3+3=8$"],"설명":"빈방이 없으므로 각 방은 $1$ 명 이상이고, 4인실이므로 $4$ 명 이하이다. 이 조건을 만족하며 합이 $8$ 인 구성은 세 가지뿐이다.","확인":null,"스킬":"C2"},{"제목":"(1, 3, 4) 구성에서 같은 방인 경우 세기","힌트":"$\\mathrm{A},\\ \\mathrm{B}$ 가 3명 방에 있을 때와 4명 방에 있을 때로 나누어 나머지 사람을 배정하면?","식":["3명 방: ${}_{6}\\mathrm{C}_{1}\\times{}_{5}\\mathrm{C}_{1}=30$","4명 방: ${}_{6}\\mathrm{C}_{2}\\times{}_{4}\\mathrm{C}_{1}=60$","방 이름 $3!$: $3!\\times(30+60)=540$"],"설명":"1명 방에는 두 사람이 함께 들어갈 수 없다. 세 묶음의 크기가 모두 달라 서로 구별되므로, 묶음을 세 객실에 배정하는 방법이 $3!$ 가지이다.","확인":"540","스킬":"C2"},{"제목":"(2, 2, 4) 구성에서 같은 방인 경우 세기","고비":true,"힌트":"$\\mathrm{A},\\ \\mathrm{B}$ 가 4명 방에 있을 때 남은 4명을 2명씩 두 묶음으로 나누는 방법은?","식":["2명 방: ${}_{6}\\mathrm{C}_{2}\\times{}_{4}\\mathrm{C}_{4}=15$","4명 방: ${}_{6}\\mathrm{C}_{2}\\times\\left({}_{4}\\mathrm{C}_{2}\\times{}_{2}\\mathrm{C}_{2}\\times\\dfrac{1}{2!}\\right)=15\\times3=45$","$3!\\times(15+45)=360$"],"설명":"같은 크기의 두 묶음은 순서를 구별하지 않으므로 $\\frac{1}{2!}$ 을 곱해 중복을 없앤다. 묶음이 정해진 뒤에는 세 묶음을 객실에 배정하는 $3!$ 을 곱한다.","확인":"360","스킬":"C2"},{"제목":"(2, 3, 3) 구성에서 같은 방인 경우 세기","힌트":"$\\mathrm{A},\\ \\mathrm{B}$ 가 2명 방에 있을 때 남은 6명을 3명씩 나누는 방법은?","식":["2명 방: ${}_{6}\\mathrm{C}_{3}\\times{}_{3}\\mathrm{C}_{3}\\times\\dfrac{1}{2!}=10$","3명 방: ${}_{6}\\mathrm{C}_{1}\\times{}_{5}\\mathrm{C}_{3}\\times{}_{2}\\mathrm{C}_{2}=60$","$3!\\times(10+60)=420$"],"설명":"$\\mathrm{A},\\ \\mathrm{B}$ 가 2명 방이면 남은 6명이 같은 크기 두 묶음이 되어 $\\frac{1}{2!}$ 을 곱한다. 3명 방이면 $\\mathrm{A},\\ \\mathrm{B}$ 가 든 묶음이 다른 3명 묶음과 구별되므로 곱하지 않는다.","확인":"420","스킬":"C2"},{"제목":"구성별 경우의 수 합하기","힌트":"세 구성은 서로 겹치지 않으므로 더하면?","식":["$540+360+420=1320$"],"설명":"방 인원 구성이 다르면 서로 다른 배정이므로 세 경우를 모두 더한다.","확인":"1320","스킬":"C2"}]},"ns-05b02d3dc962":{"길":"특수문자와 알파벳의 개수 조합별로 나누어 자리와 문자를 고른다","단계":[{"제목":"문자 사용 개수의 경우 나누기","힌트":"특수문자와 알파벳은 각각 1개 이상 쓰고 중복할 수 없다. (특수문자 수, 알파벳 수) 로 가능한 쌍은?","식":["(특수문자, 알파벳) $=(1,1),\\ (1,2),\\ (2,1),\\ (2,2)$","수의 개수는 차례로 $2,\\ 1,\\ 1,\\ 0$"],"설명":"특수문자와 알파벳은 각각 두 종류뿐이고 중복해서 쓸 수 없으므로 각각 최대 $2$ 개이다. 전체 문자가 $4$ 개이므로 나머지 자리는 수로 채운다.","확인":null,"스킬":"C2"},{"제목":"특수문자와 알파벳이 1개씩인 경우 세기","고비":true,"힌트":"특수문자와 알파벳을 하나씩 고르고 자리에 놓은 뒤, 남은 두 자리를 수로 채우는 방법은?","식":["특수문자 $2\\times4=8$, 알파벳 $2\\times3=6$, 수 $2^{2}=4$","$8\\times6\\times4=192$"],"설명":"특수문자는 종류 $2$ 가지에 자리 $4$ 곳, 알파벳은 종류 $2$ 가지에 남은 자리 $3$ 곳이다. 남은 두 자리에는 수를 중복해서 쓸 수 있어 $2^{2}$ 이다.","확인":"192","스킬":"P4"},{"제목":"한쪽이 2개이고 다른 쪽이 1개인 경우 세기","힌트":"특수문자 1개, 알파벳 2개인 경우를 세면 특수문자 2개, 알파벳 1개인 경우는 어떨까?","식":["특수문자 1, 알파벳 2: $2\\times4\\times{}_{3}\\mathrm{P}_{2}\\times2=96$","특수문자 2, 알파벳 1 도 같은 방법으로 $96$"],"설명":"특수문자는 $2$ 가지에 자리 $4$ 곳, 알파벳 두 개는 남은 $3$ 자리 중 두 곳에 순서대로 놓아 ${}_{3}\\mathrm{P}_{2}$, 마지막 자리의 수는 $2$ 가지이다. 두 경우는 역할만 바뀌므로 개수가 같다. 여기서 확인할 값은 한 경우의 개수이다.","확인":"96","스킬":"P4"},{"제목":"특수문자와 알파벳이 2개씩인 경우 세기","힌트":"수가 없고 서로 다른 문자 네 개를 일렬로 놓으면?","식":["$4!=24$"],"설명":"네 자리가 모두 서로 다른 문자로 채워지므로 네 문자를 일렬로 나열하는 수와 같다.","확인":"24","스킬":"P4"},{"제목":"경우의 수 합하기","힌트":"네 경우를 모두 더하면?","식":["$192+96+96+24=408$"],"설명":"문자 개수의 조합이 다르면 서로 다른 암호이므로 모두 더한다.","확인":"408","스킬":"C2"}]},"ns-0ca77bd761e6":{"길":"매번 x 좌표가 1 씩 늘어야 하니 점프를 세 종류로 제한해 횟수별로 센다","단계":[{"제목":"허용되는 점프의 종류 찾기","힌트":"$x$ 좌표가 $6$ 번 만에 $0$ 에서 $6$ 이 되려면 한 번에 $x$ 좌표는 얼마씩 변해야 할까?","식":["$x$ 좌표 변화량의 합이 $6$, 한 번에 변화량은 최대 $1$","매번 $x$ 좌표가 $1$ 씩 증가","가능한 점프: $(1,0),\\ (1,1),\\ (1,-1)$"],"설명":"점프의 길이가 $1$ 또는 $\\sqrt{2}$ 이면 $x$ 좌표는 한 번에 최대 $1$ 만 변한다. $6$ 번으로 $6$ 만큼 가야 하므로 모든 점프에서 $x$ 좌표가 $1$ 씩 늘어난다.","확인":null,"스킬":"P3"},{"제목":"위·아래 점프 횟수의 조건 정하기","힌트":"$y$ 좌표가 처음과 끝에서 같으려면 $(1,1)$ 점프와 $(1,-1)$ 점프의 횟수는 어떤 관계이고, 각각 최대 몇 번까지 가능할까?","식":["$(1,1)$ 점프와 $(1,-1)$ 점프를 각각 $k$ 번","$(1,0)$ 점프는 $6-2k$ 번","$6-2k\\ge0$ 이므로 $k=0,\\ 1,\\ 2,\\ 3$"],"설명":"$y$ 좌표가 올라간 만큼 내려가야 하므로 두 점프의 횟수는 같다. 나머지 점프는 $(1,0)$ 이므로 $6-2k$ 번이고 이 값이 $0$ 이상이어야 한다.","확인":"3","스킬":"P4"},{"제목":"k 별로 점프 순서 나열하기","고비":true,"힌트":"같은 점프끼리는 구별하지 않고 세 종류를 일렬로 나열하는 방법은?","식":["$k=0:\\ \\dfrac{6!}{6!}=1$","$k=1:\\ \\dfrac{6!}{1!\\,1!\\,4!}=30$","$k=2:\\ \\dfrac{6!}{2!\\,2!\\,2!}=90$","$k=3:\\ \\dfrac{6!}{3!\\,3!}=20$"],"설명":"같은 것이 있는 순열이므로 전체 $6!$ 을 같은 점프의 횟수의 팩토리얼로 나눈다. 경로가 다르면 다른 경우이므로 점프의 순서를 모두 센다.","확인":null,"스킬":"P4"},{"제목":"k 별 경우의 수 합하기","힌트":"$k$ 의 값이 다르면 서로 다른 경우이므로 모두 더하면?","식":["$1+30+90+20=141$"],"설명":"$k$ 가 다르면 점프의 구성이 달라 겹치지 않으므로 네 경우를 더한다.","확인":"141","스킬":"P4"}]},"ns-0f571bcddf0f":{"길":"한 사람의 자리를 고정해 회전을 없애고 부부를 마주 보는 두 자리에 차례로 앉힌다","단계":[{"제목":"한 부부의 자리 고정하기","힌트":"원탁에서 한 사람의 자리를 정하면 그 배우자의 자리는 몇 가지로 정해지고, 마주 보는 빈 자리쌍은 몇 쌍 남을까?","식":["첫 부부: 한 사람의 자리를 고정하면 배우자는 맞은편 $1$ 가지","마주 보는 빈 자리쌍 $2$ 쌍"],"설명":"원탁은 회전하여 일치하는 것을 같게 보므로 한 사람의 자리를 고정한다. 부부는 마주 보고 앉아야 하므로 배우자의 자리는 맞은편으로 정해지고, 6자리 중 4자리가 마주 보는 두 쌍으로 남는다.","확인":"2","스킬":"P3"},{"제목":"두 번째 부부 앉히기","고비":true,"힌트":"남은 마주 보는 자리쌍 중 하나를 고른 뒤 부부 두 사람을 그 두 자리에 앉히는 방법은?","식":["자리쌍 선택 $2$ 가지","부부 두 사람의 앉는 순서 $2$ 가지","$2\\times2=4$"],"설명":"두 번째 부부가 앉을 마주 보는 자리쌍을 고르고, 그 두 자리에 남편과 아내를 앉히는 순서를 곱한다.","확인":"4","스킬":"P3"},{"제목":"세 번째 부부 앉히고 곱하기","힌트":"마지막 자리쌍에 부부가 앉는 방법을 구해 앞의 경우와 곱하면?","식":["마지막 자리쌍에 앉는 순서 $2$ 가지","$4\\times2=8$"],"설명":"남은 자리쌍은 하나뿐이므로 부부가 앉는 순서만 정하면 된다. 앞 단계의 경우의 수에 곱한다.","확인":"8","스킬":"P3"}]},"ns-10591963243c":{"길":"상자마다 1개씩 먼저 넣는 개수와 남은 구슬이 들어갈 상자 수를 센다","단계":[{"제목":"(가) 구하기: 먼저 넣는 구슬의 개수","힌트":"$k$ 개의 상자에 1개씩 먼저 넣으려면 구슬이 몇 개 필요할까?","식":["상자 $k$ 개에 $1$ 개씩: 구슬 $k$ 개","$f(k)=k$"],"설명":"구슬이 서로 같으므로 어느 구슬 $k$ 개를 고르든 방법은 $1$ 가지이다. 상자마다 한 개씩 넣는 데 필요한 구슬은 상자 수와 같다.","확인":null,"스킬":"P3"},{"제목":"(나) 구하기: 남은 구슬이 들어갈 상자 수","고비":true,"힌트":"남은 구슬은 상자 몇 개 중에 나누어 넣게 되고, 구슬이 들어가는 상자는 최대 몇 개일까?","식":["남은 $n-k$ 개를 $1$ 개, $2$ 개, $\\cdots$, $g(k)$ 개의 상자에 나누어 넣는다","상자는 모두 $k$ 개이므로 $g(k)=k$"],"설명":"남은 구슬이 들어갈 수 있는 상자는 전체 상자 수 $k$ 를 넘을 수 없다. 따라서 남은 구슬을 최대 $k$ 개의 상자에 나누어 넣는 경우까지 더하는 식이다.","확인":null,"스킬":"P3"},{"제목":"k = 10 일 때 합 구하기","힌트":"$f(k)=k,\\ g(k)=k$ 에 $k=10$ 을 넣어 더하면?","식":["$f(10)+g(10)=10+10=20$"],"설명":"구한 두 식에 $k=10$ 을 대입해 더한다.","확인":"20","스킬":"P3"}]},"ns-12ad7ae26a29":{"길":"각 꽃을 1개 이상 넣는 전체 경우에서 한 종류가 8개 이상인 경우를 뺀다","단계":[{"제목":"각 종류 1개 이상인 전체 경우 구하기","힌트":"튤립·장미·백합의 수를 $x,\\ y,\\ z$ 로 두고 각각 $1$ 개씩 먼저 빼 두면 어떤 방정식이 될까?","식":["$x+y+z=12\\ (x,\\,y,\\,z\\ge1)$","$x-1=X,\\ y-1=Y,\\ z-1=Z$ 로 두면 $X+Y+Z=9\\ (X,\\,Y,\\,Z\\ge0)$","${}_{3}\\mathrm{H}_{9}={}_{11}\\mathrm{C}_{9}=55$"],"설명":"각 종류를 최소 한 개씩 넣은 뒤 남은 $9$ 개를 세 종류에 나누어 넣는 중복조합이다. 음이 아닌 정수해의 개수는 ${}_{3}\\mathrm{H}_{9}$ 이다.","확인":"55","스킬":"P3"},{"제목":"한 종류가 8개 이상인 경우 구하기","고비":true,"힌트":"튤립이 $8$ 개 이상이면 $x-8$ 을 새 문자로 두었을 때 합은 얼마이고, 두 종류가 동시에 $8$ 개 이상일 수 있을까?","식":["$x\\ge8$: $x-8=X'$ 로 두면 $X'+Y+Z=2$, ${}_{3}\\mathrm{H}_{2}={}_{4}\\mathrm{C}_{2}=6$","장미, 백합이 $8$ 개 이상인 경우도 각각 $6$","두 종류가 모두 $8$ 개 이상이면 $8+8+1=17>12$ 이므로 불가능","$3\\times6=18$"],"설명":"한 종류가 $8$ 개 이상인 경우는 세 종류가 서로 같은 방식으로 세어진다. 두 종류가 동시에 $8$ 개 이상이면 합이 $12$ 를 넘으므로 겹치는 경우는 없어 단순히 더하면 된다.","확인":"18","스킬":"P2"},{"제목":"여사건으로 조건에 맞는 경우 구하기","힌트":"전체 경우에서 한 종류가 $8$ 개 이상인 경우를 빼면?","식":["$55-18=37$"],"설명":"같은 종류의 꽃이 최대 $7$ 개라는 조건을 어기는 경우를 전체에서 뺀다.","확인":"37","스킬":"P2"}]},"ns-12e7a50600a0":{"길":"짝수 눈만 이동하므로 이동 칸의 합이 100 이 되는 눈의 조합을 찾아 배열한다","단계":[{"제목":"눈의 수별 이동 칸 구하기","힌트":"$(2i)^{n}$ 이 실수가 되는 $n$ 은 어떤 수이고, 그때 $|z^{n}|$ 은 얼마일까?","식":["$(2i)^{2}=-4,\\ (2i)^{4}=16,\\ (2i)^{6}=-64$","홀수 $n$ 에서는 $(2i)^{n}$ 이 허수이므로 이동하지 않는다","이동 칸: 눈 $2,\\ 4,\\ 6$ 일 때 $4,\\ 16,\\ 64$"],"설명":"$i^{2}=-1$ 이므로 $n$ 이 짝수일 때만 $(2i)^{n}$ 이 실수이다. 이때 절댓값은 $2^{n}$ 이므로 눈이 $2,\\ 4,\\ 6$ 이면 각각 $4,\\ 16,\\ 64$ 칸을 이동한다.","확인":null,"스킬":"C6"},{"제목":"이동 칸의 합이 100 인 조합 찾기","고비":true,"힌트":"눈 $2,\\ 4,\\ 6$ 이 나온 횟수를 각각 $a,\\ b,\\ c$ 로 두면 $4a+16b+64c=100$ 이다. 던진 횟수 $5$ 이하에서 가능한 $(a,\\ b,\\ c)$ 의 합 $a+b+c$ 는?","식":["$4a+16b+64c=100$ 에서 $a+4b+16c=25$","$c=1$ 이면 $a+4b=9$ 이고 $a+b\\le4$ 이므로 $(a,\\ b)=(1,\\ 2)$","$c=0$ 이면 $a+4b=25$ 에서 $a+b\\ge7$ 이라 불가능","눈 $2,\\ 4,\\ 4,\\ 6$ 이 나온 경우이고 짝수 눈은 $4$ 번"],"설명":"$c\\ge2$ 이면 $64\\times2>100$ 이라 불가능하다. $c=1$ 일 때만 던진 횟수 $5$ 이하의 해가 나오며, 짝수 눈 $2,\\ 4,\\ 4,\\ 6$ 과 홀수 눈 한 번으로 $5$ 번이 채워진다.","확인":"4","스킬":"C6"},{"제목":"홀수 눈이 나오는 순서와 값 정하기","힌트":"다섯 번째 던진 뒤에 반드시 이동했으므로 홀수 눈은 몇 번째 던지기에 나올 수 있고, 값은 몇 가지일까?","식":["다섯 번째는 짝수 눈이어야 하므로 홀수 눈의 위치는 처음 $4$ 번 중 하나: $4$ 가지","홀수 눈의 값: $1,\\ 3,\\ 5$ 중 하나: $3$ 가지","$4\\times3=12$"],"설명":"마지막 던지기에서 말이 움직였으므로 다섯 번째 눈은 짝수이다. 홀수 눈은 앞의 네 번 중 한 번에 나오고 그 값은 $1,\\ 3,\\ 5$ 중에서 고른다.","확인":"12","스킬":"P3"},{"제목":"나머지 짝수 눈의 배열과 곱","힌트":"남은 네 자리에 $2,\\ 4,\\ 4,\\ 6$ 을 놓는 방법을 구하고 앞 단계의 경우의 수와 곱하면?","식":["$\\dfrac{4!}{2!}=12$","$12\\times12=144$"],"설명":"같은 눈 $4$ 가 두 번 들어 있으므로 같은 것이 있는 순열로 센다. 홀수 눈의 위치와 값을 정한 경우마다 짝수 눈의 배열이 하나씩 이어지므로 곱한다.","확인":"144","스킬":"P3"}]},"ns-137aab21a2bf":{"길":"흰 공을 나누는 형태로 경우를 나눈 뒤 빈 주머니에 노란 공을 1개 이상씩 넣는다","단계":[{"제목":"흰 공을 나누는 형태와 빈 주머니 수 정리하기","힌트":"흰 공 $4$ 개를 세 주머니에 나누는 형태를 개수 순으로 쓰면, 각 형태에서 빈 주머니는 몇 개이고 주머니 배정은 몇 가지일까?","식":["$(4,0,0)$: $3$ 가지, 빈 주머니 $2$ 개","$(3,1,0)$: $3!=6$ 가지, 빈 주머니 $1$ 개","$(2,2,0)$: $3$ 가지, 빈 주머니 $1$ 개","$(2,1,1)$: $3$ 가지, 빈 주머니 없음"],"설명":"흰 공은 구별하지 않으므로 개수의 형태를 나눈 뒤 각 형태를 주머니에 배정한다. 숫자가 모두 다르면 $3!$, 같은 숫자가 둘이면 $3$ 가지이다. 흰 공이 없는 주머니는 노란 공이 반드시 들어가야 한다.","확인":null,"스킬":"C2"},{"제목":"형태별 노란 공의 배분 수 구하기","고비":true,"힌트":"빈 주머니에 노란 공을 $1$ 개씩 먼저 넣고 나면 남은 노란 공을 세 주머니에 나누어 넣는 중복조합은 어떻게 될까?","식":["빈 주머니 $2$ 개: ${}_{3}\\mathrm{H}_{3}={}_{5}\\mathrm{C}_{3}=10$","빈 주머니 $1$ 개: ${}_{3}\\mathrm{H}_{4}={}_{6}\\mathrm{C}_{4}=15$","빈 주머니 없음: ${}_{3}\\mathrm{H}_{5}={}_{7}\\mathrm{C}_{5}=21$"],"설명":"빈 주머니 하나당 노란 공을 $1$ 개씩 먼저 넣으면 남는 공은 $5-($빈 주머니 수$)$ 개이다. 남은 공은 제한 없이 세 주머니에 넣을 수 있으므로 중복조합 ${}_{3}\\mathrm{H}_{r}$ 이다.","확인":null,"스킬":"P3"},{"제목":"형태별 경우의 수 곱하기","힌트":"흰 공의 배정 수와 노란 공의 배분 수를 형태마다 곱하면?","식":["$(4,0,0):\\ 3\\times10=30$","$(3,1,0):\\ 6\\times15=90$","$(2,2,0):\\ 3\\times15=45$","$(2,1,1):\\ 3\\times21=63$"],"설명":"흰 공을 넣는 방법과 노란 공을 넣는 방법은 차례로 이어지는 일이므로 곱한다.","확인":null,"스킬":"P3"},{"제목":"형태별 경우의 수 합하기","힌트":"네 형태는 서로 겹치지 않으므로 더하면?","식":["$30+90+45+63=228$"],"설명":"흰 공의 형태가 다르면 서로 다른 경우이므로 모두 더한다.","확인":"228","스킬":"C2"}]},"ns-13b3f0fe61fd":{"길":"각 자리를 2 로 나눠 합이 5 인 경우를 세고 첫 자리가 0 인 경우를 뺀다","단계":[{"제목":"각 자리를 2 로 나눠 방정식으로 바꾸기","힌트":"각 자리의 숫자를 $2$ 로 나눈 값을 $x_{1},\\ x_{2},\\ \\cdots,\\ x_{5}$ 로 두면 합과 범위는 어떻게 될까?","식":["$x_{1}+x_{2}+x_{3}+x_{4}+x_{5}=5$","$x_{i}$ 는 $0,\\ 1,\\ 2,\\ 3$ 중 하나","다섯 자리 자연수이므로 $x_{1}\\ne0$"],"설명":"숫자 $0,\\ 2,\\ 4,\\ 6$ 을 $2$ 로 나누면 $0,\\ 1,\\ 2,\\ 3$ 이고 합 $10$ 은 $5$ 로 바뀐다. 첫 자리는 $0$ 이 될 수 없다.","확인":null,"스킬":"A2"},{"제목":"첫 자리 조건 없이 해의 개수 구하기","고비":true,"힌트":"음이 아닌 정수해의 개수에서 어떤 $x_{i}$ 가 $4$ 이상인 경우를 빼면?","식":["${}_{5}\\mathrm{H}_{5}={}_{9}\\mathrm{C}_{5}=126$","$x_{i}\\ge4$ 인 경우: $x_{i}-4$ 를 새 문자로 두면 합이 $1$ 이므로 ${}_{5}\\mathrm{H}_{1}=5$","$126-5\\times5=101$"],"설명":"$x_{i}$ 가 $3$ 을 넘는 경우를 전체에서 뺀다. 합이 $5$ 이므로 두 문자가 동시에 $4$ 이상일 수는 없어 겹치는 경우는 없다.","확인":"101","스킬":"P2"},{"제목":"첫 자리가 0 인 경우 구하기","힌트":"$x_{1}=0$ 이면 나머지 네 문자의 합이 $5$ 이고 각각 $3$ 이하일 때 해는 몇 개일까?","식":["${}_{4}\\mathrm{H}_{5}={}_{8}\\mathrm{C}_{5}=56$","$x_{i}\\ge4$ 인 경우: ${}_{4}\\mathrm{H}_{1}=4$ 가 $4$ 개 문자에서 $16$","$56-16=40$"],"설명":"첫 자리가 $0$ 이면 남은 네 자리가 같은 조건을 만족해야 한다. 앞 단계와 같은 방법으로 $3$ 을 넘는 경우를 뺀다.","확인":"40","스킬":"P2"},{"제목":"다섯 자리 자연수의 개수 구하기","힌트":"첫 자리 조건 없이 센 개수에서 첫 자리가 $0$ 인 개수를 빼면?","식":["$101-40=61$"],"설명":"첫 자리가 $0$ 인 경우는 다섯 자리 자연수가 아니므로 전체에서 뺀다.","확인":"61","스킬":"P2"}]},"ns-141ceb4a0d79":{"길":"f(k) 를 조합의 곱으로 쓰고 이웃한 값의 비를 비교해 최대가 되는 k 를 찾는다","단계":[{"제목":"f(k) 를 조합의 곱으로 나타내기","힌트":"두 번째로 작은 수가 $k$ 이면 $k$ 보다 작은 수와 큰 수는 각각 몇 개씩 뽑을까?","식":["$k$ 보다 작은 수 $1$ 개: $1$ 부터 $k-1$ 까지 ${}_{k-1}\\mathrm{C}_{1}$","$k$ 보다 큰 수 $2$ 개: $k+1$ 부터 $10$ 까지 ${}_{10-k}\\mathrm{C}_{2}$","$f(k)=(k-1)\\times\\dfrac{(10-k)(9-k)}{2}=\\dfrac{1}{2}(k-1)(9-k)(10-k)$"],"설명":"$k$ 가 둘째로 작으려면 $k$ 보다 작은 수가 정확히 한 개, 큰 수가 두 개이다. 각 선택은 이어서 하는 일이므로 곱한다.","확인":null,"스킬":"P4"},{"제목":"이웃한 값의 비로 증가·감소 경계 구하기","고비":true,"힌트":"$\\dfrac{f(k)}{f(k-1)}\\ge1$ 이 성립하는 $k$ 의 범위는?","식":["$\\dfrac{f(k)}{f(k-1)}=\\dfrac{(k-1)(9-k)}{(k-2)(11-k)}$","$\\ge1$ 이면 $(k-1)(9-k)\\ge(k-2)(11-k)$","$-k^{2}+10k-9\\ge-k^{2}+13k-22$ 에서 $k\\le\\dfrac{13}{3}$"],"설명":"$f(k)$ 가 직전 값 이상이 되는 조건을 정리하면 $k$ 의 이차항이 사라져 일차 부등식이 된다. 이 범위를 경계로 $f$ 의 증가와 감소가 갈린다.","확인":"13/3","스킬":"D13"},{"제목":"최댓값이 되는 k 정하기","힌트":"$k\\le\\dfrac{13}{3}$ 인 정수 $k$ 에서 $f$ 는 늘고 그 뒤에는 줄어든다면 가장 큰 값은 어디에서 나올까?","식":["$f(1)\\le f(2)\\le f(3)\\le f(4)$","$f(4)\\ge f(5)\\ge f(6)\\ge\\cdots\\ge f(10)$","최댓값은 $f(4)$"],"설명":"$f(1)=0$ 이므로 $f(1)\\le f(2)$ 이고, $2\\le k\\le4$ 에서는 비가 $1$ 이상이라 값이 늘어난다. $k\\ge5$ 에서는 비가 $1$ 보다 작아 값이 줄어든다.","확인":"4","스킬":"D13"},{"제목":"f(4) 의 값 구하기","힌트":"$f(k)=\\dfrac{1}{2}(k-1)(9-k)(10-k)$ 에 $k=4$ 를 넣으면?","식":["$f(4)=\\dfrac{1}{2}\\times3\\times5\\times6=45$"],"설명":"최댓값이 되는 $k=4$ 를 식에 대입한다.","확인":"45","스킬":"P4"}]},"ns-1473f0304a90":{"길":"가장 많은 노랑 3개를 이웃하지 않게 놓고 남은 칸에 파랑을 이웃하지 않게 넣는다","단계":[{"제목":"노랑 3개가 이웃하지 않는 자리 찾기","힌트":"여섯 칸 중 서로 이웃하지 않는 세 칸을 고르는 방법은 모두 몇 가지일까?","식":["$\\{1,3,5\\},\\ \\{2,4,6\\},\\ \\{1,3,6\\},\\ \\{1,4,6\\}$"],"설명":"노랑이 세 개로 가장 많아 먼저 놓는다. 여섯 칸에서 어느 두 칸도 연속하지 않게 세 칸을 고르면 네 가지뿐이다.","확인":"4","스킬":"P4"},{"제목":"남은 칸에 빨강·파랑 넣는 경우 세기","고비":true,"힌트":"남은 세 칸에 빨강 $1$ 개, 파랑 $2$ 개를 파랑끼리 이웃하지 않게 넣는 방법은 자리 조합마다 몇 가지일까?","식":["$\\{1,3,5\\}$: 남은 칸 $2,4,6$ 은 서로 떨어져 있어 빨강 자리 $3$ 가지","$\\{2,4,6\\}$: 남은 칸 $1,3,5$ 도 $3$ 가지","$\\{1,3,6\\}$: 남은 칸 $2,4,5$ 에서 $4,5$ 가 이웃이라 파랑이 둘 다 들어가는 경우를 빼 $2$ 가지","$\\{1,4,6\\}$: 남은 칸 $2,3,5$ 에서 $2,3$ 이 이웃이라 $2$ 가지"],"설명":"남은 칸 중 이웃한 두 칸이 있으면 그 두 칸에 파랑이 함께 들어가는 경우가 빠진다. 빨강을 넣을 칸만 정하면 나머지 두 칸은 파랑이므로 빨강의 자리를 센다.","확인":null,"스킬":"P4"},{"제목":"자리 조합별 경우의 수 합하기","힌트":"네 가지 노랑 자리마다 센 값을 더하면?","식":["$3+3+2+2=10$"],"설명":"노랑 자리가 다르면 서로 다른 배열이므로 모두 더한다.","확인":"10","스킬":"P4"}]},"ns-1574a3301aef":{"길":"각 보기를 분할의 뜻과 점화식으로 따져 참과 거짓을 가른다","단계":[{"제목":"ㄱ 판정: n−1 개로 분할하는 모양 찾기","힌트":"원소 $n$ 개를 부분집합 $n-1$ 개로 나누려면 어떤 부분집합이 몇 개의 원소를 가질까?","식":["$n-1$ 개로 분할하면 한 부분집합만 원소가 $2$ 개이고 나머지는 $1$ 개씩","두 원소를 고르는 방법: ${}_{n}\\mathrm{C}_{2}$","$S(n,\\ n-1)={}_{n}\\mathrm{C}_{2}$ 이므로 ㄱ 은 참"],"설명":"원소 $n$ 개를 $n-1$ 개의 부분집합으로 나누면 한 부분집합에만 원소가 두 개 들어간다. 그 두 원소를 고르면 분할이 정해진다.","확인":null,"스킬":"C3"},{"제목":"ㄴ 판정: S(7, 3) 을 S(6, ·) 로 나타내기","고비":true,"힌트":"일곱 번째 원소가 혼자 한 부분집합이 되는 경우와 기존 세 부분집합 중 하나에 들어가는 경우로 나누면?","식":["혼자인 경우: $S(6,\\ 2)$","기존 세 부분집합 중 하나에 넣는 경우: $3S(6,\\ 3)$","$S(7,\\ 3)=S(6,\\ 2)+3S(6,\\ 3)$"],"설명":"$S(7,\\ 3)$ 에는 $3S(6,\\ 3)$ 이 더해지므로 $S(6,\\ 2)+S(6,\\ 3)$ 보다 $2S(6,\\ 3)$ 만큼 크다. $S(6,\\ 3)>0$ 이므로 두 값은 같을 수 없고 ㄴ 은 거짓이다.","확인":null,"스킬":"C3"},{"제목":"ㄷ 판정: 반례 찾기","힌트":"$S(6,\\ 5)$ 를 ㄱ 의 결과로 구해 $S(6,\\ 3)=90$ 과 비교하면?","식":["$S(6,\\ 5)={}_{6}\\mathrm{C}_{2}=15$","$3<5<6$ 이지만 $S(6,\\ 5)=15<S(6,\\ 3)=90$"],"설명":"$k_{1}=3,\\ k_{2}=5,\\ n=6$ 일 때 $S(n,\\ k_{1})<S(n,\\ k_{2})$ 가 성립하지 않는 반례이다. 따라서 ㄷ 은 거짓이다.","확인":"15","스킬":"C3"},{"제목":"참인 보기 정리하기","힌트":"세 보기 중 참인 것은 무엇일까?","식":["ㄱ 참, ㄴ 거짓, ㄷ 거짓","옳은 것은 ㄱ"],"설명":"참으로 판정된 보기는 ㄱ 하나이다.","확인":null,"스킬":"C3"}]},"ns-1637d9c51573":{"길":"고르는 흰 돌과 검은 돌의 개수 조합마다 중복조합을 곱해 더한다","단계":[{"제목":"흰 돌과 검은 돌 개수의 조합 나누기","힌트":"흰 돌과 검은 돌이 각각 $4$ 개씩뿐일 때, 합이 $5$ 개가 되는 (흰, 검은) 조합은 몇 가지일까?","식":["(흰, 검은) $=(4,1),\\ (3,2),\\ (2,3),\\ (1,4)$"],"설명":"각 색은 $4$ 개씩만 있으므로 한 색으로 $5$ 개를 고를 수 없다. 두 색의 개수는 모두 $1$ 이상 $4$ 이하이다.","확인":"4","스킬":"C2"},{"제목":"조합별로 그릇에 넣는 방법 구하기","고비":true,"힌트":"같은 색의 돌은 구별되지 않고 빈 그릇이 가능하므로 색마다 세 그릇에 넣는 방법을 중복조합으로 세어 곱하면?","식":["$(4,1):\\ {}_{3}\\mathrm{H}_{4}\\times{}_{3}\\mathrm{H}_{1}=15\\times3=45$","$(3,2):\\ {}_{3}\\mathrm{H}_{3}\\times{}_{3}\\mathrm{H}_{2}=10\\times6=60$","$(2,3):\\ {}_{3}\\mathrm{H}_{2}\\times{}_{3}\\mathrm{H}_{3}=6\\times10=60$","$(1,4):\\ {}_{3}\\mathrm{H}_{1}\\times{}_{3}\\mathrm{H}_{4}=3\\times15=45$"],"설명":"구별되지 않는 돌 $r$ 개를 세 그릇에 넣는 방법은 ${}_{3}\\mathrm{H}_{r}$ 이다. 흰 돌과 검은 돌을 넣는 일은 서로 독립이므로 곱한다.","확인":null,"스킬":"P3"},{"제목":"조합별 경우의 수 합하기","힌트":"네 조합은 서로 겹치지 않으므로 더하면?","식":["$45+60+60+45=210$"],"설명":"고르는 돌의 개수 조합이 다르면 서로 다른 경우이므로 모두 더한다.","확인":"210","스킬":"P3"}]},"ns-1764b4464db2":{"길":"밑면 색을 먼저 정하고 옆면 5개는 초록·노랑을 한 묶음으로 둔 원순열로 센다","단계":[{"제목":"밑면에 칠할 색 정하기","힌트":"초록과 노랑이 모두 옆면에 쓰이려면 밑면에 칠할 수 있는 색은 몇 가지일까?","식":["여섯 색을 모두 쓰므로 면 $6$ 개의 색이 모두 다르다","초록·노랑은 옆면이므로 밑면은 나머지 $4$ 가지 색 중 하나"],"설명":"밑면과 옆면 $5$ 개, 모두 $6$ 개의 면에 $6$ 가지 색을 한 번씩 쓴다. 초록과 노랑이 옆면에 와야 하므로 밑면의 색은 두 색을 뺀 나머지 중에서 고른다.","확인":"4","스킬":"P3"},{"제목":"초록·노랑을 묶어 옆면 원순열 세기","고비":true,"힌트":"옆면 $5$ 개는 밑면을 둘러싸고 있으므로 원형으로 놓인다. 초록·노랑을 한 묶음으로 보면 몇 개를 원형으로 배열할까?","식":["묶음 $1$ 개와 나머지 색 $3$ 개를 원형으로 배열: $(4-1)!=6$","묶음 안에서 초록·노랑의 순서: $2$ 가지","$6\\times2=12$"],"설명":"옆면은 한 바퀴 돌려 겹치는 배열을 같은 것으로 보는 원순열이다. 서로 이웃해야 하는 두 색을 한 묶음으로 보면 네 대상의 원순열이 되고, 묶음 안의 순서를 곱한다.","확인":"12","스킬":"P3"},{"제목":"밑면과 옆면의 경우의 수 곱하기","힌트":"밑면의 경우의 수와 옆면의 경우의 수를 곱하면?","식":["$4\\times12=48$"],"설명":"밑면의 색을 정하는 일과 옆면을 칠하는 일은 이어서 하는 일이므로 곱한다.","확인":"48","스킬":"P3"}]},"ns-1945f3c80a78":{"길":"양의 정수해의 개수 a_n 과 S(n, n−1) 을 구해 극한식에 대입한다","단계":[{"제목":"양의 정수해를 음이 아닌 정수해로 바꾸기","힌트":"$x,\\ y,\\ z$ 가 각각 $1$ 이상이므로 $1$ 씩 빼서 새 문자로 두면 방정식은 어떻게 될까?","식":["$x-1=X,\\ y-1=Y,\\ z-1=Z$ ($X,\\,Y,\\,Z\\ge0$)","$2X+Y+Z=4n^{2}-4$"],"설명":"양의 정수해의 개수는 각 문자에서 $1$ 을 뺀 음이 아닌 정수해의 개수와 같다. $2x+y+z$ 에서 상수가 $2+1+1=4$ 만큼 줄어든다.","확인":null,"스킬":"P3"},{"제목":"X 를 고정해 (Y, Z) 의 개수 구하기","힌트":"$X=k$ 로 고정하면 $Y+Z$ 의 값은 얼마이고, 그 음이 아닌 정수해는 몇 개일까?","식":["$X=k\\ (0\\le k\\le2n^{2}-2)$ 이면 $Y+Z=4n^{2}-4-2k$","${}_{2}\\mathrm{H}_{4n^{2}-4-2k}={}_{4n^{2}-3-2k}\\mathrm{C}_{1}=4n^{2}-3-2k$"],"설명":"$Y+Z=m$ 의 음이 아닌 정수해는 $m+1$ 개이다. $k$ 는 $2k\\le4n^{2}-4$ 를 만족해야 하므로 $0$ 부터 $2n^{2}-2$ 까지이다.","확인":null,"스킬":"P3"},{"제목":"k 에 대해 모두 더해 a_n 구하기","고비":true,"힌트":"$4n^{2}-3-2k$ 를 $k=0$ 부터 $2n^{2}-2$ 까지 더하면?","식":["항의 개수 $2n^{2}-1$, 처음 항 $4n^{2}-3$, 마지막 항 $1$","$\\displaystyle\\sum_{k=0}^{2n^{2}-2}(4n^{2}-3-2k)=(4n^{2}-3)(2n^{2}-1)-2\\times\\dfrac{(2n^{2}-2)(2n^{2}-1)}{2}$","$a_{n}=(2n^{2}-1)^{2}$"],"설명":"공통인수 $2n^{2}-1$ 을 묶으면 $(4n^{2}-3)-(2n^{2}-2)=2n^{2}-1$ 이 남아 완전제곱 꼴이 된다.","확인":null,"스킬":"P6"},{"제목":"S(n, n−1) 구하기","힌트":"원소 $n$ 개를 $n-1$ 개의 부분집합으로 나누면 원소가 $2$ 개인 부분집합은 몇 개일까?","식":["$n-1$ 개로 나누면 한 부분집합만 원소가 $2$ 개이고 나머지 $n-2$ 개는 원소가 $1$ 개","$S(n,\\ n-1)={}_{n}\\mathrm{C}_{2}=\\dfrac{1}{2}n(n-1)$"],"설명":"같은 부분집합에 들어갈 두 원소를 고르면 분할이 정해지므로 $n$ 개 중 $2$ 개를 고르는 조합의 수와 같다.","확인":null,"스킬":"C6"},{"제목":"극한 계산하기","힌트":"분모와 분자의 최고차항 $n^{4}$ 으로 분자·분모를 나누면?","식":["$\\dfrac{a_{n}}{n^{2}\\times S(n,\\ n-1)}=\\dfrac{(2n^{2}-1)^{2}}{n^{2}\\times\\frac{1}{2}n(n-1)}=\\dfrac{2(2n^{2}-1)^{2}}{n^{3}(n-1)}$","$=\\dfrac{2\\left(2-\\frac{1}{n^{2}}\\right)^{2}}{1-\\frac{1}{n}}$","$n\\to\\infty$ 이면 $\\dfrac{2\\times2^{2}}{1}=8$"],"설명":"분자와 분모가 모두 $n$ 에 대한 사차식이므로 $n^{4}$ 으로 나눈다. $\\frac{1}{n}$ 과 $\\frac{1}{n^{2}}$ 은 $0$ 으로 가까워진다.","확인":"8","스킬":"A11"}]},"ns-19d6404641db":{"길":"f(a) 가 정해지는 것을 이용해 나머지 세 원소가 1 과 3 을 모두 갖는 경우를 센다","단계":[{"제목":"f(a) 의 값 정하기","힌트":"$f(a)$ 는 짝수이고 치역에는 $4$ 가 없다. $f(a)$ 로 가능한 값은?","식":["$f(a)\\in\\{2,\\ 4\\}$","치역이 $\\{1,\\,2,\\,3\\}$ 이므로 $4$ 는 쓸 수 없다","$f(a)=2$"],"설명":"짝수인 함숫값은 $2$ 와 $4$ 이다. 치역이 $\\{1,\\,2,\\,3\\}$ 이라 $4$ 는 나올 수 없으므로 $f(a)=2$ 로 정해진다.","확인":"2","스킬":"P4"},{"제목":"b, c, d 의 함숫값 조건 정하기","힌트":"치역이 $\\{1,\\,2,\\,3\\}$ 이려면 $f(b),\\ f(c),\\ f(d)$ 는 어떤 값을 반드시 가져야 할까?","식":["$f(b),\\ f(c),\\ f(d)\\in\\{1,\\,2,\\,3\\}$","$2$ 는 $f(a)$ 로 이미 나왔으므로 $1$ 과 $3$ 이 반드시 나와야 한다"],"설명":"치역의 세 원소가 모두 나오려면 $1$ 과 $3$ 은 $b,\\ c,\\ d$ 의 함숫값 중에서 나와야 한다. $2$ 는 $f(b),\\ f(c),\\ f(d)$ 에 나와도 되고 안 나와도 된다.","확인":null,"스킬":"C2"},{"제목":"함숫값 구성별로 경우 나누어 세기","고비":true,"힌트":"$f(b),\\ f(c),\\ f(d)$ 의 값이 서로 모두 다른 경우와 두 개가 같은 경우로 나누면?","식":["$1,\\,2,\\,3$ 이 하나씩: $3!=6$","$1,\\,1,\\,3$ 또는 $1,\\,3,\\,3$: $({}_{3}\\mathrm{C}_{2}\\times{}_{1}\\mathrm{C}_{1})\\times2!=6$"],"설명":"세 값이 모두 다르면 $1,\\,2,\\,3$ 을 나열하는 순열이다. 두 값이 같으면 $1$ 과 $3$ 이 모두 있어야 하므로 같은 값은 $1$ 또는 $3$ 이고, 같은 값이 놓일 두 자리를 고른다.","확인":null,"스킬":"C2"},{"제목":"경우의 수 합하기","힌트":"두 경우를 더하면?","식":["$6+6=12$"],"설명":"함숫값의 구성이 다르면 서로 다른 함수이므로 더한다.","확인":"12","스킬":"C2"}]},"ns-1a193f252e94":{"길":"지성이 조가 2명인지 3명인지로 나누고 연아 조에 남자가 들어가는 경우를 센다","단계":[{"제목":"지성이 조의 크기로 경우 나누기","힌트":"지성이 조는 남자만 있으므로 조의 크기가 $2$ 명일 때와 $3$ 명일 때 같은 조에 들어갈 사람은 몇 명씩일까?","식":["$2$ 명 조: 지성이 + 남자 $1$ 명 → ${}_{3}\\mathrm{C}_{1}=3$ 가지","$3$ 명 조: 지성이 + 남자 $2$ 명 → ${}_{3}\\mathrm{C}_{2}=3$ 가지"],"설명":"지성이를 뺀 남자는 $3$ 명이다. 지성이 조에는 남자만 들어가므로 같은 조원을 이 $3$ 명 중에서 고른다.","확인":null,"스킬":"C2"},{"제목":"지성이 조가 2명인 경우 세기","고비":true,"힌트":"남은 $6$ 명(남자 $2$, 여자 $4$)을 $3$ 명씩 두 조로 나누는 방법에서 연아 조에 남자가 없는 경우를 빼면?","식":["$3$ 명씩 두 조: $\\dfrac{{}_{6}\\mathrm{C}_{3}}{2}=10$","연아 조에 남자가 없는 경우: 연아 + 여자 $2$ 명 → ${}_{3}\\mathrm{C}_{2}=3$","$3\\times(10-3)=21$"],"설명":"$3$ 명짜리 두 조는 서로 구별되지 않으므로 $2$ 로 나눈다. 연아 조가 여자만이면 조건 (나) 를 어기므로 그 경우를 제외한 뒤, 지성이와 함께 들어갈 남자의 선택 $3$ 가지를 곱한다.","확인":"21","스킬":"P4"},{"제목":"지성이 조가 3명인 경우 세기","힌트":"남은 $5$ 명(남자 $1$, 여자 $4$)을 $2$ 명 조와 $3$ 명 조로 나눌 때 연아 조에 남자가 있는 경우는?","식":["연아와 남자가 $2$ 명 조: $1$ 가지","연아와 남자가 $3$ 명 조: 여자 $1$ 명을 더 고른다 → ${}_{3}\\mathrm{C}_{1}=3$ 가지","$3\\times(1+3)=12$"],"설명":"남자는 한 명뿐이므로 연아와 같은 조에 있어야 한다. 그 조가 $2$ 명이면 둘만으로 정해지고, $3$ 명이면 남은 여자 $3$ 명 중 한 명이 더해진다. 지성이와 함께 들어갈 남자 선택 $3$ 가지를 곱한다.","확인":"12","스킬":"P4"},{"제목":"두 경우의 합 구하기","힌트":"지성이 조의 크기가 다른 두 경우를 더하면?","식":["$21+12=33$"],"설명":"지성이 조의 크기가 다르면 서로 다른 분할이므로 더한다.","확인":"33","스킬":"C2"}]},"ns-1b65e3a5e571":{"길":"특수문자가 1개일 때와 2개일 때로 나누어 자리와 수를 고른다","단계":[{"제목":"특수문자가 1개인 경우 세기","힌트":"특수문자의 종류와 자리를 정한 뒤, 남은 세 자리를 수로 채우는 방법은?","식":["특수문자 종류 $2$ 가지, 자리 $4$ 곳","남은 세 자리에 수: $4^{3}=64$","$2\\times4\\times64=512$"],"설명":"수는 중복해서 쓸 수 있으므로 남은 자리마다 $2,\\,4,\\,6,\\,8$ 중 어느 것이든 올 수 있어 $4^{3}$ 이다.","확인":"512","스킬":"P4"},{"제목":"특수문자가 2개인 경우 세기","고비":true,"힌트":"서로 다른 특수문자 두 개를 네 자리 중 두 곳에 놓는 방법과, 남은 두 자리에 수를 채우는 방법은?","식":["특수문자 두 개의 자리: $4\\times3=12$","남은 두 자리에 수: $4^{2}=16$","$12\\times16=192$"],"설명":"특수문자는 중복할 수 없고 두 종류를 모두 쓰므로 어느 문자가 어느 자리인지까지 정하는 순열 $4\\times3$ 이다. 남은 자리에는 수를 중복해서 쓸 수 있다.","확인":"192","스킬":"P4"},{"제목":"두 경우의 수 합하기","힌트":"특수문자 개수가 다른 두 경우를 더하면?","식":["$512+192=704$"],"설명":"특수문자의 개수가 다르면 서로 다른 암호이므로 더한다.","확인":"704","스킬":"P4"}]},"ns-1dab667f40d0":{"길":"파란 공 사이의 공이 2, 4, 6 개인 경우로 나누고 사이 구성별로 센다","단계":[{"제목":"파란 공 사이의 공 구성 모두 찾기","힌트":"파란 공이 이웃하지 않고 그 사이 공의 개수가 짝수이면 사이 공의 개수는 몇 개일 수 있고, 흰·검은 공의 구성은?","식":["사이 $2$ 개: 흰 $2$ / 검은 $2$ / 흰 $1$, 검은 $1$","사이 $4$ 개: 흰 $4$ / 흰 $3$, 검은 $1$ / 흰 $2$, 검은 $2$","사이 $6$ 개: 흰 $4$, 검은 $2$"],"설명":"이웃하지 않으므로 사이 공은 $0$ 개가 아니고, 짝수이므로 $2,\\,4,\\,6$ 개이다. 검은 공은 $2$ 개, 흰 공은 $4$ 개뿐이어서 가능한 구성은 모두 $7$ 가지이다.","확인":"7","스킬":"C2"},{"제목":"사이 공이 2개인 경우 세기","힌트":"파란 공 두 개와 그 사이 공을 한 묶음으로 보고, 묶음과 바깥 공을 나열하면?","식":["흰 $2$: 묶음, 흰 $2$, 검은 $2$ 나열 $\\dfrac{5!}{2!\\,2!}=30$","검은 $2$: 묶음, 흰 $4$ 나열 $\\dfrac{5!}{4!}=5$","흰 $1$ 검은 $1$: 사이 순서 $2$ × 묶음, 흰 $3$, 검은 $1$ 나열 $\\dfrac{5!}{3!}=20$ → $40$","$30+5+40=75$"],"설명":"파란 공 사이의 구성이 정해지면 묶음 하나를 한 대상으로 보고 같은 것이 있는 순열로 센다. 사이에 서로 다른 색이 하나씩 있으면 두 색의 순서가 $2$ 가지이다.","확인":"75","스킬":"P4"},{"제목":"사이 공이 4개인 경우 세기","고비":true,"힌트":"사이 공의 배열 수와 묶음·바깥 공의 나열 수를 곱해 세 구성을 각각 구하면?","식":["흰 $3$ 검은 $1$: 사이 배열 $\\dfrac{4!}{3!}=4$, 묶음·흰 $1$·검은 $1$ 나열 $3!=6$ → $24$","흰 $2$ 검은 $2$: 사이 배열 $\\dfrac{4!}{2!\\,2!}=6$, 묶음·흰 $2$ 나열 $\\dfrac{3!}{2!}=3$ → $18$","흰 $4$: 사이 배열 $1$, 묶음·검은 $2$ 나열 $\\dfrac{3!}{2!}=3$ → $3$","$24+18+3=45$"],"설명":"사이 공의 순서와 바깥 공의 나열을 모두 세므로 두 값을 곱한다. 바깥에 남는 공은 사이에 넣고 남은 흰·검은 공이다.","확인":"45","스킬":"P4"},{"제목":"사이 공이 6개인 경우 세기","힌트":"여섯 공 모두가 파란 공 사이에 있으면 사이 배열은 몇 가지일까?","식":["사이 배열: $\\dfrac{6!}{4!\\,2!}=15$","바깥에는 공이 없으므로 묶음 하나뿐: $1$"],"설명":"흰 공 $4$ 개, 검은 공 $2$ 개가 모두 사이에 들어가므로 파란 공이 양 끝에 놓인다. 여섯 공을 나열하는 수가 곧 경우의 수이다.","확인":"15","스킬":"P4"},{"제목":"사이 공 개수별 경우의 수 합하기","힌트":"사이 공이 $2$ 개, $4$ 개, $6$ 개인 경우를 모두 더하면?","식":["$75+45+15=135$"],"설명":"사이 공의 개수가 다르면 서로 다른 배열이므로 모두 더한다.","확인":"135","스킬":"C2"}]},"ns-24c93b147d68":{"길":"전체 일대일 대응에서 제자리에 가는 원소가 있는 경우를 포함배제로 뺀다","단계":[{"제목":"전체 일대일 대응의 개수 구하기","힌트":"$X$ 에서 $X$ 로의 일대일 대응은 다섯 원소를 일렬로 놓는 순열과 같다. 모두 몇 개일까?","식":["$5!=120$"],"설명":"다섯 원소의 함숫값을 서로 다르게 정하는 방법은 다섯 원소를 나열하는 순열의 수와 같다.","확인":"120","스킬":"P2"},{"제목":"제자리에 가는 원소 수별 경우 구하기","고비":true,"힌트":"특정한 $k$ 개의 원소가 $f(x)=x$ 이면 나머지는 몇 가지로 정해지고, $k$ 개를 고르는 방법은?","식":["$k=1:\\ {}_{5}\\mathrm{C}_{1}\\times4!=120,\\quad k=2:\\ {}_{5}\\mathrm{C}_{2}\\times3!=60$","$k=3:\\ {}_{5}\\mathrm{C}_{3}\\times2!=20,\\quad k=4:\\ {}_{5}\\mathrm{C}_{4}\\times1!=5$","$k=5:\\ {}_{5}\\mathrm{C}_{5}\\times0!=1$"],"설명":"정해진 $k$ 개가 제자리이면 나머지 $5-k$ 개는 자유롭게 대응하므로 $(5-k)!$ 이고, 제자리에 갈 $k$ 개를 고르는 방법을 곱한다.","확인":null,"스킬":"P2"},{"제목":"포함배제로 제자리가 없는 경우 구하기","힌트":"전체에서 $k=1$ 은 빼고 $k=2$ 는 더하는 식으로 부호를 번갈아 놓으면?","식":["$120-120+60-20+5-1=44$"],"설명":"제자리에 가는 원소가 하나 이상인 경우를 포함배제로 세어 전체에서 빼면 된다. 겹쳐 센 만큼 부호를 번갈아 더하고 뺀다.","확인":"44","스킬":"P2"}]},"ns-29d7c5557cb7":{"길":"소인수 6개를 빈 묶음 없이 세 묶음으로 나누는 방법의 수로 바꾼다","단계":[{"제목":"30030 을 소인수분해하기","힌트":"$30030$ 을 소수의 곱으로 나타내면 서로 다른 소수는 몇 개일까?","식":["$30030=2\\times3\\times5\\times7\\times11\\times13$","서로 다른 소수 $6$ 개의 곱"],"설명":"$2,\\ 3,\\ 5,\\ 7,\\ 11,\\ 13$ 을 곱하면 $30030$ 이 되고 같은 소수는 반복되지 않는다.","확인":"6","스킬":"N1"},{"제목":"세 자연수의 곱을 소수의 묶음으로 바꾸기","힌트":"$30030$ 을 $1$ 보다 큰 세 수의 곱으로 나타낸다면 여섯 소수는 각각 어느 수에 들어갈까?","식":["각 소수는 세 수 중 정확히 하나에 들어간다","세 수가 모두 $1$ 보다 크므로 빈 묶음이 없다","곱의 순서는 구별하지 않으므로 묶음의 순서도 구별하지 않는다"],"설명":"같은 소수는 한 번뿐이라 어느 한 수에만 들어가야 한다. 세 수가 $1$ 보다 크려면 각 수에 소수가 하나 이상 들어간다. 곱으로 나타내는 방법은 수의 순서와 무관하므로 소수 $6$ 개를 순서 없는 세 묶음으로 나누는 수이다.","확인":null,"스킬":"P3"},{"제목":"묶음 크기별로 나누는 방법 세기","고비":true,"힌트":"여섯 개를 세 묶음으로 나누는 크기의 조합은 무엇이고, 같은 크기의 묶음이 있으면 어떻게 처리할까?","식":["$(4,1,1):\\ {}_{6}\\mathrm{C}_{4}=15$","$(3,2,1):\\ {}_{6}\\mathrm{C}_{3}\\times{}_{3}\\mathrm{C}_{2}=60$","$(2,2,2):\\ \\dfrac{{}_{6}\\mathrm{C}_{2}\\times{}_{4}\\mathrm{C}_{2}\\times{}_{2}\\mathrm{C}_{2}}{3!}=15$"],"설명":"크기가 같은 묶음끼리는 순서를 구별하지 않으므로 같은 크기의 묶음 수의 팩토리얼로 나눈다. $(4,1,1)$ 은 큰 묶음을 고르면 나머지 두 개는 하나씩 남아 순서가 필요 없다.","확인":null,"스킬":"P3"},{"제목":"크기별 경우의 수 합하기","힌트":"세 가지 크기 조합은 서로 겹치지 않으므로 더하면?","식":["$15+60+15=90$"],"설명":"묶음의 크기 조합이 다르면 서로 다른 곱셈식이므로 모두 더한다.","확인":"90","스킬":"P3"}]},"ns-2a838b1c4f08":{"길":"전체 함수에서 치역에 빠진 값이 있는 함수를 포함배제로 뺀다","단계":[{"제목":"전체 함수의 개수 구하기","힌트":"$X$ 의 원소 $6$ 개가 각각 $Y$ 의 원소 $3$ 개 중 하나에 대응하면 함수는 모두 몇 개일까?","식":["$3^{6}=729$"],"설명":"원소마다 대응할 수 있는 값이 $3$ 가지이고 서로 독립이므로 곱의 법칙을 쓴다.","확인":"729","스킬":"P2"},{"제목":"치역에 빠진 값이 있는 함수 구하기","고비":true,"힌트":"치역에 $1$ 이 없는 함수, $1,\\ 2$ 가 모두 없는 함수의 개수를 세고 겹침을 처리하면?","식":["값 하나가 빠진 함수: $3\\times2^{6}=192$","값 두 개가 빠진 함수: $3\\times1=3$","빠진 값이 있는 함수: $192-3=189$"],"설명":"빠진 값이 하나인 경우를 세면 값 두 개가 빠진 함수는 두 번씩 세어진다. 그래서 값 두 개가 빠진 경우를 한 번 빼 준다. 값 세 개가 모두 빠진 함수는 없다.","확인":"189","스킬":"P2"},{"제목":"여사건으로 공역과 치역이 같은 함수 구하기","힌트":"전체 함수에서 치역에 빠진 값이 있는 함수를 빼면?","식":["$729-189=540$"],"설명":"공역과 치역이 같은 함수는 치역에 빠진 값이 없는 함수이다.","확인":"540","스킬":"P2"}]},"ns-2add9a9f5859":{"길":"치역 후보 4가지로 나누고 f(3)f(4)f(5) 가 4 의 배수인 경우를 센다","단계":[{"제목":"치역 후보와 (가) 조건 정리하기","힌트":"치역이 $\\{6,\\ 7,\\ 8,\\ 9\\}$ 중 세 개이면 후보는 몇 가지이고, 곱이 $4$ 의 배수가 되려면 $f(3),\\ f(4),\\ f(5)$ 는 어떤 값을 가져야 할까?","식":["치역 후보: $\\{6,7,8\\},\\ \\{6,7,9\\},\\ \\{6,8,9\\},\\ \\{7,8,9\\}$","$6=2\\times3,\\ 8=2^{3}$ 이고 $7,\\ 9$ 는 홀수","곱이 $4$ 의 배수: $8$ 이 하나 이상이거나 $6$ 이 두 개 이상"],"설명":"소인수 $2$ 가 두 개 이상 곱해져야 한다. $8$ 이 있으면 $2$ 가 세 개이고, $6$ 은 두 개 이상 있어야 $2$ 가 두 개가 된다. $\\{6,8,9\\}$ 에서는 $9$ 가, $\\{6,7,8\\}$ 에서는 $7$ 이 홀수 역할이라 두 경우의 구조가 같다.","확인":null,"스킬":"C2"},{"제목":"치역이 {6, 7, 8} 인 경우 세기","고비":true,"힌트":"$f(3),\\ f(4),\\ f(5)$ 에 쓰인 서로 다른 값의 개수가 $1,\\ 2,\\ 3$ 개일 때로 나누어 $f(1),\\ f(2)$ 가 나머지 값을 채우는 방법을 곱하면?","식":["값 $1$ 개: $6$ 또는 $8$ 만 가능 $2$ 가지, $f(1),\\ f(2)$ 는 나머지 두 값을 채워 $2$ 가지 → $2\\times2=4$","값 $2$ 개: 조건을 만족하는 $f(3),\\ f(4),\\ f(5)$ 가 $15$ 가지, $f(1),\\ f(2)$ 중 빠진 값이 하나 이상 → $15\\times5=75$","값 $3$ 개: $3!\\times3^{2}=54$","$4+75+54=133$"],"설명":"$\\{6,7,8\\}$ 에서 곱이 $4$ 의 배수가 아닌 것은 $7,7,7$ 과 $6,7,7$ 의 배열뿐이다. 값 $2$ 개인 경우는 $\\{6,7\\}$ 에서 $6,6,7$ 의 배열 $3$ 가지, $\\{6,8\\}$ 와 $\\{7,8\\}$ 에서 각 $6$ 가지로 $15$ 가지이다. 빠진 값이 $f(1),\\ f(2)$ 에 한 번 이상 나오는 경우는 $3^{2}-2^{2}=5$ 가지이다.","확인":"133","스킬":"P4"},{"제목":"치역이 {6, 7, 9} 인 경우 세기","힌트":"$6$ 이 두 개 이상 필요하다. $f(3),\\ f(4),\\ f(5)$ 가 $6,\\ 6,\\ 6$ 일 때와 $6$ 이 두 개일 때로 나누면?","식":["$6,6,6$: $f(1),\\ f(2)$ 가 $7,\\ 9$ 를 채워 $2$ 가지 → $2$","$6$ 두 개와 $7$ 또는 $9$ 한 개: $3\\times2=6$ 가지, $f(1),\\ f(2)$ 중 빠진 값이 하나 이상 → $6\\times5=30$","$2+30=32$"],"설명":"$7,\\ 9$ 는 홀수이므로 $6$ 이 두 개 이상 있어야 곱이 $4$ 의 배수가 된다. $6$ 이 세 개이면 $7$ 과 $9$ 를 모두 $f(1),\\ f(2)$ 가 채워야 하고, 두 개이면 빠진 값만 채우면 된다.","확인":"32","스킬":"P4"},{"제목":"치역이 {7, 8, 9} 인 경우 세기","힌트":"$8$ 이 하나 이상 필요하다. $f(3),\\ f(4),\\ f(5)$ 에 쓰인 서로 다른 값의 개수별로 세면?","식":["값 $1$ 개: $8,8,8$ 에 $f(1),\\ f(2)$ 가 $7,\\ 9$ 를 채워 $2$ 가지 → $2$","값 $2$ 개: $\\{7,8\\},\\ \\{8,9\\}$ 에서 $6$ 가지씩 $12$ 가지, 빠진 값이 하나 이상 → $12\\times5=60$","값 $3$ 개: $3!\\times3^{2}=54$","$2+60+54=116$"],"설명":"$f(3),\\ f(4),\\ f(5)$ 에 $8$ 이 하나 이상 있어야 하므로 $8$ 이 빠진 경우는 제외한다. 나머지는 앞의 경우와 같은 방식으로 $f(1),\\ f(2)$ 가 채우는 값을 센다.","확인":"116","스킬":"P4"},{"제목":"치역별 경우의 수 합하기","힌트":"$\\{6,7,8\\}$ 와 $\\{6,8,9\\}$ 는 같은 값이므로 두 번 더하고, 나머지 둘을 더하면?","식":["$133\\times2+32+116=414$"],"설명":"치역이 다르면 서로 다른 함수이므로 모두 더한다. $7$ 과 $9$ 는 둘 다 홀수라 $\\{6,8,9\\}$ 도 $133$ 이다.","확인":"414","스킬":"C2"}]},"ns-2d16767c06fa":{"길":"x₃ 가 정해지면 앞 두 수는 2 가지이므로 뒤 네 수의 중복조합으로 a_n 을 구해 합한다","단계":[{"제목":"꺼낸 수의 조건을 부등식으로 쓰기","힌트":"여섯 수를 차례로 $x_{1},\\ \\cdots,\\ x_{6}$ 이라 하고 두 조건을 식으로 나타내면?","식":["(가): $0\\le x_{1}\\le x_{2}\\le x_{3}\\le x_{4}\\le x_{5}\\le x_{6}\\le n$","(나): $x_{3}=x_{1}+1$"],"설명":"먼저 꺼낸 공의 수보다 작지 않다는 것은 순서대로 수가 줄지 않는다는 뜻이다. 세 번째 수는 첫 번째 수보다 $1$ 이 크므로 $x_{1}$ 은 $x_{3}$ 로 정해진다.","확인":null,"스킬":"P3"},{"제목":"x₃ 가 정해졌을 때 (x₁, x₂) 의 경우 세기","힌트":"$x_{3}$ 를 알면 $x_{1}=x_{3}-1$ 이고 $x_{1}\\le x_{2}\\le x_{3}$ 이다. $x_{2}$ 가 될 수 있는 값은 몇 가지일까?","식":["$x_{1}=x_{3}-1$","$x_{2}=x_{3}-1$ 또는 $x_{2}=x_{3}$"],"설명":"$x_{2}$ 는 $x_{1}$ 이상 $x_{3}$ 이하인 정수이고 $x_{3}=x_{1}+1$ 이므로 두 값뿐이다.","확인":"2","스킬":"P3"},{"제목":"x₃ 부터 x₆ 까지 고르는 경우로 a_n 구하기","고비":true,"힌트":"$x_{3}\\ge1$ 이고 $x_{3}\\le x_{4}\\le x_{5}\\le x_{6}\\le n$ 이면 $1$ 부터 $n$ 까지 중복을 허락해 네 개를 고르는 것과 같을까?","식":["$x_{3}=x_{1}+1\\ge1$ 이므로 $x_{3},\\ x_{4},\\ x_{5},\\ x_{6}$ 은 $1$ 부터 $n$ 중 중복을 허락해 고른 네 수","개수: ${}_{n}\\mathrm{H}_{4}={}_{n+3}\\mathrm{C}_{4}$","$a_{n}=2\\times{}_{n+3}\\mathrm{C}_{4}$"],"설명":"네 수를 고르면 크기순으로 $x_{3}\\le x_{4}\\le x_{5}\\le x_{6}$ 이 하나로 정해진다. 여기에 $(x_{1},\\ x_{2})$ 의 $2$ 가지를 곱한다.","확인":null,"스킬":"P3"},{"제목":"분수식을 간단히 하기","힌트":"${}_{n+3}\\mathrm{C}_{4}=\\dfrac{(n+3)(n+2)(n+1)n}{24}$ 를 대입해 $(n+2)(n+3)$ 으로 나누면?","식":["$\\dfrac{a_{n}}{(n+2)(n+3)}=\\dfrac{2\\times(n+3)(n+2)(n+1)n}{24\\times(n+2)(n+3)}$","$=\\dfrac{n(n+1)}{12}$"],"설명":"조합의 정의로 쓴 분자에 $(n+2)(n+3)$ 이 들어 있어 약분된다.","확인":null,"스킬":"P6"},{"제목":"시그마 계산하기","힌트":"$\\displaystyle\\sum_{n=1}^{36}n^{2}$ 과 $\\displaystyle\\sum_{n=1}^{36}n$ 의 공식을 써서 합하면?","식":["$\\dfrac{1}{12}\\left(\\displaystyle\\sum_{n=1}^{36}n^{2}+\\sum_{n=1}^{36}n\\right)$","$=\\dfrac{1}{12}\\left(\\dfrac{36\\times37\\times73}{6}+\\dfrac{36\\times37}{2}\\right)=\\dfrac{1}{12}(16206+666)$","$=1406$"],"설명":"$\\sum n^{2}=\\frac{N(N+1)(2N+1)}{6},\\ \\sum n=\\frac{N(N+1)}{2}$ 에 $N=36$ 을 넣는다.","확인":"1406","스킬":"P6"}]},"ns-2e20cfea748d":{"길":"삼각형에 쓸 두 색을 고르고 반원 8색은 원순열로 놓은 뒤 삼각형을 교대로 칠한다","단계":[{"제목":"삼각형 영역에 쓸 두 색 고르기","힌트":"열 가지 색 중 삼각형 $8$ 개에 쓸 두 색을 고르는 방법은? (남은 색은 반원에 쓴다)","식":["${}_{10}\\mathrm{C}_{2}=45$"],"설명":"삼각형에 쓸 두 색을 정하면 남은 $8$ 가지 색은 모두 반원에 쓰인다. 두 색의 순서는 아직 구별하지 않는다.","확인":"45","스킬":"P3"},{"제목":"반원 8개에 8색 칠하는 경우 세기","고비":true,"힌트":"도형을 회전해서 일치하는 것은 같은 것으로 볼 때, 서로 다른 여덟 색을 원 모양으로 늘어놓는 방법은?","식":["서로 다른 $8$ 색의 원순열: $(8-1)!=7!=5040$"],"설명":"반원 $8$ 개가 원을 이루고 색이 모두 달라 회전으로 겹치는 경우를 같게 보면 원순열이다. 이렇게 하면 회전에 의한 중복이 모두 처리된다.","확인":"5040","스킬":"P3"},{"제목":"삼각형 두 색을 칠하는 방법 정하기","힌트":"이웃한 삼각형끼리 색이 달라야 할 때, 반원이 정해진 상태에서 두 색으로 삼각형 $8$ 개를 칠하는 방법은?","식":["이웃한 삼각형은 색이 달라야 하므로 두 색이 번갈아 나온다","첫 삼각형에 두 색 중 어느 것을 쓰느냐: $2$ 가지"],"설명":"삼각형 $8$ 개가 중심 둘레에 이웃하여 있고 모두 구분되려면 두 색이 번갈아야 한다. 반원의 배열이 정해져 회전 중복이 없으므로 번갈아 칠하는 방법은 $2$ 가지이다.","확인":"2","스킬":"P3"},{"제목":"세 경우의 수 곱하기","힌트":"두 색 고르기, 반원 칠하기, 삼각형 칠하기를 모두 곱하면?","식":["$45\\times5040\\times2=453600=\\dfrac{10!}{8}$"],"설명":"세 일은 이어서 하는 일이므로 곱한다. $\\frac{10\\times9}{2}\\times7!\\times2=\\frac{10!}{8}$ 이다.","확인":"453600","스킬":"P3"}]},"ns-3172289faaca":{"길":"남자 4명을 변마다 한 명씩 앉혀 회전을 처리한 뒤 여자를 남은 자리에 앉힌다","단계":[{"제목":"남자 4명을 네 변에 배정하기","고비":true,"힌트":"붙어 있는 두 의자에 남녀가 한 명씩 앉으면 변마다 남자는 몇 명일까? 탁자를 돌려 겹치는 배치를 같게 볼 때 남자 $4$ 명을 네 변에 놓는 방법은?","식":["각 변의 두 의자에 남자 $1$ 명, 여자 $1$ 명","남자 $4$ 명을 네 변에 놓는 방법: $\\dfrac{4!}{4}=6$"],"설명":"정사각형 탁자를 $90^{\\circ}$ 씩 돌리면 같은 배치가 네 번씩 세어지므로 순열 $4!$ 을 $4$ 로 나눈다. 해설이 이 방식으로 회전을 같게 본다.","확인":"6","스킬":"P3"},{"제목":"변마다 남자가 앉을 의자 고르기","힌트":"각 변의 두 의자 중 남자가 앉을 의자를 고르는 방법을 네 변에 모두 곱하고, 앞 단계의 값과 곱하면?","식":["한 변에서 의자 $2$ 가지, 네 변: $2^{4}=16$","남자를 앉히는 방법 $6\\times16=96$"],"설명":"남자가 앉을 의자가 정해지면 같은 변의 나머지 의자는 여자의 자리이다. 네 변에서 각각 두 가지씩 독립적으로 고른다.","확인":"96","스킬":"P3"},{"제목":"여자 4명을 남은 의자에 앉히기","힌트":"남은 네 의자에 서로 다른 여자 $4$ 명을 앉히는 방법은?","식":["$4!=24$"],"설명":"남자의 자리가 정해지면 회전으로 겹치는 경우는 이미 처리되었으므로 여자는 남은 네 의자에 자유롭게 앉는다.","확인":"24","스킬":"P4"},{"제목":"남자와 여자의 경우의 수 곱하기","힌트":"남자를 앉히는 방법과 여자를 앉히는 방법을 곱하면?","식":["$96\\times24=2304$"],"설명":"남자를 앉힌 뒤 여자를 앉히는 이어진 일이므로 곱한다.","확인":"2304","스킬":"P4"}]},"ns-34e14e49151c":{"길":"문자가 바뀌는 횟수가 홀수이면 A 와 B 의 묶음 수가 같으므로 묶음별 개수를 중복조합으로 센다","단계":[{"제목":"바뀌는 횟수가 2n−1 인 배열의 구조 파악하기","힌트":"같은 문자가 이어진 부분을 한 묶음으로 보면 문자가 바뀔 때마다 묶음은 몇 개 늘까? 바뀌는 횟수가 홀수이면 처음과 끝 문자는 같을까 다를까?","식":["문자가 바뀔 때마다 묶음이 $1$ 개 늘어 묶음은 모두 $2n$ 개","$\\mathrm{A}$ 로 시작하면 $\\mathrm{A}$ 묶음 $n$ 개와 $\\mathrm{B}$ 묶음 $n$ 개가 번갈아 놓이고 $\\mathrm{B}$ 로 끝난다"],"설명":"같은 문자가 연속한 부분이 한 묶음이므로 바뀐 횟수 $2n-1$ 에 $1$ 을 더하면 묶음은 $2n$ 개이다. 두 문자가 번갈아 나오므로 각각 $n$ 개씩이다.","확인":null,"스킬":"P3"},{"제목":"A 묶음별 카드 수 세기","고비":true,"힌트":"$\\mathrm{A}$ 카드 $6$ 장을 $n$ 개의 묶음에 각각 $1$ 장 이상씩 나누는 방법은?","식":["묶음별 $\\mathrm{A}$ 의 수: $x_{1}+x_{2}+\\cdots+x_{n}=6\\ (x_{i}\\ge1)$","$x_{i}-1$ 을 새 문자로 두면 합이 $6-n$ 인 음이 아닌 정수해","${}_{n}\\mathrm{H}_{6-n}={}_{5}\\mathrm{C}_{6-n}={}_{5}\\mathrm{C}_{n-1}$"],"설명":"각 묶음에 한 장씩 먼저 넣고 남은 $6-n$ 장을 $n$ 개 묶음에 나누는 중복조합이다. ${}_{n}\\mathrm{H}_{6-n}={}_{5}\\mathrm{C}_{6-n}$ 이고 ${}_{5}\\mathrm{C}_{6-n}={}_{5}\\mathrm{C}_{n-1}$ 이다.","확인":null,"스킬":"P3"},{"제목":"f(2n−1) 구하기","힌트":"$\\mathrm{B}$ 카드도 같은 방법으로 세고, $\\mathrm{B}$ 로 시작하는 경우까지 더하면?","식":["$\\mathrm{B}$ 묶음별 카드 수도 ${}_{5}\\mathrm{C}_{n-1}$ 가지","$\\mathrm{A}$ 로 시작: $\\left({}_{5}\\mathrm{C}_{n-1}\\right)^{2}$","$\\mathrm{B}$ 로 시작해도 같으므로 $f(2n-1)=2\\left({}_{5}\\mathrm{C}_{n-1}\\right)^{2}$"],"설명":"$\\mathrm{A}$ 의 분배와 $\\mathrm{B}$ 의 분배는 독립이라 곱한다. $\\mathrm{B}$ 로 시작해 $\\mathrm{A}$ 로 끝나는 경우도 같은 수이므로 $2$ 배이다.","확인":null,"스킬":"P3"},{"제목":"시그마를 조합의 곱의 합으로 바꾸기","힌트":"${}_{5}\\mathrm{C}_{n}={}_{5}\\mathrm{C}_{5-n}$ 임을 써서 제곱을 서로 다른 두 조합의 곱으로 바꾸면?","식":["$\\displaystyle\\sum_{n=1}^{6}f(2n-1)=2\\sum_{n=0}^{5}\\left({}_{5}\\mathrm{C}_{n}\\right)^{2}$","$=2\\displaystyle\\sum_{n=0}^{5}{}_{5}\\mathrm{C}_{n}\\times{}_{5}\\mathrm{C}_{5-n}$"],"설명":"$n-1$ 을 $n$ 으로 바꾸면 합의 범위가 $0$ 부터 $5$ 까지가 된다. 한 조합을 ${}_{5}\\mathrm{C}_{5-n}$ 으로 바꾸면 두 조합의 아래 수의 합이 $5$ 가 되어 다항식 곱의 계수 꼴이 된다.","확인":null,"스킬":"P6"},{"제목":"다항식의 계수 비교로 합 구하기","힌트":"$(1+x)^{10}=(1+x)^{5}(1+x)^{5}$ 의 $x^{5}$ 의 계수를 양쪽에서 비교하면?","식":["좌변의 $x^{5}$ 의 계수: ${}_{10}\\mathrm{C}_{5}$","우변의 $x^{5}$ 의 계수: $\\displaystyle\\sum_{k=0}^{5}{}_{5}\\mathrm{C}_{k}\\times{}_{5}\\mathrm{C}_{5-k}$","$\\sum f(2n-1)=2\\times{}_{10}\\mathrm{C}_{5}=2\\times252=504$"],"설명":"우변에서 $x^{5}$ 이 나오려면 한쪽에서 $x^{k}$, 다른 쪽에서 $x^{5-k}$ 를 고르므로 계수가 ${}_{5}\\mathrm{C}_{k}\\times{}_{5}\\mathrm{C}_{5-k}$ 이다. $k$ 를 모두 더하면 좌변의 계수와 같다.","확인":"504","스킬":"P6"}]},"ns-351c2169dd41":{"길":"고른 세 색의 사용 횟수를 (3,2,1) 과 (2,2,2) 로 나누어 회전을 처리하며 센다","단계":[{"제목":"사용할 색 3가지 고르기","힌트":"네 가지 색 중 쓸 세 가지를 고르는 방법은?","식":["${}_{4}\\mathrm{C}_{3}=4$"],"설명":"고른 세 색은 모두 한 번 이상 칠해야 하므로 색의 조합이 정해지면 나머지는 사용 횟수의 경우로 나눈다.","확인":"4","스킬":"P4"},{"제목":"사용 횟수가 (3, 2, 1) 인 경우 세기","힌트":"세 번 칠하는 색이 서로 이웃하지 않으려면 어느 면들에 놓일까? 그 뒤 두 번·한 번 칠하는 색을 놓는 방법은?","식":["세 번 칠하는 색은 한 면씩 건너 $3$ 개 면 → 나머지 $3$ 개 면에 두 번·한 번 색을 놓는 방법은 회전으로 겹쳐 $1$ 가지","$3,\\ 2,\\ 1$ 번 칠할 색을 정하는 방법: $3!=6$","$4\\times6\\times1=24$"],"설명":"여섯 면에서 같은 색 세 개가 이웃하지 않으려면 한 면씩 건너뛰어야 한다. 남은 세 면에는 같은 색이 두 면, 다른 색이 한 면 들어가며 회전하여 일치하는 것을 같게 보면 한 가지뿐이다.","확인":"24","스킬":"P4"},{"제목":"사용 횟수가 (2, 2, 2) 인 경우 세기","고비":true,"힌트":"색마다 두 번씩 칠할 때 이웃한 면은 달라야 한다. 마주 보는 면에 같은 색이 오는 색이 몇 개인지로 나누면?","식":["세 색이 모두 마주 보게 칠하는 경우: $2$ 가지","한 색만 마주 보게 칠하는 경우: 마주 볼 색 $3$ 가지, 나머지 두 색 칠하는 방법 $1$ → $3$ 가지","$4\\times(2+3)=20$"],"설명":"마주 보는 쌍이 몇 개 같은 색인지로 나누어 회전으로 겹치는 것을 같게 센다. 모든 쌍이 같은 색이면 두 가지 배열이 있고, 한 쌍만 같은 색이면 그 색을 고르는 $3$ 가지에 나머지 배열이 하나씩 정해진다.","확인":"20","스킬":"C2"},{"제목":"두 경우의 수 합하기","힌트":"사용 횟수의 구성이 다른 두 경우를 더하면?","식":["$24+20=44$"],"설명":"사용 횟수의 구성이 다르면 서로 다른 칠하기이므로 더한다.","확인":"44","스킬":"C2"}]},"ns-3530af5f7ba5":{"길":"호수 안 교차점을 지날 수 없으니 교차점마다 오는 방법의 수를 왼쪽·아래에서 더해 간다","단계":[{"제목":"지날 수 없는 교차점과 길의 모양 확인하기","힌트":"$\\mathrm{A}$ 를 $(0,0)$, $\\mathrm{B}$ 를 $(6,4)$ 로 둘 때 호수 안에 들어 있는 교차점은 몇 개일까?","식":["호수 안의 교차점: $(4,1),\\ (5,1),\\ (4,2),\\ (5,2)$","맨 윗줄 $y=4$ 는 $x\\ge2$ 인 부분만 길이다"],"설명":"그림에서 호수에 완전히 들어 있는 교차점은 네 개이고, 그 점들에 닿는 길은 지날 수 없다. 맨 윗줄은 세 번째 세로선부터 시작한다.","확인":"4","스킬":"P4"},{"제목":"호수 왼쪽 영역에서 교차점별 경로 수 채우기","힌트":"각 교차점까지 가는 최단 경로의 수는 왼쪽 교차점과 아래쪽 교차점의 경로 수를 더한 것이다. $x\\le3,\\ y\\le2$ 영역을 채우면?","식":["$y=0$ 줄: $1,\\ 1,\\ 1,\\ 1,\\ 1,\\ 1,\\ 1$","$y=1$ 줄 ($x=0\\sim3$): $1,\\ 2,\\ 3,\\ 4$","$y=2$ 줄 ($x=0\\sim3$): $1,\\ 3,\\ 6,\\ 10$"],"설명":"한 교차점에는 왼쪽 교차점이나 아래쪽 교차점에서만 올 수 있으므로 두 값을 더해 채운다. 맨 아랫줄은 모두 $1$ 이다. 여기서 확인할 값은 $(3,2)$ 의 경로 수이다.","확인":"10","스킬":"P4"},{"제목":"오른쪽 세로길과 세 번째 가로선 채우기","고비":true,"힌트":"호수에 막혀 $(6,1),\\ (6,2)$ 는 아래에서만 올 수 있다. $y=3$ 줄의 값을 채우면 $(6,3)$ 은?","식":["$(6,1)=1,\\ (6,2)=1$ ($(5,1),\\ (5,2)$ 는 막혀 있으므로)","$y=3$ 줄: $1,\\ 4,\\ 10,\\ 20,\\ 20,\\ 20,\\ 21$","$(4,3)=20+0,\\ (5,3)=20+0,\\ (6,3)=20+1$"],"설명":"호수 안 교차점의 경로 수는 $0$ 으로 본다. $(4,3)$ 은 아래 교차점이 호수 안이라 왼쪽에서만, $(6,3)$ 은 왼쪽 $20$ 과 아래 $1$ 을 더한다.","확인":"21","스킬":"P4"},{"제목":"맨 윗줄을 채워 B 까지의 경로 수 구하기","힌트":"$y=4$ 줄은 $(2,4)$ 에서 시작한다. 왼쪽과 아래 값을 더해 $\\mathrm{B}$ 까지 채우면?","식":["$(2,4)=10,\\ (3,4)=10+20=30$","$(4,4)=30+20=50,\\ (5,4)=50+20=70$","$(6,4)=70+21=91$"],"설명":"맨 윗줄의 시작점은 아래 교차점에서만 올 수 있어 값이 $10$ 이다. 이후 왼쪽 값과 아래 값을 더해 $\\mathrm{B}$ 에 이른다.","확인":"91","스킬":"P4"}]},"ns-361ffcbdbf88":{"길":"소인수 4개를 빈 묶음 없이 세 묶음으로 나눈다","단계":[{"제목":"910 을 소인수분해하기","힌트":"$910$ 을 소수의 곱으로 나타내면 서로 다른 소수는 몇 개일까?","식":["$910=2\\times5\\times7\\times13$"],"설명":"$2,\\ 5,\\ 7,\\ 13$ 을 곱하면 $910$ 이고 같은 소수는 반복되지 않는다.","확인":"4","스킬":"N1"},{"제목":"세 자연수의 곱을 소수의 묶음으로 바꾸기","고비":true,"힌트":"소수 $4$ 개를 $1$ 보다 큰 세 수에 나누어 넣으면 묶음의 크기는 어떻게 될까?","식":["소수 $4$ 개를 세 묶음으로 나누고 빈 묶음은 없다","묶음의 크기는 $(2,1,1)$ 뿐"],"설명":"각 소수는 세 수 중 하나에 들어가고 세 수가 모두 $1$ 보다 크려면 각 묶음에 소수가 하나 이상 있어야 한다. $4=2+1+1$ 이므로 두 소수가 함께 묶이고 나머지 둘은 따로 있다.","확인":null,"스킬":"P3"},{"제목":"함께 묶을 두 소수 고르기","힌트":"곱하는 순서를 구별하지 않을 때 함께 묶이는 두 소수를 고르는 방법은?","식":["${}_{4}\\mathrm{C}_{2}=6$"],"설명":"함께 묶일 두 소수를 고르면 나머지 두 소수는 각각 하나씩 한 묶음이 되어 곱이 정해진다. 곱하는 순서는 생각하지 않으므로 더 곱할 것이 없다.","확인":"6","스킬":"P3"}]},"ns-36a0bac5e28c":{"길":"A, B, C 를 먼저 앉혀 원탁을 고정하고 사이 세 칸에 D, E 를 떨어뜨려 넣은 뒤 F, G 를 놓는다","단계":[{"제목":"A, B, C 를 원탁에 앉히기","힌트":"세 명을 원탁에 앉히는 원순열은 몇 가지이고, 이렇게 앉으면 사이의 빈 칸은 몇 개일까?","식":["$(3-1)!=2$","$\\mathrm{A},\\ \\mathrm{B},\\ \\mathrm{C}$ 사이에 칸이 $3$ 개 생긴다"],"설명":"세 사람을 먼저 앉히면 원탁의 회전이 고정되어 이후에는 칸마다 자리를 일렬로 세면 된다. $\\mathrm{A},\\ \\mathrm{B},\\ \\mathrm{C}$ 가 서로 이웃하지 않으려면 사이 세 칸에 모두 다른 사람이 앉아야 한다.","확인":"2","스킬":"P4"},{"제목":"D, E 가 앉을 칸 정하기","고비":true,"힌트":"$\\mathrm{D},\\ \\mathrm{E}$ 가 이웃하지 않으려면 같은 칸에 앉을 수 있을까? 서로 다른 칸에 앉히는 방법은?","식":["사이 $3$ 칸에 네 명($\\mathrm{D},\\ \\mathrm{E},\\ \\mathrm{F},\\ \\mathrm{G}$)이 들어가고 칸마다 한 명 이상","$\\mathrm{D},\\ \\mathrm{E}$ 가 같은 칸이면 이웃하므로 서로 다른 칸","${}_{3}\\mathrm{P}_{2}=6$"],"설명":"$\\mathrm{F},\\ \\mathrm{G}$ 두 명만으로는 $\\mathrm{D},\\ \\mathrm{E}$ 사이를 채우면서 세 칸을 모두 채울 수 없다. 그래서 $\\mathrm{D},\\ \\mathrm{E}$ 는 $\\mathrm{A},\\ \\mathrm{B},\\ \\mathrm{C}$ 로 갈라진 서로 다른 칸에 앉는다. 칸을 고르는 순서가 의미가 있어 순열로 센다.","확인":"6","스킬":"P4"},{"제목":"남은 한 칸과 F, G 놓기","힌트":"남은 칸에도 반드시 앉아야 한다. $\\mathrm{F},\\ \\mathrm{G}$ 가 모두 그 칸에 앉는 경우와 한 명만 앉는 경우로 나누면?","식":["둘 다 남은 칸: 앉는 순서 $2$ 가지","한 명만 남은 칸: 그 사람 선택 ${}_{2}\\mathrm{C}_{1}$, 다른 한 명은 $\\mathrm{D},\\ \\mathrm{E}$ 의 양옆 자리 ${}_{4}\\mathrm{C}_{1}$ → $2\\times4=8$","$2+8=10$"],"설명":"$\\mathrm{F},\\ \\mathrm{G}$ 가 둘 다 $\\mathrm{D},\\ \\mathrm{E}$ 칸에 가면 남은 칸이 비어 $\\mathrm{A},\\ \\mathrm{B},\\ \\mathrm{C}$ 가 이웃하게 되므로 불가능하다. 한 명만 남은 칸에 앉으면 다른 한 명은 $\\mathrm{D}$ 또는 $\\mathrm{E}$ 의 양옆 네 자리 중 하나에 앉는다.","확인":"10","스킬":"C2"},{"제목":"세 단계의 경우의 수 곱하기","힌트":"세 단계의 경우의 수를 모두 곱하면?","식":["$2\\times6\\times10=120$"],"설명":"$\\mathrm{A},\\ \\mathrm{B},\\ \\mathrm{C}$ 를 앉히고 $\\mathrm{D},\\ \\mathrm{E}$ 를 앉힌 뒤 $\\mathrm{F},\\ \\mathrm{G}$ 를 앉히는 이어진 일이므로 곱한다.","확인":"120","스킬":"P4"}]},"ns-39f7476f0ab9":{"길":"각 종류를 1개씩 먼저 빼 두고 합이 7 이하인 음이 아닌 정수해를 합마다 센다","단계":[{"제목":"부등식으로 바꾸어 상한 구하기","힌트":"세 종류의 수를 $x,\\ y,\\ z$ 로 두고 각각 $1$ 씩 빼서 새 문자로 나타내면 합의 상한은 얼마일까?","식":["$x+y+z\\le10\\ (x,\\,y,\\,z\\ge1)$","$x=x'+1,\\ y=y'+1,\\ z=z'+1$ 로 두면 $x'+y'+z'\\le7\\ (x',\\,y',\\,z'\\ge0)$"],"설명":"적어도 하나씩 선택하므로 각 종류에서 $1$ 개씩 먼저 뺀다. 각 종류가 $11$ 개씩 있고 전체가 $10$ 개 이하라 개수 제한에 걸리지 않는다.","확인":"7","스킬":"P3"},{"제목":"합이 k 로 정해진 경우의 수 구하기","고비":true,"힌트":"$x'+y'+z'=k$ 의 음이 아닌 정수해는 중복조합으로 몇 개이고, $k=0$ 부터 $7$ 까지 값은?","식":["$k=0,\\ 1,\\ 2,\\ 3:\\ 1,\\ {}_{3}\\mathrm{H}_{1}=3,\\ {}_{3}\\mathrm{H}_{2}=6,\\ {}_{3}\\mathrm{H}_{3}=10$","$k=4,\\ 5,\\ 6:\\ {}_{3}\\mathrm{H}_{4}=15,\\ {}_{3}\\mathrm{H}_{5}=21,\\ {}_{3}\\mathrm{H}_{6}=28$","$k=7:\\ {}_{3}\\mathrm{H}_{7}={}_{9}\\mathrm{C}_{7}=36$"],"설명":"합이 $7$ 이하이므로 합이 $0,\\ 1,\\ \\cdots,\\ 7$ 인 경우를 따로 센다. 합이 $k$ 일 때는 ${}_{3}\\mathrm{H}_{k}={}_{k+2}\\mathrm{C}_{k}$ 이다. 여기서 확인할 값은 $k=7$ 의 경우의 수이다.","확인":"36","스킬":"P3"},{"제목":"합마다 센 경우의 수 더하기","힌트":"$k=0$ 부터 $7$ 까지의 값을 모두 더하면?","식":["$1+3+6+10+15+21+28+36=120$"],"설명":"합이 다르면 서로 다른 꽃다발이므로 모두 더한다.","확인":"120","스킬":"P3"}]},"ns-3a0fba84e418":{"길":"내릴 3개 층을 고르고 5명이 그 3개 층을 모두 쓰는 경우를 여사건으로 센다","단계":[{"제목":"내릴 3개 층 고르기","힌트":"$3$ 층부터 $7$ 층까지 $5$ 개 층 중 사람이 내릴 $3$ 개 층을 고르는 방법은?","식":["${}_{5}\\mathrm{C}_{3}=10$"],"설명":"내리는 층의 조합을 먼저 정하고, 그 세 층에 5명이 어떻게 나누어 내리는지는 따로 센다.","확인":"10","스킬":"P3"},{"제목":"5명이 고른 세 층에 모두 내리는 경우 구하기","고비":true,"힌트":"5명이 각각 세 층 중 한 층에 내리는 전체 경우에서 내리지 않는 층이 생기는 경우를 빼면?","식":["전체: $3^{5}=243$","한 층에 아무도 안 내리는 경우: $3\\times2^{5}=96$, 두 층이 비는 경우: $3\\times1=3$","$243-96+3=150$"],"설명":"세 층이 모두 쓰여야 하므로 비는 층이 있는 경우를 뺀다. 한 층이 빈 경우를 셀 때 두 층이 빈 경우가 두 번씩 세어지므로 한 번 더해 준다.","확인":"150","스킬":"P2"},{"제목":"층 고르기와 내리는 방법 곱하기","힌트":"층을 고르는 방법과 5명이 내리는 방법을 곱하면?","식":["$10\\times150=1500$"],"설명":"층을 고른 뒤 그 층들에 사람이 내리는 이어진 일이므로 곱한다.","확인":"1500","스킬":"P2"}]},"ns-3b3f3ce870c7":{"길":"1학년 두 명의 자리를 정해 회전을 없애고 남은 자리를 일렬로 보아 3학년 사이에 2학년을 넣는다","단계":[{"제목":"1학년이 앉는 자리와 순서 정하기","힌트":"의자를 둘레를 따라 이으면 이웃한 쌍은 몇 개일까? 탁자를 $180^{\\circ}$ 돌려 겹치는 것을 같게 보면 1학년 두 명의 자리는 몇 가지이고, 서로 자리를 바꾸는 경우까지 곱하면?","식":["의자 $8$ 개가 둘레를 따라 이어지므로 이웃한 쌍 $8$ 개 (모서리 이웃 포함)","$180^{\\circ}$ 회전으로 겹치는 것은 같으므로 $8\\div2=4$","1학년끼리 자리를 바꾸는 경우 $2$ 가지: $4\\times2=8$"],"설명":"직사각형 탁자는 $180^{\\circ}$ 돌릴 때만 의자가 겹친다. 같은 변이 아니어도 옆에 있으면 이웃으로 보므로 의자 $8$ 개는 원 모양으로 이어진 것과 같다.","확인":"8","스킬":"P3"},{"제목":"3학년 4명을 일렬로 배열하기","고비":true,"힌트":"1학년의 자리가 정해지면 남은 여섯 자리는 원순열일까, 일렬일까? 3학년 4명을 그 자리에 놓는 순서는?","식":["1학년 자리가 고정되면 회전 대칭이 사라져 남은 $6$ 자리는 일렬","3학년 $4$ 명의 배열: $4!=24$"],"설명":"1학년 두 명이 앉은 자리를 기준으로 삼으면 더 이상 회전으로 겹치는 경우가 없다. 남은 자리를 줄 세워 3학년을 먼저 앉히면 2학년이 앉을 자리가 사이 공간으로 정해진다.","확인":"24","스킬":"P3"},{"제목":"2학년이 앉을 사이 공간 고르기","힌트":"3학년 4명의 양 끝과 사이의 빈 공간은 모두 몇 개이고, 서로 다른 2학년 두 명이 서로 다른 공간에 앉는 방법은?","식":["3학년 사이와 양 끝의 공간: $5$ 개","2학년 두 명이 서로 다른 공간에 앉는 방법: ${}_{5}\\mathrm{P}_{2}=20$"],"설명":"2학년 두 명이 서로 이웃하지 않으려면 서로 다른 공간에 앉아야 한다. 양 끝 공간은 한쪽이 1학년과 닿아 있어도 2학년끼리 떨어지므로 쓸 수 있다.","확인":"20","스킬":"P4"},{"제목":"세 단계의 경우의 수 곱하기","힌트":"1학년 자리, 3학년 배열, 2학년 자리의 경우의 수를 곱하면?","식":["$8\\times24\\times20=3840$"],"설명":"세 일은 이어서 하는 일이므로 곱한다. $4\\times2\\times4!\\times{}_{5}\\mathrm{P}_{2}=3840$ 이다.","확인":"3840","스킬":"P3"}]},"ns-3e4e3bf27707":{"길":"a, b, c 를 3 의 거듭제곱으로 두어 지수의 합 x+y+z=n 의 해의 개수로 바꾼다","단계":[{"제목":"a, b, c 를 3 의 거듭제곱으로 나타내기","힌트":"$abc=3^{n}$ 이면 $a,\\ b,\\ c$ 는 어떤 꼴이어야 하고, $2$ 보다 크면 지수는 어떤 범위일까?","식":["$a=3^{x},\\ b=3^{y},\\ c=3^{z}$ 로 놓으면 $3^{x+y+z}=3^{n}$","$x+y+z=n$","$a,\\ b,\\ c>2$ 이므로 $x,\\ y,\\ z\\ge1$"],"설명":"곱이 $3$ 의 거듭제곱이면 각 수의 약수도 $3$ 의 거듭제곱이다. $3^{0}=1$ 은 $2$ 보다 작으므로 지수는 $1$ 이상의 정수이다.","확인":null,"스킬":"N1"},{"제목":"자연수해의 개수를 n 으로 나타내기","고비":true,"힌트":"$x,\\ y,\\ z\\ge1$ 에서 $1$ 씩 빼서 음이 아닌 정수해로 바꾸면 합은 얼마이고, 해의 개수는 어떤 식일까?","식":["$x=x'+1,\\ y=y'+1,\\ z=z'+1$ 로 두면 $x'+y'+z'=n-3\\ (x',\\,y',\\,z'\\ge0)$","${}_{3}\\mathrm{H}_{n-3}={}_{n-1}\\mathrm{C}_{n-3}={}_{n-1}\\mathrm{C}_{2}$","$\\dfrac{(n-1)(n-2)}{2}$"],"설명":"각 지수에서 $1$ 씩 빼 합이 $n-3$ 인 음이 아닌 정수해로 바꾸면 중복조합이다. ${}_{n-1}\\mathrm{C}_{n-3}={}_{n-1}\\mathrm{C}_{2}$ 이다.","확인":null,"스킬":"P3"},{"제목":"개수가 36 이 되는 n 구하기","힌트":"$\\dfrac{(n-1)(n-2)}{2}=36$ 에서 이웃한 두 자연수의 곱이 $72$ 가 되는 $n$ 은?","식":["$(n-1)(n-2)=72=9\\times8$","$n-1=9$ 이므로 $n=10$"],"설명":"연속한 두 자연수의 곱이 $72$ 이므로 $9$ 와 $8$ 이다. $n-1$ 이 큰 쪽이다.","확인":"10","스킬":"P3"}]},"ns-3f97d77cf341":{"길":"전체에서 2 가 없는 경우와 4 가 없는 경우를 빼고 둘 다 없는 경우를 더한다","단계":[{"제목":"전체 네 자리 자연수의 개수 구하기","힌트":"$2,\\ 4,\\ 6$ 중 중복을 허용해 네 자리를 채우는 방법은?","식":["${}_{3}\\mathrm{\\Pi}_{4}=3^{4}=81$"],"설명":"각 자리마다 세 숫자가 모두 올 수 있으므로 $3$ 을 네 번 곱한다. 숫자가 $0$ 이 아니므로 첫째 자리에도 제한이 없다.","확인":"81","스킬":"P2"},{"제목":"2 또는 4 가 빠진 경우 구하기","고비":true,"힌트":"$2$ 가 없는 경우, $4$ 가 없는 경우, 둘 다 없는 경우를 각각 세고 겹침을 처리하면?","식":["$2$ 가 없는 경우: $4,\\ 6$ 으로만 만든 수 ${}_{2}\\mathrm{\\Pi}_{4}=16$","$4$ 가 없는 경우: $2,\\ 6$ 으로만 만든 수 $16$","둘 다 없는 경우: $6$ 만 쓴 수 $1$","$16+16-1=31$"],"설명":"두 경우를 더하면 $6$ 만 쓴 수가 두 번 세어지므로 한 번 뺀다.","확인":"31","스킬":"P2"},{"제목":"여사건으로 2 와 4 가 모두 포함된 수 구하기","힌트":"전체에서 $2$ 또는 $4$ 가 빠진 수를 빼면?","식":["$81-31=50$"],"설명":"$2$ 와 $4$ 가 모두 포함된 수는 둘 중 하나라도 빠진 수를 제외한 나머지이다.","확인":"50","스킬":"P2"}]},"ns-3ffff73c256f":{"길":"(나)는 분할된 집합의 개수, (가)는 두 원소를 고르는 경우의 수로 구한다","단계":[{"제목":"(나)의 집합 개수 세기","힌트":"원소가 2개인 집합 1개와 원소가 1개인 집합 $(n-2)$개를 합하면 집합은 모두 몇 개인가?","식":["$g(n)=1+(n-2)=n-1$","$g(5)=4$"],"설명":"원소 2개짜리 집합 1개와 원소 1개짜리 집합 $(n-2)$개이므로 집합의 개수는 $n-1$이다. $n=5$를 넣으면 $4$이다.","확인":"4","스킬":"P3"},{"제목":"(가)의 경우의 수 세기","힌트":"$n$개의 원소 중 한 묶음이 될 2개를 고르는 방법은 몇 가지인가?","식":["$f(n)={}_{n}\\mathrm{C}_{2}$","$f(5)={}_{5}\\mathrm{C}_{2}=10$"],"설명":"두 원소를 한 묶음으로 고르면 나머지 원소는 각각 따로 한 집합이 되어 분할이 하나로 정해진다. 따라서 분할의 수는 두 원소를 고르는 방법의 수와 같다.","확인":"10","스킬":"P3","고비":true},{"제목":"두 값의 곱 구하기","힌트":"$f(5)$와 $g(5)$를 곱하면 얼마인가?","식":["$f(5)\\times g(5)=10\\times4=40$"],"설명":"앞에서 구한 두 값을 곱한다.","확인":"40","스킬":"P3"}]},"ns-40433a04cb29":{"길":"c 사이 문자 수를 2·4·6으로 나누고 c와 사이 문자를 한 묶음으로 본다","단계":[{"제목":"c 사이 문자 수로 경우 나누기","힌트":"$c$를 뺀 문자는 $7$개이다. $c$ 사이에 들어갈 수 있는 짝수 개는 몇 개인가?","식":["사이 문자 수는 $2,\\ 4,\\ 6$ 중 하나","묶음 $X=c\\,\\cdots\\,c$를 한 문자로 본다"],"설명":"문제의 조건상 사이에 $2$개 이상의 짝수 개가 들어가므로 $2$개, $4$개, $6$개이다. 두 $c$와 사이 문자를 한 묶음으로 보면 묶음과 남은 문자를 일렬로 나열하는 문제가 된다.","확인":null,"스킬":"C2"},{"제목":"사이 문자가 2개인 경우 세기","힌트":"사이에 $aa$, $ab$ 또는 $ba$, $bb$ 가 들어갈 때 묶음과 남은 문자를 나열하면 각각 몇 가지인가?","식":["$caac$: $\\frac{6!}{4!}=30$","$cabc,\\ cbac$: $2\\times\\frac{6!}{2!\\,3!}=120$","$cbbc$: $\\frac{6!}{2!\\,3!}=60$"],"설명":"묶음 하나와 남은 문자 $5$개를 나열한다. 사이가 $ab$인 경우는 순서가 $2$가지이다. 세 경우를 모두 더한다.","확인":"210","스킬":"P3"},{"제목":"사이 문자가 4개인 경우 세기","힌트":"사이에 들어가는 문자 구성이 $a$와 $b$의 개수에 따라 네 가지이다. 각각 사이 문자의 순서와 묶음 배열을 곱하면?","식":["사이 $aaab$: $\\frac{4!}{3!}\\times\\frac{4!}{3!}=16$","사이 $aabb$: $\\frac{4!}{2!\\,2!}\\times\\frac{4!}{2!}=72$,  사이 $abbb$: $\\frac{4!}{3!}\\times\\frac{4!}{2!}=48$","사이 $bbbb$: $\\frac{4!}{3!}=4$"],"설명":"사이 문자를 나열하는 방법의 수와, 묶음과 남은 문자를 나열하는 방법의 수를 곱한다. 사이에 $a$가 $0$개부터 $3$개까지 들어가는 네 경우를 모두 더한다.","확인":"140","스킬":"P3","고비":true},{"제목":"사이 문자가 6개인 경우 세기","힌트":"사이 문자 $6$개의 구성은 두 가지뿐이다. 남은 문자는 몇 개이며 배열은 몇 가지인가?","식":["사이 $aaabbb$: $\\frac{6!}{3!\\,3!}\\times2!=40$","사이 $aabbbb$: $\\frac{6!}{2!\\,4!}\\times2!=30$"],"설명":"문자가 $7$개 중 $6$개가 사이에 들어가므로 남은 문자는 $1$개이고, 묶음과 남은 문자 $1$개의 배열은 $2!$이다.","확인":"70","스킬":"P3"},{"제목":"경우를 모두 합하기","힌트":"사이 문자 수가 $2$개, $4$개, $6$개인 경우의 수를 더하면?","식":["$210+140+70=420$"],"설명":"사이 문자 수가 다른 경우는 서로 겹치지 않으므로 합의 법칙을 쓴다.","확인":"420","스킬":"C2"}]},"ns-40d7399cffa1":{"길":"누가 무엇을 고르는지 보고 고르는 쪽의 수가 지수인 중복순열로 비교한다","단계":[{"제목":"①③④⑤의 경우의 수 구하기","힌트":"공·편지·투표자·$A$의 원소는 각각 몇 가지 중 하나를 고르는가?","식":["$3\\times3\\times3\\times3=3^{4}$","$3^{4}=81$"],"설명":"공, 편지, 투표자, 집합 $A$의 원소는 각각 $3$가지 중 하나를 정한다. $4$개의 대상이 정하므로 $3^{4}$이다.","확인":"81","스킬":"P3"},{"제목":"②의 경우의 수 구하기","힌트":"여행자 한 명은 호텔을 몇 곳 중에서 고르고, 몇 명이 고르는가?","식":["$4\\times4\\times4=4^{3}$","$4^{3}=64$"],"설명":"투숙하는 쪽은 여행자 $3$명이고 고르는 대상은 호텔 $4$곳이다. 한 명당 $4$가지씩 $3$명이 정하므로 $4^{3}$이다.","확인":"64","스킬":"P3","고비":true},{"제목":"값을 비교해 다른 하나 찾기","힌트":"$81$과 $64$ 중 하나만 다른 것은 어느 경우인가?","식":["①③④⑤는 $81$, ②는 $64$"],"설명":"네 경우는 $81$로 같고 ②만 $64$이다. 고르는 쪽의 수가 지수, 고르는 대상의 수가 밑이 된다.","확인":null,"스킬":"P3"}]},"ns-45a35a13d3a7":{"길":"좌표를 잡아 교차점마다 가는 방법의 수를 더하고 C, D는 0으로 둔다","단계":[{"제목":"교차점에 좌표 붙이기","힌트":"$\\mathrm{A}$에서 오른쪽 아래로 한 칸을 $x$, 오른쪽 위로 한 칸을 $y$로 세면 $\\mathrm{C}$, $\\mathrm{D}$, $\\mathrm{B}$의 좌표는?","식":["$\\mathrm{A}(0,\\,0),\\ \\mathrm{C}(4,\\,0)$","$\\mathrm{D}(4,\\,4),\\ \\mathrm{B}(6,\\,4)$"],"설명":"도로망은 폭이 한 칸인 세 개의 띠로 이어져 있다. $\\mathrm{A}$에서 오른쪽 아래로 $4$칸이 $\\mathrm{C}$, $\\mathrm{C}$에서 오른쪽 위로 $4$칸이 $\\mathrm{D}$, $\\mathrm{D}$에서 오른쪽 아래로 $2$칸이 $\\mathrm{B}$이다. 최단거리는 $x$나 $y$가 늘어나는 방향으로만 가는 경로이다.","확인":null,"스킬":"P4"},{"제목":"첫 번째 띠에서 방법의 수 적기","힌트":"교차점 $(3,\\,1)$에 오는 방법의 수를 구하려면 어느 두 점의 수를 더하는가?","식":["$(0,1),\\ (1,0),\\ (2,0),\\ (3,0)$은 모두 $1$","$(1,1)=2,\\ (2,1)=3,\\ (3,1)=3+1=4$","$(4,0)=\\mathrm{C}=0,\\ (4,1)=4+0=4$"],"설명":"한 교차점에는 왼쪽 위와 왼쪽 아래 두 방향에서만 올 수 있으므로 두 점의 수를 더한다. $\\mathrm{C}$는 지나지 않으므로 $0$으로 둔다.","확인":"4","스킬":"P4"},{"제목":"가운데 띠에서 방법의 수 적기","힌트":"$(3,\\,1)$과 $(4,\\,1)$에서 위로 올라가며 $(4,\\,3)$까지 각 교차점의 수는?","식":["$(3,2)=4,\\ (3,3)=4$","$(4,2)=4+4=8$","$(4,3)=4+8=12$"],"설명":"$x=3$ 줄의 점은 왼쪽 점이 길 밖이므로 아래 점의 수를 그대로 받는다. $x=4$ 줄은 왼쪽 점과 아래 점의 수를 더한다. $\\mathrm{D}(4,4)$는 지나지 않으므로 $0$이다.","확인":"12","스킬":"P4","고비":true},{"제목":"마지막 띠에서 B까지 더하기","힌트":"$\\mathrm{D}$를 $0$으로 두고 $(5,\\,3)$, $(5,\\,4)$, $(6,\\,3)$을 거쳐 $\\mathrm{B}$까지 더하면?","식":["$(5,3)=12,\\ (6,3)=12$","$(5,4)=0+12=12$","$\\mathrm{B}(6,4)=12+12=24$"],"설명":"$(5,3)$과 $(6,3)$은 아래 점이 길 밖이라 왼쪽 점의 수를 그대로 받는다. $(5,4)$는 $\\mathrm{D}$가 $0$이므로 아래 점의 수만 받는다. $\\mathrm{B}$는 $(5,4)$와 $(6,3)$의 수를 더한다.","확인":"24","스킬":"P2"}]},"ns-46499bea460d":{"길":"색 변화 횟수로 덩어리 수를 정해 ㄱ, ㄴ, ㄷ을 하나씩 세어 판정한다","단계":[{"제목":"ㄱ: 변화 횟수의 범위와 전체 배열","힌트":"색 변화는 최소 몇 번, 최대 몇 번 일어날 수 있는가?","식":["최소 $1$번, 최대 $8$번","$f(1)+\\cdots+f(8)=\\frac{11!}{4!\\,7!}={}_{11}\\mathrm{C}_{4}$"],"설명":"같은 색끼리 모이면 $1$번이고, 흰 공이 모두 떨어지고 양끝이 검은 공이면 최대 $8$번이다. $1$번부터 $8$번까지가 가능한 모든 경우이므로 합은 전체 배열의 수이고, ㄱ은 참이다.","확인":"330","스킬":"P3"},{"제목":"ㄴ: 양끝 색이 다른 배열의 수","힌트":"처음이 흰 공이고 끝이 검은 공인 배열은 몇 가지인가?","식":["양끝 색이 다르면 변화는 홀수 번","처음 흰 공·끝 검은 공: $\\frac{9!}{3!\\,6!}=84$","$f(1)+f(3)+f(5)+f(7)=84\\times2=168$"],"설명":"양끝이 같은 색이면 변화가 짝수 번이고 다른 색이면 홀수 번이다. 홀수 번의 합은 양끝 색이 다른 배열의 수이며, 흰-검과 검-흰이 같은 수이다. ㄴ은 참이다.","확인":"84","스킬":"P3"},{"제목":"ㄷ: 양끝이 흰 공인 경우 세기","힌트":"변화 $4$번이면 덩어리는 몇 개이고, 흰 공과 검은 공 덩어리는 각각 몇 개인가?","식":["덩어리 $5$개: 흰 공 $3$덩어리, 검은 공 $2$덩어리","흰 공 ${}_{3}\\mathrm{H}_{1}=3$, 검은 공 ${}_{2}\\mathrm{H}_{5}=6$","$3\\times6=18$"],"설명":"변화가 $4$번이면 덩어리가 $5$개이고 색이 번갈아 나온다. 양끝이 흰 공이면 흰 공이 $3$덩어리이다. 각 덩어리에 $1$개 이상씩 넣는 중복조합으로 센다.","확인":"18","스킬":"P3","고비":true},{"제목":"ㄷ: 양끝이 검은 공인 경우와 합","힌트":"검은 공 $3$덩어리, 흰 공 $2$덩어리일 때의 경우의 수를 더하면 $f(4)$는?","식":["검은 공 ${}_{3}\\mathrm{H}_{4}=15$, 흰 공 ${}_{2}\\mathrm{H}_{2}=3$, $15\\times3=45$","$f(4)=18+45=63$"],"설명":"검은 공 $7$개를 $3$덩어리에 $1$개 이상씩 나누는 방법은 ${}_{6}\\mathrm{C}_{2}=15$, 흰 공 $4$개를 $2$덩어리에 나누는 방법은 $3$이다. $f(4)=63$이므로 보기의 $45$와 다르고 ㄷ은 거짓이다.","확인":"63","스킬":"P3"},{"제목":"참·거짓 종합하기","힌트":"ㄱ, ㄴ, ㄷ 중 옳은 것은 무엇인가?","식":["ㄱ 참, ㄴ 참, ㄷ 거짓"],"설명":"ㄱ과 ㄴ은 참이고 ㄷ은 $f(4)=63$이라 거짓이다. 옳은 것만 고르면 ㄱ, ㄴ이다.","확인":null,"스킬":"C3"}]},"ns-468fa2257071":{"길":"흰 공 두 개의 자리 번호 차를 3·5·7로 보고 자리쌍 수와 나머지 배열 수를 곱한다","단계":[{"제목":"사이 공 개수 조건을 번호 차로 바꾸기","힌트":"서로 이웃하지 않고 사이 공 수가 짝수이면 사이 공은 몇 개일 수 있는가?","식":["사이 공 수 $2,\\ 4,\\ 6$","자리 번호의 차 $3,\\ 5,\\ 7$"],"설명":"공은 모두 $9$개이다. 이웃하지 않으므로 사이 공이 $0$개일 수 없고, 짝수이므로 $2$개, $4$개, $6$개이다. 사이 공이 $k$개이면 두 흰 공의 자리 번호 차는 $k+1$이다.","확인":null,"스킬":"P4"},{"제목":"흰 공 자리쌍의 수 세기","힌트":"$9$자리에서 번호 차가 $3$, $5$, $7$인 두 자리를 고르는 방법은 각각 몇 가지인가?","식":["차 $3$: $6$가지, 차 $5$: $4$가지, 차 $7$: $2$가지","$6+4+2=12$"],"설명":"번호 차가 $d$인 자리쌍은 $(9-d)$개이다. 차가 다른 경우는 서로 겹치지 않으므로 더한다.","확인":"12","스킬":"P4","고비":true},{"제목":"나머지 일곱 자리 배열하기","힌트":"흰 공 자리를 정하면 남은 $7$자리에 검은 공 $5$개, 파란 공 $2$개를 놓는 방법은 몇 가지인가?","식":["$\\frac{7!}{5!\\,2!}=21$"],"설명":"같은 색끼리는 구별하지 않으므로 같은 것이 있는 순열이다. 흰 공 자리와 나머지 공의 배열은 서로 영향을 주지 않는다.","확인":"21","스킬":"P3"},{"제목":"곱의 법칙으로 합치기","힌트":"흰 공 자리쌍의 수와 나머지 배열의 수를 곱하면 얼마인가?","식":["$12\\times21=252$"],"설명":"흰 공 자리를 정하는 일과 나머지 공을 배열하는 일이 차례로 일어나므로 곱한다.","확인":"252","스킬":"P3"}]},"ns-478f0b99a28e":{"길":"이동 순서를 x·y·z 나열로 보고 BF, EF를 지나는 조건을 순서 조건으로 바꾼다","단계":[{"제목":"최단 경로를 세 방향 이동의 나열로 보기","힌트":"$\\mathrm{A}$에서 $\\mathrm{G}$까지 최단으로 가려면 $x$, $y$, $z$ 방향으로 각각 몇 칸씩, 모두 몇 번 이동하는가?","식":["$x,\\ y,\\ z$ 방향 각각 $4$칸","이동 횟수 $4+4+4=12$"],"설명":"$\\mathrm{A}$를 원점으로 $\\overline{\\mathrm{AB}}$ 방향을 $x$, $\\overline{\\mathrm{BC}}$ 방향을 $y$, $\\overline{\\mathrm{AE}}$ 방향을 $z$로 둔다. $\\mathrm{G}$는 $(4,4,4)$이므로 최단 경로는 각 방향으로 $4$칸씩 되돌아가지 않고 간다. 경로는 $x$, $y$, $z$ 이동을 $4$번씩 늘어놓은 순서로 정해진다.","확인":"12","스킬":"P3"},{"제목":"변 BF를 지나는 경로 수 구하기","힌트":"$\\mathrm{BF}$ 위의 점은 $x=4,\\ y=0$이다. 이 점을 지나려면 $x$ 이동 $4$번과 $y$ 이동의 앞뒤 순서가 어때야 하는가?","식":["$x$ 이동 $4$번이 모두 $y$ 이동보다 앞","$z$ 이동의 자리 선택 ${}_{12}\\mathrm{C}_{4}=495$"],"설명":"$y$가 $0$인 채로 $x$가 $4$가 되어야 하므로 $x$ 이동이 모두 끝날 때까지 $y$ 이동이 없다. $z$ 이동 $4$번의 자리를 $12$자리 중에서 고르면 남은 $8$자리는 앞 $4$자리에 $x$, 뒤 $4$자리에 $y$를 놓는 $1$가지이다. 경로는 앞면과 오른쪽 면 위에 있어 겉면에서 벗어나지 않는다.","확인":"495","스킬":"P3","고비":true},{"제목":"변 EF를 지나는 경로 수 구하기","힌트":"$\\mathrm{EF}$ 위의 점은 $y=0,\\ z=4$이다. 앞 단계에서 $x$와 $z$의 역할을 바꾸면?","식":["$z$ 이동 $4$번이 모두 $y$ 이동보다 앞","$x$ 이동의 자리 선택 ${}_{12}\\mathrm{C}_{4}=495$"],"설명":"$x$와 $z$의 역할만 바뀌므로 같은 방법으로 센다. 경로는 앞면과 윗면 위에 있다.","확인":null,"스킬":"P3"},{"제목":"두 변을 모두 지나는 경로 수 구하기","힌트":"두 변을 모두 지나려면 $y$ 이동은 $x$, $z$ 이동과 어떤 순서여야 하는가?","식":["$y$ 이동 $4$번이 $x$, $z$ 이동 $8$번보다 모두 뒤","$\\frac{8!}{4!\\,4!}=70$"],"설명":"$\\mathrm{BF}$ 조건과 $\\mathrm{EF}$ 조건을 함께 만족하면 $x$, $z$ 이동이 모두 끝난 뒤에 $y$ 이동을 하므로 점 $\\mathrm{F}$를 지난다. 앞의 $8$번에 $x$ $4$번, $z$ $4$번을 나열하는 방법의 수이다.","확인":"70","스킬":"P3"},{"제목":"합의 법칙으로 합치기","힌트":"$\\mathrm{BF}$를 지나는 경로와 $\\mathrm{EF}$를 지나는 경로의 합에서 두 번 센 경로를 빼면?","식":["$495+495-70=920$"],"설명":"두 변을 모두 지나는 경로는 앞의 두 값에 모두 들어 있으므로 한 번 뺀다.","확인":"920","스킬":"P2"}]},"ns-48bb413d1218":{"길":"서점별 경로 수를 구하고 두 서점을 모두 지나는 경로를 두 번 뺀다","단계":[{"제목":"집-서점-학교 경로를 좌표로 나누기","힌트":"집에서 가까운 서점까지는 오른쪽과 위쪽으로, 서점에서 학교까지는 오른쪽과 아래쪽으로 몇 칸씩 가는가?","식":["집 $(0,0)$, 학교 $(4,0)$, 서점 $\\mathrm{P}(1,4),\\ \\mathrm{Q}(3,4)$","집에서 $\\mathrm{P}$까지 오른쪽 $1$칸, 위쪽 $4$칸","$\\mathrm{P}$에서 학교까지 오른쪽 $3$칸, 아래쪽 $4$칸"],"설명":"집을 원점으로 두면 가까운 서점 $\\mathrm{P}$는 $(1,4)$, 먼 서점 $\\mathrm{Q}$는 $(3,4)$이다. 서점을 거쳐 가는 최단거리는 서점까지 오른쪽·위쪽으로, 서점에서 학교까지 오른쪽·아래쪽으로 가는 경로이다.","확인":null,"스킬":"P3"},{"제목":"서점 한 곳을 지나는 경로 수 구하기","힌트":"$\\mathrm{P}$를 지나는 경로와 $\\mathrm{Q}$를 지나는 경로의 수를 각각 구하면?","식":["$\\mathrm{P}$ 경유: $\\frac{5!}{4!}\\times\\frac{7!}{3!\\,4!}=5\\times35=175$","$\\mathrm{Q}$ 경유: $\\frac{7!}{3!\\,4!}\\times\\frac{5!}{4!}=35\\times5=175$"],"설명":"집에서 $\\mathrm{P}$까지는 오른쪽 $1$칸과 위쪽 $4$칸을 나열하는 $5$가지이고, $\\mathrm{P}$에서 학교까지는 오른쪽 $3$칸과 아래쪽 $4$칸을 나열하는 $35$가지이다. $\\mathrm{Q}$는 앞뒤 순서만 바뀌어 같은 값이다.","확인":"175","스킬":"P3"},{"제목":"두 서점을 모두 지나는 경로 수 구하기","힌트":"집에서 $\\mathrm{P}$, $\\mathrm{P}$에서 $\\mathrm{Q}$, $\\mathrm{Q}$에서 학교까지 각각 몇 가지인가?","식":["$\\frac{5!}{4!}\\times1\\times\\frac{5!}{4!}=25$"],"설명":"$\\mathrm{P}$에서 $\\mathrm{Q}$까지는 오른쪽으로 $2$칸 곧바로 가는 $1$가지뿐이다.","확인":"25","스킬":"P3"},{"제목":"한 곳만 지나는 경로 수 합하기","힌트":"각 서점 경유 경로에는 두 서점을 모두 지나는 경로가 들어 있다. 한 곳만 지나는 경로를 합하면?","식":["$\\mathrm{P}$만: $175-25=150$","$\\mathrm{Q}$만: $175-25=150$","$150+150=300$"],"설명":"서점 한 곳만 들르는 경로는 서점별 경로에서 두 곳을 모두 지나는 경로를 뺀 것이다. 합하면 $175+175-2\\times25$와 같다.","확인":"300","스킬":"P2","고비":true}]},"ns-4a0059a97ffa":{"길":"전체 최단 경로에서 P 좌회전 경로와 Q 비직진 경로를 빼고 겹침을 더한다","단계":[{"제목":"전체 최단 경로 수 구하기","힌트":"오른쪽 $5$칸, 위쪽 $4$칸을 나열하는 방법은 몇 가지인가?","식":["$\\frac{9!}{5!\\,4!}=126$"],"설명":"$\\mathrm{A}$에서 $\\mathrm{B}$까지 최단으로 가면 오른쪽 $5$번, 위쪽 $4$번 이동한다. 같은 것이 있는 순열로 세고, 금지된 회전을 하는 경로를 뺄 것이다.","확인":"126","스킬":"P2"},{"제목":"P에서 좌회전하는 경로 수 구하기","힌트":"$\\mathrm{P}$의 왼쪽 점 $\\mathrm{P}_{1}$에서 들어와 $\\mathrm{P}$의 위쪽 점 $\\mathrm{P}_{2}$로 나가는 경로는 몇 가지인가?","식":["$\\mathrm{A}\\to\\mathrm{P}_{1}\\to\\mathrm{P}\\to\\mathrm{P}_{2}\\to\\mathrm{B}$","$2\\times1\\times\\frac{5!}{3!\\,2!}=20$"],"설명":"오른쪽으로 달려 $\\mathrm{P}$에 들어와 위쪽으로 꺾는 것이 좌회전이다. $\\mathrm{A}$에서 $\\mathrm{P}_{1}$까지 $2$가지, $\\mathrm{P}_{1}$에서 $\\mathrm{P}_{2}$까지 $\\mathrm{P}$를 지나는 $1$가지, $\\mathrm{P}_{2}$에서 $\\mathrm{B}$까지 오른쪽 $3$칸과 위쪽 $2$칸을 나열하는 $10$가지를 곱한다.","확인":"20","스킬":"P2"},{"제목":"Q에서 직진하지 않는 경로 수 구하기","힌트":"$\\mathrm{Q}$의 아래쪽 점 $\\mathrm{Q}_{1}$에서 들어와 오른쪽으로 꺾는 경우와, 왼쪽 점 $\\mathrm{Q}_{2}$에서 들어와 위쪽으로 꺾는 경우는 각각 몇 가지인가?","식":["$\\mathrm{Q}_{1}$에서 들어와 오른쪽: $\\frac{5!}{3!\\,2!}\\times2=20$","$\\mathrm{Q}_{2}$에서 들어와 위쪽: $\\frac{5!}{2!\\,3!}\\times1=10$"],"설명":"$\\mathrm{A}$에서 $\\mathrm{Q}_{1}$이나 $\\mathrm{Q}_{2}$까지는 각각 $10$가지이다. $\\mathrm{Q}$에서 오른쪽으로 꺾으면 $\\mathrm{B}$까지 $2$가지, 위쪽으로 꺾으면 $1$가지이다. 두 경우를 더한다.","확인":"30","스킬":"P2"},{"제목":"두 조건에 모두 걸리는 경로 수 구하기","힌트":"$\\mathrm{P}$에서 좌회전한 뒤 $\\mathrm{P}_{2}$를 거쳐 $\\mathrm{Q}$에서도 직진하지 않는 경로는 몇 가지인가?","식":["$\\mathrm{P}_{2}\\to\\mathrm{Q}_{1}\\to\\mathrm{Q}\\to$ 오른쪽: $2\\times1\\times1\\times2=4$","$\\mathrm{P}_{2}\\to\\mathrm{Q}_{2}\\to\\mathrm{Q}\\to$ 위쪽: $2\\times1\\times1\\times1=2$"],"설명":"$\\mathrm{A}$에서 $\\mathrm{P}_{2}$까지 $\\mathrm{P}$를 지나는 경로가 $2$가지이고, $\\mathrm{P}_{2}$에서 $\\mathrm{Q}_{1}$이나 $\\mathrm{Q}_{2}$까지 $1$가지씩이다. $\\mathrm{Q}$에서 꺾은 뒤 $\\mathrm{B}$까지의 가짓수를 곱한다. 앞 두 단계의 값에 겹쳐 들어 있는 경로이다.","확인":"6","스킬":"P2","고비":true},{"제목":"조건에 맞는 경로 수 구하기","힌트":"전체에서 두 조건에 걸리는 경로의 합을 겹침을 고려해 빼면?","식":["$126-(20+30-6)=82$"],"설명":"$\\mathrm{P}$ 좌회전 경로와 $\\mathrm{Q}$ 비직진 경로의 합집합은 $20+30-6=44$가지이다. 전체에서 뺀다.","확인":"82","스킬":"P2"}]},"ns-4e3dd6de56f8":{"길":"x+y=6인 점을 반드시 한 번 지남을 이용해 C를 뺀 점별 경로를 더한다","단계":[{"제목":"경로가 반드시 지나는 점 찾기","힌트":"$\\mathrm{A}$를 원점으로 $x+y=6$인 길 위의 점은 어디인가?","식":["$\\mathrm{B}(6,6)$까지 $12$번 이동","$x+y=6$인 점: $\\mathrm{D},\\ \\mathrm{E},\\ \\mathrm{F},\\ \\mathrm{C},\\ \\mathrm{G}$"],"설명":"오른쪽을 $x$, 위쪽을 $y$로 두면 한 번 이동할 때마다 $x+y$가 $1$씩 늘어 $12$번 만에 $\\mathrm{B}$에 닿는다. 따라서 $x+y=6$인 점을 정확히 한 번 지난다. 길 위의 그런 점은 $\\mathrm{D},\\ \\mathrm{E},\\ \\mathrm{F},\\ \\mathrm{C},\\ \\mathrm{G}$ 다섯 개이므로 $\\mathrm{C}$를 거치지 않는 경로는 나머지 네 점 중 하나를 지난다.","확인":null,"스킬":"P4"},{"제목":"D, E, F를 지나는 경로 수 구하기","힌트":"각 점까지 가는 경로 수와 각 점에서 $\\mathrm{B}$까지 가는 경로 수를 곱하면?","식":["$\\mathrm{D}$: $1\\times1=1$","$\\mathrm{E}$: $\\frac{6!}{5!}\\times\\frac{6!}{5!}=36$","$\\mathrm{F}$: $\\frac{6!}{4!\\,2!}\\times\\frac{6!}{4!\\,2!}=225$"],"설명":"$\\mathrm{D},\\ \\mathrm{E},\\ \\mathrm{F}$ 앞뒤의 경로는 계단 모양 경계에 닿지 않으므로 오른쪽·위쪽 나열로 센다. 세 값을 더하면 $262$이다.","확인":"262","스킬":"P3"},{"제목":"G를 지나는 경로 수 구하기","힌트":"$\\mathrm{G}$에는 어느 점에서 들어와 어느 점으로 나가는가? 길이 없는 경로는 몇 가지 빼야 하는가?","식":["$\\mathrm{A}$에서 $\\mathrm{G}_{1}$까지: $\\frac{5!}{2!\\,3!}-1=9$","$\\mathrm{G}_{2}$에서 $\\mathrm{B}$까지: $\\frac{5!}{2!\\,3!}-1=9$","$9\\times9=81$"],"설명":"$\\mathrm{G}$로 들어오는 길은 $\\mathrm{G}_{1}$에서 오른쪽뿐이고 나가는 길은 $\\mathrm{G}_{2}$로 위쪽뿐이다. $\\mathrm{A}$에서 오른쪽으로 $3$칸을 먼저 가는 $1$가지와, $\\mathrm{G}_{2}$에서 오른쪽으로 $2$칸을 먼저 가는 $1$가지는 길이 끊겨 있어 각각 뺀다.","확인":"81","스킬":"P2","고비":true},{"제목":"점별 경로 수 합하기","힌트":"$\\mathrm{D}$, $\\mathrm{E}$, $\\mathrm{F}$를 지나는 경우와 $\\mathrm{G}$를 지나는 경우를 더하면?","식":["$262+81=343$"],"설명":"서로 다른 점을 지나는 경로는 겹치지 않으므로 합의 법칙으로 더한다.","확인":"343","스킬":"P3"}]},"ns-4e7cdb8bee9d":{"길":"방향 전환 4번을 덩어리 5개로 보고 중복조합으로 센 뒤 끊긴 길을 뺀다","단계":[{"제목":"방향 전환 4번의 덩어리 구조 정하기","힌트":"방향이 $4$번 바뀌면 같은 방향으로 이어진 덩어리는 모두 몇 개이고, 어느 방향으로 시작할 수 있는가?","식":["덩어리 $5$개","$a\\,b\\,a\\,b\\,a$ 꼴, $b\\,a\\,b\\,a\\,b$ 꼴 두 가지"],"설명":"가로 이동을 $a$ $5$번, 세로 이동을 $b$ $4$번이라 하자. 방향이 $4$번 바뀌면 덩어리가 $5$개이고 $a$, $b$가 번갈아 나온다. $a$로 시작하면 $a$ $3$덩어리·$b$ $2$덩어리, $b$로 시작하면 $b$ $3$덩어리·$a$ $2$덩어리이다.","확인":null,"스킬":"P3"},{"제목":"a로 시작하는 경우 세기","힌트":"$a$ $5$개를 $3$덩어리에, $b$ $4$개를 $2$덩어리에 $1$개 이상씩 나누는 방법은 각각 몇 가지인가?","식":["$a$: 남는 $2$개를 $3$덩어리에 ${}_{3}\\mathrm{H}_{2}=6$","$b$: 남는 $2$개를 $2$덩어리에 ${}_{2}\\mathrm{H}_{2}=3$","$6\\times3=18$"],"설명":"덩어리마다 $1$개씩 먼저 놓고 남은 개수를 덩어리에 나누어 놓는 중복조합으로 센다. $a$의 배치와 $b$의 배치를 곱한다.","확인":"18","스킬":"P3","고비":true},{"제목":"b로 시작하는 경우 세기","힌트":"$b$ $4$개를 $3$덩어리에, $a$ $5$개를 $2$덩어리에 $1$개 이상씩 나누는 방법은 각각 몇 가지인가?","식":["$b$: 남는 $1$개를 $3$덩어리에 ${}_{3}\\mathrm{H}_{1}=3$","$a$: 남는 $3$개를 $2$덩어리에 ${}_{2}\\mathrm{H}_{3}=4$","$3\\times4=12$"],"설명":"같은 방법으로 센다. $b$가 $3$덩어리이므로 남는 $b$는 $4-3=1$개이고, $a$는 $2$덩어리이므로 남는 $a$는 $5-2=3$개이다.","확인":"12","스킬":"P3"},{"제목":"끊어진 길을 지나는 경우 세기","힌트":"끊어진 곳은 $x=3$에서 $y$가 $1$에서 $2$로 오르는 변이다. 지나는 경로의 앞쪽 이동 횟수는 어떠한가?","식":["$5$번째 이동이 $b$, 앞의 $4$번에 $a$ $3$번·$b$ $1$번","$aaabbabba,\\ aaabbbaba,\\ aababbbaa$","$abaabbbaa,\\ baaabaabb,\\ baaabbaab$"],"설명":"끊어진 변을 지나려면 $a$가 $3$번, $b$가 $1$번 일어난 뒤 다섯 번째로 $b$가 와야 한다. 다섯 번째가 $b$라는 조건과 방향 전환 $4$번을 함께 만족하는 배열을 세면 $6$가지이다.","확인":"6","스킬":"C2"},{"제목":"끊어진 길을 뺀 경로 수 구하기","힌트":"방향 전환이 $4$번인 전체 경우에서 끊어진 길을 지나는 경우를 빼면?","식":["$18+12=30$","$30-6=24$"],"설명":"방향 전환이 $4$번인 경로는 모두 $30$가지이고, 끊어진 길을 지나는 $6$가지는 갈 수 없으므로 뺀다.","확인":"24","스킬":"P2"}]},"ns-50b5210b9d6e":{"길":"등호가 막히는 두 곳을 여사건으로 보고 중복조합으로 센다","단계":[{"제목":"순서쌍 전체의 개수 구하기","힌트":"눈의 수 $1$부터 $6$ 중 중복을 허락해 $5$개를 고르는 방법은 몇 가지인가?","식":["$x_{1}\\le x_{2}\\le x_{3}\\le x_{4}\\le x_{5}$","$n(S)={}_{6}\\mathrm{H}_{5}={}_{10}\\mathrm{C}_{5}=252$"],"설명":"눈이 나오는 순서를 무시하고 작은 수부터 나열하므로 순서쌍 하나는 중복을 허락한 선택 하나와 같다. 확률은 $S$의 원소 하나를 고르는 것이므로 분모는 $n(S)$이다.","확인":"252","스킬":"P3"},{"제목":"한 곳이 등호인 경우 세기","힌트":"$x_{2}=x_{3}$이면 자유롭게 고르는 값은 몇 개인가?","식":["$x_{1}\\le x_{2}=x_{3}\\le x_{4}\\le x_{5}$: ${}_{6}\\mathrm{H}_{4}={}_{9}\\mathrm{C}_{4}=126$","$x_{4}=x_{5}$인 경우도 같은 방법으로 $126$"],"설명":"$x_{2}=x_{3}$이면 $x_{1},\\ x_{2},\\ x_{4},\\ x_{5}$ $4$개를 중복을 허락해 고르는 문제가 된다. $x_{4}=x_{5}$도 마찬가지이다.","확인":"126","스킬":"P2"},{"제목":"겹침을 보정해 조건에 맞는 경우 구하기","힌트":"$x_{2}=x_{3}$이고 $x_{4}=x_{5}$인 경우는 몇 가지인가? 전체에서 막히는 경우를 빼면?","식":["$x_{1}\\le x_{2}=x_{3}\\le x_{4}=x_{5}$: ${}_{6}\\mathrm{H}_{3}={}_{8}\\mathrm{C}_{3}=56$","$252-(126+126-56)=56$"],"설명":"두 등호가 동시에 성립하는 경우는 앞의 두 값에 모두 들어 있으므로 한 번 더해 준다. 부등호 조건을 만족하는 순서쌍은 전체에서 한 곳이라도 등호인 경우를 뺀 것이다.","확인":"56","스킬":"P2","고비":true},{"제목":"확률과 90p 구하기","힌트":"$p=\\frac{56}{252}$일 때 $90p$는 얼마인가?","식":["$p=\\frac{56}{252}=\\frac{2}{9}$","$90p=90\\times\\frac{2}{9}=20$"],"설명":"조건을 만족하는 경우의 수를 전체 경우의 수로 나눈다.","확인":"20","스킬":"P3"}]},"ns-53a8cf406031":{"길":"A의 원소를 먼저 고르고 B는 남은 원소의 공집합 아닌 부분집합으로 센다","단계":[{"제목":"집합 A 정하기","힌트":"$n(A)=1$이면 $A$는 전체집합의 원소 중 어느 하나인가? 몇 가지인가?","식":["$A=\\{x\\}$, $x\\in U$","$A$의 경우의 수 $7$"],"설명":"$A$는 원소가 하나뿐인 집합이므로 $U$의 원소 $7$개 중 하나를 고르는 경우와 같다.","확인":"7","스킬":"P4"},{"제목":"집합 B 정하기","힌트":"$A\\cap B=\\varnothing$이면 $B$의 원소는 어느 범위에서 고르고, $B$가 공집합이면 안 되는 것은 어떻게 처리하는가?","식":["$B\\subset U-A$, $n(U-A)=6$","$2^{6}-1=63$"],"설명":"$B$는 $A$의 원소를 포함할 수 없으므로 남은 $6$개의 부분집합이다. 부분집합은 $2^{6}$개이고 $n(B)\\ge1$이므로 공집합 $1$개를 뺀다.","확인":"63","스킬":"P2","고비":true},{"제목":"곱의 법칙으로 합치기","힌트":"$A$를 정하는 경우와 $B$를 정하는 경우를 곱하면?","식":["$7\\times63=441$"],"설명":"$A$를 정한 다음 $B$를 정하는 일이 차례로 일어나므로 곱한다.","확인":"441","스킬":"P3"}]},"ns-5511e2ca95a0":{"길":"소인수마다 가로·세로·높이 중 하나에 배정하고 가로·세로 교환을 보정한다","단계":[{"제목":"부피 30030의 소인수 구조 알기","힌트":"$30030$을 소인수분해하면 서로 다른 소수는 몇 개인가?","식":["$30030=2\\times3\\times5\\times7\\times11\\times13$"],"설명":"소수가 모두 서로 다르고 지수는 $1$이다. 가로·세로·높이의 곱이 $30030$이므로 소인수 하나하나가 세 길이 중 어느 하나에 들어간다.","확인":"6","스킬":"N1"},{"제목":"순서가 있는 (가로, 세로, 높이) 개수 구하기","힌트":"소인수 $6$개는 각각 가로, 세로, 높이 중 어디에 들어갈 수 있는가?","식":["소인수 하나당 $3$가지","$3^{6}=729$"],"설명":"소인수 하나마다 세 길이 중 어느 하나에 곱해지는 경우가 $3$가지이다. 가로, 세로, 높이를 구별한 순서쌍의 수이다.","확인":"729","스킬":"P3"},{"제목":"가로와 세로가 같은 경우 찾기","힌트":"가로와 세로가 같은 값 $a$이면 $a^{2}$이 $30030$의 약수여야 한다. 가능한 $a$는?","식":["$a^{2}\\mid30030$이면 $a=1$","$(1,\\ 1,\\ 30030)$ $1$가지"],"설명":"$30030$은 제곱인수가 없으므로 $a^{2}$이 약수이려면 $a=1$이다. 윗면이 없는 그릇은 가로와 세로를 바꿔도 같은 그릇이지만 높이는 바꿀 수 없다.","확인":null,"스킬":"N1","고비":true},{"제목":"서로 다른 그릇의 개수 구하기","힌트":"가로·세로를 바꾼 쌍을 하나로 보면 순서쌍 $729$개 중 서로 다른 그릇은 몇 개인가?","식":["$\\frac{729-1}{2}+1=365$"],"설명":"가로와 세로가 다른 순서쌍은 둘씩 짝지어 같은 그릇이므로 $(729-1)\\div2$개이고, 가로와 세로가 같은 $1$가지를 더한다.","확인":"365","스킬":"P3"}]},"ns-559fa6c195ed":{"길":"빈 필통을 허용한 전체에서 포함배제로 빈 필통이 생기는 경우를 뺀다","단계":[{"제목":"빈 필통을 허용한 전체 경우 구하기","힌트":"연필 $3$자루와 볼펜 $5$자루를 필통 $3$개에 나누는 중복조합은 각각 몇 가지인가?","식":["연필 ${}_{3}\\mathrm{H}_{3}=10$, 볼펜 ${}_{3}\\mathrm{H}_{5}=21$","$10\\times21=210$"],"설명":"같은 종류끼리는 구별하지 않고 필통만 구별하므로 중복조합으로 센다. 연필과 볼펜의 나누는 방법은 서로 독립이다.","확인":"210","스킬":"P3"},{"제목":"특정 필통이 비는 경우 세기","힌트":"한 필통이 비면 나머지 필통 $2$개에 연필과 볼펜을 나누는 방법은 몇 가지이고, 비는 필통을 고르는 방법은 몇 가지인가?","식":["연필 ${}_{2}\\mathrm{H}_{3}=4$, 볼펜 ${}_{2}\\mathrm{H}_{5}=6$","$3\\times4\\times6=72$"],"설명":"비는 필통을 하나 정하면 나머지 둘에만 나누어 넣는다. 필통이 하나 이상 비는 경우를 센 값이지만 두 필통이 동시에 비는 경우를 두 번 센 상태이다.","확인":"72","스킬":"P2"},{"제목":"겹침을 보정해 합치기","힌트":"필통 두 개가 동시에 비는 경우는 몇 가지이고, 전체에서 빼고 더한 결과는?","식":["두 필통이 빔: ${}_{3}\\mathrm{C}_{2}\\times1=3$","$210-72+3=141$"],"설명":"두 필통이 비면 나머지 한 필통에 모두 넣는 $1$가지이다. 빈 필통을 하나씩 센 값 $72$에는 두 필통이 비는 경우가 두 번씩 들어 있으므로 한 번 되돌려 더한다. 세 필통이 모두 비는 경우는 없다.","확인":"141","스킬":"P2","고비":true}]},"ns-56bd109eae4a":{"길":"1이 연속하는 길이별로 세고 1001로 시작하는 경우와 겹침을 뺀다","단계":[{"제목":"1이 정확히 4개 연속하는 경우 세기","힌트":"$1111$이 맨 앞, 맨 뒤, 중간에 놓이는 경우를 나누어 앞뒤 자리를 채우면 몇 가지인가?","식":["맨 앞 $11110\\square\\square\\square$, 맨 뒤 $\\square\\square\\square01111$: $2\\times2^{3}=16$","중간 $0\\,1111\\,0$ 앞뒤 $2$자리: $3\\times2^{2}=12$","$16+12=28$"],"설명":"$1$이 정확히 $4$개 연속이려면 $1111$의 양옆이 $0$이거나 끝이어야 한다. 중간에 놓이면 $0$을 포함한 여섯 자리 묶음의 앞뒤로 남는 두 자리를 $(2,0),\\ (1,1),\\ (0,2)$로 나누어 센다.","확인":"28","스킬":"P4","고비":true},{"제목":"1이 5개 이상 연속하는 경우 세기","힌트":"연속하는 $1$의 개수가 $5$, $6$, $7$, $8$일 때를 같은 방법으로 세어 더하면?","식":["$5$개: $2\\times2^{2}+2\\times2=12$, $6$개: $2\\times2+1=5$","$7$개: $2$, $8$개: $1$"],"설명":"연속하는 개수가 늘수록 남는 자리가 줄어든다. $12+5+2+1$을 더한다. $1$이 연속해서 $4$개 이상인 경우는 길이가 서로 달라 겹치지 않는다.","확인":"20","스킬":"P4"},{"제목":"1001로 시작하는 경우와 겹침 구하기","힌트":"$1001$로 시작하면 남은 네 자리는 자유이다. 그중 $1$이 $4$개 이상 연속하는 것은 어느 경우인가?","식":["$1001\\square\\square\\square\\square$: $2^{4}=16$","겹침: $10011110,\\ 10011111$"],"설명":"남은 네 자리 중 $1$이 연속해서 $4$개 이상이 되려면 $1001$의 마지막 $1$ 뒤로 $111$이 이어져야 한다. 남은 네 자리가 $1110$ 또는 $1111$인 $2$가지가 겹친다.","확인":"16","스킬":"P2"},{"제목":"합집합 개수 구하기","힌트":"$1$이 $4$개 이상 연속하는 경우와 $1001$로 시작하는 경우를 더하고 겹침을 빼면?","식":["$(28+20)+16-2=62$"],"설명":"$1$이 $4$개 이상 연속하는 경우는 $48$가지이다. 두 조건 중 하나라도 만족하는 경우의 수는 합에서 겹침을 한 번 뺀다.","확인":"62","스킬":"P2"}]},"ns-572e8af14ce5":{"길":"빈 사물함을 허용한 전체에서 빈 사물함이 둘인 경우를 뺀다","단계":[{"제목":"제한 없이 나누는 경우 구하기","힌트":"책 한 권은 사물함 $3$곳 중 몇 곳에 넣을 수 있고, 책은 모두 몇 권인가?","식":["$3\\times3\\times3\\times3\\times3=3^{5}$","$3^{5}=243$"],"설명":"책이 서로 다르므로 책마다 사물함 $3$곳 중 하나를 고르는 중복순열이다.","확인":"243","스킬":"P3"},{"제목":"빈 사물함이 둘인 경우 찾기","힌트":"빈 사물함이 최대 $1$개이면 빼야 하는 경우는 어떤 배치인가?","식":["빈 사물함 $2$개: 한 사물함에 책 $5$권을 모두 넣음","사물함 선택 $3$가지"],"설명":"빈 사물함은 $0$개이거나 $1$개여야 하므로 빈 사물함이 $2$개인 경우만 빼면 된다. 빈 사물함이 $2$개이면 한 사물함에 모든 책이 들어간다.","확인":null,"스킬":"P2","고비":true},{"제목":"전체에서 빼서 구하기","힌트":"$243$에서 한 사물함에 모두 넣는 경우를 빼면?","식":["$243-3=240$"],"설명":"빈 사물함이 최대 $1$개인 경우의 수는 제한 없는 경우에서 빈 사물함이 $2$개인 $3$가지를 뺀 값이다.","확인":"240","스킬":"P2"}]},"ns-5b540ce228b8":{"길":"ㄱ, ㄴ으로 각 자리의 하한을 정하고 a₂의 값별로 가능한 수를 센다","단계":[{"제목":"조건으로 각 자리의 범위 줄이기","힌트":"$a_{1}$이 가장 작은 수이고 $a_{1}\\ne1$이면 네 자리에 쓸 수 있는 수의 범위는?","식":["$a_{1}\\ge2,\\ a_{2}\\ge3,\\ a_{3}\\ge4,\\ a_{4}\\ge5$","$a_{4}=5$"],"설명":"$a_{1}$이 가장 작은 수이고 $a_{1}\\ne1$이므로 네 수는 모두 $2$ 이상이다. $a_{2}\\ge a_{1}\\ge2$이고 $a_{2}\\ne2$이므로 $a_{2}\\ge3$이다. 같은 방법으로 $a_{3}\\ge4$, $a_{4}\\ge5$이므로 $a_{4}=5$이다.","확인":null,"스킬":"P4"},{"제목":"a₂의 값별로 a₁, a₃ 고르기","힌트":"$a_{2}$를 $3,\\ 4,\\ 5$로 정하면 $a_{1}$과 $a_{3}$을 고르는 방법은 각각 몇 가지인가?","식":["$a_{2}=3$: $a_{1}\\in\\{2,3\\}$, $a_{3}\\in\\{4,5\\}$이므로 $2\\times2=4$","$a_{2}=4$: $a_{1}\\in\\{2,3,4\\}$, $a_{3}\\in\\{4,5\\}$이므로 $3\\times2=6$","$a_{2}=5$: $a_{1}\\in\\{2,3,4,5\\}$, $a_{3}=5$이므로 $4\\times1=4$"],"설명":"$a_{2}$가 정해지면 $a_{1}$은 $2$ 이상 $a_{2}$ 이하, $a_{3}$은 $a_{2}$ 이상이면서 $4$ 이상 $5$ 이하이다. 두 선택이 서로 영향을 주지 않으므로 곱한다.","확인":null,"스킬":"P4","고비":true},{"제목":"경우를 모두 더하기","힌트":"$a_{2}$가 $3,\\ 4,\\ 5$인 경우의 수를 더하면?","식":["$4+6+4=14$"],"설명":"$a_{2}$의 값이 다르면 서로 다른 수이므로 합의 법칙으로 더한다.","확인":"14","스킬":"P4"}]},"ns-5c7faa40739f":{"길":"전체에서 같은 문자가 이웃하는 경우를 포함배제로 뺀다","단계":[{"제목":"제한 없이 나열하는 경우 구하기","힌트":"같은 문자가 $2$개씩 세 종류, 하나뿐인 문자 $d$를 일렬로 나열하는 방법은?","식":["$\\frac{7!}{2!\\,2!\\,2!}=630$"],"설명":"같은 것이 있는 순열이다. 이웃하는 경우를 뺄 것이므로 전체를 먼저 구한다.","확인":"630","스킬":"P2"},{"제목":"한 종류가 이웃하는 경우 구하기","힌트":"$a$ $2$개를 한 문자로 묶으면 몇 개의 문자를 나열하는가? $a,\\ b,\\ c$에 대해 합하면?","식":["$a$가 이웃: $\\frac{6!}{2!\\,2!}=180$","$b$, $c$도 같으므로 $180\\times3=540$"],"설명":"$a$ $2$개를 하나로 묶으면 문자 $6$개 중 $b$와 $c$가 $2$개씩이다. $b$나 $c$가 이웃하는 경우도 같은 값이다.","확인":"540","스킬":"P2"},{"제목":"겹침을 보정해 이웃하는 경우 구하기","힌트":"두 종류가 동시에 이웃하는 경우와 세 종류가 모두 이웃하는 경우는 각각 몇 가지이고, 합하면?","식":["두 종류가 이웃: $\\frac{5!}{2!}\\times3=180$","세 종류가 이웃: $4!=24$","$540-180+24=384$"],"설명":"한 종류씩 센 $540$에는 두 종류가 이웃하는 경우가 두 번, 세 종류가 이웃하는 경우가 세 번 들어 있다. 포함배제로 두 종류 이웃하는 경우를 빼고 세 종류 이웃하는 경우를 더한다.","확인":"384","스킬":"P2","고비":true},{"제목":"전체에서 빼서 구하기","힌트":"전체 경우에서 같은 문자가 이웃하는 경우를 빼면?","식":["$630-384=246$"],"설명":"같은 문자끼리 이웃하지 않는 경우는 전체에서 한 종류라도 이웃하는 경우를 뺀 것이다.","확인":"246","스킬":"P2"}]},"ns-5d84e7a88f03":{"길":"B, C를 지나는 경로를 빼고 둘 다 지나는 경로를 다시 더한다","단계":[{"제목":"전체 최단 경로 수 구하기","힌트":"$\\mathrm{A}$에서 $\\mathrm{D}$까지 오른쪽 몇 칸, 위쪽 몇 칸을 나열하는가?","식":["오른쪽 $5$칸, 위쪽 $5$칸","$\\frac{10!}{5!\\,5!}=252$"],"설명":"각 지점에서 오른쪽이나 위쪽으로만 이동한다. $\\mathrm{A}$를 원점으로 두면 $\\mathrm{B}(2,2)$, $\\mathrm{C}(4,3)$, $\\mathrm{D}(5,5)$이다.","확인":"252","스킬":"P2"},{"제목":"B를 지나는 경로 수 구하기","힌트":"$\\mathrm{A}$에서 $\\mathrm{B}$, $\\mathrm{B}$에서 $\\mathrm{D}$까지 가는 방법의 수를 각각 구해 곱하면?","식":["$\\mathrm{A}\\to\\mathrm{B}$: $\\frac{4!}{2!\\,2!}=6$","$\\mathrm{B}\\to\\mathrm{D}$: $\\frac{6!}{3!\\,3!}=20$","$6\\times20=120$"],"설명":"$\\mathrm{B}$를 거치는 경로는 앞 구간과 뒤 구간을 따로 센 뒤 곱한다.","확인":"120","스킬":"P3"},{"제목":"C를 지나는 경로 수 구하기","힌트":"$\\mathrm{A}$에서 $\\mathrm{C}$, $\\mathrm{C}$에서 $\\mathrm{D}$까지 가는 방법의 수를 각각 구해 곱하면?","식":["$\\mathrm{A}\\to\\mathrm{C}$: $\\frac{7!}{4!\\,3!}=35$","$\\mathrm{C}\\to\\mathrm{D}$: $\\frac{3!}{1!\\,2!}=3$","$35\\times3=105$"],"설명":"$\\mathrm{C}$까지는 오른쪽 $4$칸, 위쪽 $3$칸이고 $\\mathrm{C}$에서 $\\mathrm{D}$까지는 오른쪽 $1$칸, 위쪽 $2$칸이다.","확인":"105","스킬":"P3"},{"제목":"B, C를 모두 지나는 경로 수 구하기","힌트":"$\\mathrm{A}$에서 $\\mathrm{B}$, $\\mathrm{B}$에서 $\\mathrm{C}$, $\\mathrm{C}$에서 $\\mathrm{D}$까지 가는 방법의 수를 모두 곱하면?","식":["$\\mathrm{B}\\to\\mathrm{C}$: $\\frac{3!}{2!\\,1!}=3$","$6\\times3\\times3=54$"],"설명":"$\\mathrm{B}$를 지나는 경로와 $\\mathrm{C}$를 지나는 경로에 모두 들어 있는 경로이다. 두 값을 더할 때 두 번 세어지므로 한 번 빼야 한다.","확인":"54","스킬":"P2","고비":true},{"제목":"둘 다 지나지 않는 경로 수 구하기","힌트":"전체에서 B 또는 C를 지나는 경로를 빼면?","식":["$252-(120+105-54)=81$"],"설명":"$\\mathrm{B}$ 또는 $\\mathrm{C}$를 지나는 경로의 수는 $120+105-54=171$이다. 전체에서 빼면 둘 다 거치지 않는 경로의 수가 된다.","확인":"81","스킬":"P2"}]},"ns-5e47023d3206":{"길":"소인수 다섯 개를 빈 묶음 없이 세 묶음으로 나누는 경우로 바꾼다","단계":[{"제목":"15015의 소인수 구조 알기","힌트":"$15015$를 소인수분해하면 서로 다른 소수는 몇 개인가?","식":["$15015=3\\times5\\times7\\times11\\times13$"],"설명":"소수가 모두 서로 다르고 지수는 $1$이다. $1$보다 큰 세 수의 곱으로 나타내는 것은 소수 다섯 개를 빈 묶음 없이 세 묶음으로 나누어 각 묶음의 곱을 세 수로 두는 것과 같다. 곱하는 순서는 구별하지 않는다.","확인":"5","스킬":"N1"},{"제목":"묶음 크기가 3, 1, 1인 경우 세기","힌트":"소수 $5$개 중 $3$개를 한 묶음으로 고르면 나머지 $2$개는 각각 한 묶음이다. 몇 가지인가?","식":["묶음 크기 $3,\\ 1,\\ 1$: ${}_{5}\\mathrm{C}_{3}=10$"],"설명":"크기가 $1$인 두 묶음은 구별되지 않으므로 $3$개를 고르는 방법의 수가 곧 경우의 수이다. 묶음 크기의 합이 $5$이고 모두 $1$ 이상인 경우는 $(3,1,1)$과 $(2,2,1)$뿐이다.","확인":"10","스킬":"P3"},{"제목":"묶음 크기가 2, 2, 1인 경우 세기","힌트":"크기 $1$인 묶음을 먼저 고르고 나머지 $4$개를 $2$개씩 두 묶음으로 나누면 몇 가지인가?","식":["${}_{5}\\mathrm{C}_{1}\\times\\frac{{}_{4}\\mathrm{C}_{2}}{2!}=5\\times3=15$"],"설명":"나머지 네 소수에서 $2$개를 고르면 남은 $2$개는 자동으로 다른 묶음이 된다. 크기가 같은 두 묶음은 순서를 구별하지 않으므로 $2!$로 나눈다.","확인":"15","스킬":"P3","고비":true},{"제목":"경우를 모두 더하기","힌트":"묶음 크기가 $(3,1,1)$인 경우와 $(2,2,1)$인 경우를 더하면?","식":["$10+15=25$"],"설명":"묶음 크기가 다르면 서로 겹치지 않으므로 합의 법칙으로 더한다.","확인":"25","스킬":"P3"}]},"ns-5effb0ab63b0":{"길":"h의 개수로 경우를 나누고 f, g가 같은 칸에 섞이지 않게 칸별로 배정한다","단계":[{"제목":"이동 횟수의 관계와 금지 조건 정리","힌트":"$h$를 $k$번 쓰면 $f$와 $g$는 각각 몇 번 써야 하는가?","식":["$f,\\ g$는 각각 $8-2k$번","$f$와 $g$는 서로 이웃할 수 없다"],"설명":"$h$는 $x$, $y$를 모두 $2$씩 옮기므로 $f$와 $g$는 각각 $8-2k$번씩 쓴다. $f$와 $g$가 이웃할 수 없으므로 $h$가 나눈 $k+1$개의 칸마다 $f$만 있거나 $g$만 있거나 비어 있다. $k=0$이면 한 칸에 $f$와 $g$가 모두 들어가야 하므로 불가능하다.","확인":null,"스킬":"C2"},{"제목":"h가 1번 또는 4번인 경우 세기","힌트":"$h$가 $1$번이면 칸이 $2$개이다. $f$ $6$번과 $g$ $6$번은 칸에 어떻게 들어가는가?","식":["$k=1$: $f$칸과 $g$칸이 한 칸씩 → $2$가지","$k=4$: $f$, $g$를 쓰지 않으므로 $hhhh$ → $1$가지"],"설명":"$k=1$이면 두 칸에 $f$ $6$번, $g$ $6$번이 따로 들어가므로 어느 칸이 $f$인지만 정하면 된다. $k=4$이면 $8-2k=0$이다.","확인":null,"스킬":"P4"},{"제목":"h가 2번인 경우 세기","힌트":"$h$가 $2$번이면 칸이 $3$개이다. $f$가 들어가는 칸과 $g$가 들어가는 칸을 겹치지 않게 고르는 방법은?","식":["$f$ 한 칸·$g$ 한 칸: $3\\times2=6$","$f$ 한 칸·$g$ 두 칸: $3\\times{}_{3}\\mathrm{C}_{1}=9$","$f$ 두 칸·$g$ 한 칸: $3\\times{}_{3}\\mathrm{C}_{1}=9$"],"설명":"$f$ $4$번을 $r$칸에 $1$번 이상씩 나누는 방법은 ${}_{3}\\mathrm{C}_{r-1}$이다. $f$와 $g$가 쓰는 칸은 겹치지 않으므로 $3$칸 중 $f$ 칸, $g$ 칸을 정한 뒤 각각 나누는 방법을 곱한다. 세 경우의 합은 $24$이다.","확인":"24","스킬":"C2","고비":true},{"제목":"h가 3번인 경우 세기","힌트":"$h$가 $3$번이면 칸이 $4$개이고 $f$, $g$는 각각 $2$번이다. 칸을 고르는 경우별로 세면?","식":["$f$ 한 칸·$g$ 한 칸: $4\\times3=12$","$f$ 한 칸·$g$ 두 칸 $12$, $f$ 두 칸·$g$ 한 칸 $12$","$f$ 두 칸·$g$ 두 칸: ${}_{4}\\mathrm{C}_{2}=6$"],"설명":"$f$ $2$번은 한 칸에 모두 넣거나 두 칸에 $1$번씩 넣는다. $g$도 같다. 칸을 고르는 방법에 나누는 방법을 곱해 더하면 $12+12+12+6$이다.","확인":"42","스킬":"C2"},{"제목":"h의 개수별 경우를 모두 더하기","힌트":"$h$가 $1,\\ 2,\\ 3,\\ 4$번인 경우의 수를 더하면?","식":["$2+24+42+1=69$"],"설명":"$h$의 개수가 다르면 서로 다른 경로이므로 합의 법칙으로 더한다. $h$가 $0$번인 경우는 불가능하다.","확인":"69","스킬":"C2"}]},"ns-6077327bb777":{"길":"정육면체를 먼저 칠해 회전을 없앤 뒤 정팔면체 면은 모두 구별해 센다","단계":[{"제목":"정육면체에 쓸 색 고르기","힌트":"서로 다른 $14$색 중 정육면체 여섯 면에 쓸 색을 고르는 방법은 몇 가지인가?","식":["${}_{14}\\mathrm{C}_{6}=3003$"],"설명":"$14$색을 모두 쓰므로 정육면체에 $6$색, 정팔면체에 나머지 $8$색을 쓴다. 정육면체에 쓸 색을 먼저 고른다.","확인":"3003","스킬":"P3"},{"제목":"정육면체를 칠하는 방법 구하기","힌트":"특정한 색을 윗면에 놓으면 아랫면과 옆면 네 개는 각각 몇 가지로 칠할 수 있는가?","식":["아랫면 $5$가지","옆면 $(4-1)!=6$가지","$5\\times6=30$"],"설명":"돌려서 같아지는 것은 같은 방법이다. 특정한 색의 면을 윗면으로 놓아 회전을 고정하면 아랫면은 남은 $5$색 중 하나이고, 옆면 네 개는 원순열이므로 $(4-1)!$이다.","확인":"30","스킬":"P3","고비":true},{"제목":"정팔면체를 칠하는 방법 구하기","힌트":"정육면체의 칠이 정해지면 정팔면체의 여덟 면은 서로 구별되는가? 남은 $8$색으로 칠하는 방법은?","식":["$8!=40320$"],"설명":"정팔면체의 면은 정육면체의 꼭짓점마다 하나씩 놓여 있다. 정육면체의 여섯 면 색이 모두 달라 회전으로 겹치는 경우가 없으므로 정팔면체의 여덟 면은 모두 구별된다.","확인":"40320","스킬":"P3"},{"제목":"세 값을 곱해 정리하기","힌트":"$3003\\times30\\times8!$을 $11!$을 이용한 꼴로 고치면?","식":["$3003\\times30\\times8!=91\\times(33\\times30)\\times8!$","$33\\times30=11\\times10\\times9$이므로 $91\\times11\\times10\\times9\\times8!=91\\times11!$"],"설명":"$3003=91\\times33$이고 $33\\times30=990=11\\times10\\times9$이다. $11\\times10\\times9\\times8!=11!$이므로 구하는 방법의 수는 $91\\times11!$이다.","확인":null,"스킬":"P3"}]},"ns-619eb43f3432":{"길":"파란 전구 개수별로 먼저 사이에 빨간 전구를 놓고 남은 전구를 중복조합으로 배분한다","단계":[{"제목":"파란 전구 1개인 경우 세기","힌트":"파란 전구 앞뒤에 놓는 빨간 전구를 $x$, $y$개, 쓰지 않는 빨간 전구를 $z$개라 하면 $x+y+z$는 얼마인가?","식":["$x+y+z=6$의 음이 아닌 정수해: ${}_{3}\\mathrm{H}_{6}={}_{8}\\mathrm{C}_{6}=28$","$x=y=0$ 제외: $28-1=27$"],"설명":"빨간 전구가 $1$개 이상이어야 하므로 앞뒤의 빨간 전구는 합이 $1$ 이상 $6$ 이하이다. 쓰지 않는 빨간 전구 수 $z$를 두면 $x+y+z=6$이고, 빨간 전구가 없는 $x=y=0$은 뺀다.","확인":"27","스킬":"P3"},{"제목":"파란 전구 2개인 경우 세기","힌트":"파란 전구 둘 사이에 빨간 전구를 먼저 $1$개 놓으면 앞·사이·뒤에 더 놓는 빨간 전구 수 $x,\\ y,\\ z$는 합이 얼마 이하인가?","식":["$x+y+z\\le5$","$w=5-(x+y+z)$로 두면 $x+y+z+w=5$","${}_{4}\\mathrm{H}_{5}={}_{8}\\mathrm{C}_{5}=56$"],"설명":"파란 전구가 이웃하지 않으려면 둘 사이에 빨간 전구가 $1$개 이상 있어야 한다. 하나를 먼저 놓고 남은 $5$개 이하를 앞·사이·뒤에 나누어 놓는다. 빨간 전구가 이미 있으므로 $x=y=z=0$도 가능하다.","확인":"56","스킬":"P4","고비":true},{"제목":"파란 전구 3개인 경우 세기","힌트":"파란 전구 사이 두 곳에 빨간 전구를 $1$개씩 먼저 놓으면 남은 빨간 전구는 몇 개 이하인가?","식":["$x+y+z+w\\le4$","$v=4-(x+y+z+w)$로 두면 $x+y+z+w+v=4$","${}_{5}\\mathrm{H}_{4}={}_{8}\\mathrm{C}_{4}=70$"],"설명":"$x,\\ y,\\ z,\\ w$는 앞, 첫째 사이, 둘째 사이, 뒤에 더 놓는 빨간 전구 수이다. 사이에 이미 $1$개씩 있으므로 모두 $0$ 이상이면 된다.","확인":"70","스킬":"P4"},{"제목":"경우를 모두 더하기","힌트":"파란 전구가 $1$개, $2$개, $3$개인 경우의 수를 더하면?","식":["$27+56+70=153$"],"설명":"파란 전구의 개수가 다르면 서로 다른 신호이므로 합의 법칙으로 더한다.","확인":"153","스킬":"P3"}]},"ns-638558ac866f":{"길":"교차점마다 왼쪽·아래에서 오는 방법의 수를 더하고 끊긴 길로는 더하지 않는다","단계":[{"제목":"좌표를 놓고 끊긴 길 찾기","힌트":"$\\mathrm{P}$를 원점으로 $\\mathrm{Q}$의 좌표와, 도로가 이어져 있지 않은 곳은 어디인가?","식":["$\\mathrm{P}(0,0),\\ \\mathrm{Q}(3,5)$","끊긴 길: $(2,1)$-$(2,2)$ 세로, $(2,2)$-$(3,2)$ 가로, $(1,3)$-$(2,3)$ 가로"],"설명":"오른쪽과 위쪽으로만 가는 최단거리이므로 교차점마다 왼쪽 점과 아래쪽 점의 수를 더해 간다. 도로가 없는 변으로 오는 수는 더하지 않는다.","확인":null,"스킬":"P4"},{"제목":"아래 세 줄의 방법의 수 적기","힌트":"$y=0,\\ 1,\\ 2$인 줄에서 $(3,2)$에 오는 방법의 수는 얼마인가?","식":["$y=0$: $1,\\ 1,\\ 1,\\ 1$","$y=1$: $1,\\ 2,\\ 3,\\ 4$","$y=2$: $1,\\ 3,\\ 3,\\ 4$"],"설명":"$y=2$에서 $(2,2)$는 아래의 세로 도로가 끊겨 왼쪽 점의 수 $3$만 받고, $(3,2)$는 왼쪽의 가로 도로가 끊겨 아래 점의 수 $4$만 받는다.","확인":"4","스킬":"P4"},{"제목":"y=3 줄의 방법의 수 적기","힌트":"$(2,3)$은 왼쪽 도로가 끊겨 있다. $(3,3)$에 오는 방법의 수는 얼마인가?","식":["$(1,3)=1+3=4$","$(2,3)=3$ (아래에서만)","$(3,3)=3+4=7$"],"설명":"$(1,3)$과 $(2,3)$ 사이의 가로 도로가 끊겨 $(2,3)$은 아래 점의 수만 받는다. $(3,3)$은 왼쪽 점과 아래 점의 수를 더한다.","확인":"7","스킬":"P4","고비":true},{"제목":"위 두 줄을 채워 Q까지 구하기","힌트":"$y=4$, $y=5$ 줄은 끊긴 길이 없다. $\\mathrm{Q}$에 오는 방법의 수는?","식":["$y=4$: $1,\\ 5,\\ 8,\\ 15$","$y=5$: $1,\\ 6,\\ 14,\\ 29$"],"설명":"왼쪽 점과 아래 점의 수를 더해 간다. $(3,4)=8+7=15$이고 $\\mathrm{Q}(3,5)=14+15=29$이다.","확인":"29","스킬":"P4"}]},"ns-6536cc407213":{"길":"전체 최단 경로에서 P에서 좌회전하거나 우회전하는 경로를 뺀다","단계":[{"제목":"전체 최단 경로 수 구하기","힌트":"$\\mathrm{A}$에서 $\\mathrm{B}$까지 오른쪽 몇 칸, 위쪽 몇 칸을 나열하는가?","식":["오른쪽 $6$칸, 위쪽 $5$칸","$\\frac{11!}{6!\\,5!}=462$"],"설명":"$\\mathrm{A}$를 원점으로 두면 $\\mathrm{B}(6,5)$, $\\mathrm{P}(2,3)$이다. $\\mathrm{P}$에서 꺾지 못하는 경로를 빼기 위해 전체를 먼저 구한다.","확인":"462","스킬":"P2"},{"제목":"P에서 좌회전하는 경로 수 구하기","힌트":"$\\mathrm{P}$에 왼쪽에서 들어와 위쪽으로 나가는 경로는 몇 가지인가?","식":["$\\mathrm{A}\\to(1,3)$: $\\frac{4!}{1!\\,3!}=4$","$(2,4)\\to\\mathrm{B}$: $\\frac{5!}{4!\\,1!}=5$","$4\\times1\\times5=20$"],"설명":"오른쪽으로 달려 $\\mathrm{P}$에 들어와 위쪽으로 꺾는 것이 좌회전이다. $(1,3)$에서 $\\mathrm{P}$를 지나 $(2,4)$로 가는 길은 $1$가지이다.","확인":"20","스킬":"P2","고비":true},{"제목":"P에서 우회전하는 경로 수 구하기","힌트":"$\\mathrm{P}$에 아래쪽에서 들어와 오른쪽으로 나가는 경로는 몇 가지인가?","식":["$\\mathrm{A}\\to(2,2)$: $\\frac{4!}{2!\\,2!}=6$","$(3,3)\\to\\mathrm{B}$: $\\frac{5!}{3!\\,2!}=10$","$6\\times1\\times10=60$"],"설명":"위쪽으로 달려 $\\mathrm{P}$에 들어와 오른쪽으로 꺾는 것이 우회전이다. 최단거리이므로 왼쪽이나 아래쪽으로 꺾는 경우는 없다.","확인":"60","스킬":"P2"},{"제목":"전체에서 빼서 구하기","힌트":"전체 경로에서 좌회전하는 경로와 우회전하는 경로를 빼면?","식":["$462-(20+60)=382$"],"설명":"좌회전 경로와 우회전 경로는 $\\mathrm{P}$에 들어오는 방향이 달라 겹치지 않는다.","확인":"382","스킬":"P2"}]},"ns-662674790c63":{"길":"전체 최단 경로에서 잘려 나간 꼭짓점 P와 단면의 꼭짓점 Q를 지나는 경로를 뺀다","단계":[{"제목":"전체 최단 경로 수 구하기","힌트":"$\\mathrm{A}$에서 $\\mathrm{B}$까지 가로, 안쪽, 위쪽으로 각각 몇 칸씩 가는가?","식":["가로 $2$칸, 안쪽 $2$칸, 위쪽 $3$칸","$\\frac{7!}{2!\\,2!\\,3!}=210$"],"설명":"$\\mathrm{A}$를 원점으로 가로를 $x$, 안쪽을 $y$, 위쪽을 $z$로 두면 $\\mathrm{B}(2,2,3)$이다. 잘려 나가지 않은 직육면체라고 보고 먼저 센다.","확인":"210","스킬":"P3"},{"제목":"잘려 나간 꼭짓점 P를 지나는 경로 수 구하기","힌트":"$\\mathrm{A}$에서 $\\mathrm{P}$까지, $\\mathrm{P}$에서 $\\mathrm{B}$까지 가는 방법의 수를 각각 구해 곱하면?","식":["$\\mathrm{P}(2,0,3)$","$\\mathrm{A}\\to\\mathrm{P}$: $\\frac{5!}{3!\\,2!}=10$, $\\mathrm{P}\\to\\mathrm{B}$: $1$","$10\\times1=10$"],"설명":"$\\mathrm{P}$는 잘려 나간 꼭짓점이므로 $\\mathrm{P}$를 지나는 경로는 갈 수 없다. $\\mathrm{P}$에서 $\\mathrm{B}$까지는 안쪽으로 $2$칸 곧바로 가는 $1$가지뿐이다.","확인":"10","스킬":"P2"},{"제목":"단면의 꼭짓점 Q를 지나는 경로 수 구하기","힌트":"$\\mathrm{Q}$를 지나 $\\mathrm{P}$가 아닌 $\\mathrm{R}$로 가는 경로는 몇 가지인가?","식":["$\\mathrm{Q}(2,0,2),\\ \\mathrm{R}(2,1,2)$","$\\mathrm{A}\\to\\mathrm{Q}$: $\\frac{4!}{2!\\,2!}=6$, $\\mathrm{Q}\\to\\mathrm{R}$: $1$, $\\mathrm{R}\\to\\mathrm{B}$: $2$","$6\\times1\\times2=12$"],"설명":"$\\mathrm{Q}$는 단면의 한 꼭짓점이어서 $\\mathrm{Q}$에서 이어지는 길은 단면의 모서리를 지나는 길로 본다.$\\mathrm{Q}$에서 $\\mathrm{P}$로 가는 경로는 앞 단계에서 이미 센 경로이므로 $\\mathrm{R}$로 가는 경로만 센다. $\\mathrm{R}$에서 $\\mathrm{B}$까지는 안쪽 $1$칸, 위쪽 $1$칸을 나열하는 $2$가지이다.","확인":"12","스킬":"P2","고비":true},{"제목":"전체에서 빼서 구하기","힌트":"전체 경로에서 $\\mathrm{P}$를 지나는 경로와 $\\mathrm{Q}$에서 $\\mathrm{R}$로 가는 경로를 빼면?","식":["$210-(10+12)=188$"],"설명":"$\\mathrm{P}$를 지나는 경로와 $\\mathrm{Q}$에서 $\\mathrm{R}$로 가는 경로는 겹치지 않으므로 그대로 더해 뺀다.","확인":"188","스킬":"P2"}]},"ns-67730529c989":{"길":"조 3개의 크기를 (2,2,2), (2,2,3), (2,3,3)으로 나누고 낱장까지 조합으로 센다","단계":[{"제목":"조의 크기와 낱장 수로 경우 나누기","힌트":"조 $3$개의 카드 수 합이 $8$ 이하일 때 크기의 조합과 낱장 수는 어떻게 되는가?","식":["$(2,2,2)$: 낱장 $2$장","$(2,2,3)$: 낱장 $1$장","$(2,3,3)$: 낱장 $0$장"],"설명":"조 하나는 $2$장 또는 $3$장이고 합이 $8$ 이하이므로 위 세 경우뿐이다. $(3,3,3)$은 $9$장이라 안 된다. 낱장은 조가 아닌 숫자에서 각각 $1$장씩만 뽑는다.","확인":null,"스킬":"C2"},{"제목":"조가 2장씩 세 개인 경우 세기","힌트":"조가 될 숫자와 카드, 낱장이 될 숫자와 카드를 차례로 고르면 각각 몇 가지인가?","식":["조: 숫자 ${}_{6}\\mathrm{C}_{3}=20$, 카드 $({}_{3}\\mathrm{C}_{2})^{3}=27$","낱장: 숫자 ${}_{3}\\mathrm{C}_{2}=3$, 카드 $3\\times3=9$","$20\\times27\\times3\\times9=14580$"],"설명":"$6$개의 숫자 중 $3$개가 조가 되고, 각 조의 카드는 모양 $3$가지 중 $2$장을 뽑는다. 남은 $3$개 숫자 중 $2$개에서 카드를 $1$장씩 뽑는다.","확인":"14580","스킬":"P4"},{"제목":"조가 2장, 2장, 3장인 경우 세기","힌트":"$2$장 조 두 개, $3$장 조 한 개, 낱장 한 장을 차례로 정하면 각각 몇 가지인가?","식":["$2$장 조: 숫자 ${}_{6}\\mathrm{C}_{2}=15$, 카드 $({}_{3}\\mathrm{C}_{2})^{2}=9$","$3$장 조: 숫자 ${}_{4}\\mathrm{C}_{1}=4$, 카드 $1$ / 낱장: 숫자 ${}_{3}\\mathrm{C}_{1}=3$, 카드 $3$","$15\\times9\\times4\\times1\\times3\\times3=4860$"],"설명":"$3$장 조는 같은 숫자의 카드 $3$장을 모두 뽑으므로 카드를 고르는 방법은 $1$가지이다. 남은 숫자 $3$개 중 하나에서 낱장 $1$장을 뽑는다.","확인":"4860","스킬":"P4","고비":true},{"제목":"조가 2장, 3장, 3장인 경우 세기","힌트":"$2$장 조 한 개와 $3$장 조 두 개를 정하는 방법은 각각 몇 가지인가?","식":["$2$장 조: ${}_{6}\\mathrm{C}_{1}\\times{}_{3}\\mathrm{C}_{2}=18$","$3$장 조: ${}_{5}\\mathrm{C}_{2}\\times1=10$","$18\\times10=180$"],"설명":"낱장이 없으므로 조 세 개만 정하면 된다. $2$장 조의 숫자를 먼저 고르고 남은 숫자 $5$개 중 $3$장 조 두 개를 고른다.","확인":"180","스킬":"P4"},{"제목":"경우를 모두 더하기","힌트":"세 경우의 수를 더하면?","식":["$14580+4860+180=19620$"],"설명":"조의 크기 구성이 다르면 서로 겹치지 않으므로 합의 법칙으로 더한다.","확인":"19620","스킬":"C2"}]},"ns-69b6045da8cd":{"길":"합이 19 이상인 상자는 밖 공의 합이 2 이하일 때뿐이므로 전체에서 뺀다","단계":[{"제목":"제한 없이 넣는 경우 구하기","힌트":"공 한 개는 상자 $3$개 중 몇 곳에 들어갈 수 있고, 공은 모두 몇 개인가?","식":["$3^{6}=729$"],"설명":"공마다 상자를 하나 고르는 중복순열이다. 합이 $19$ 이상인 상자가 생기는 경우를 뺄 것이다.","확인":"729","스킬":"P2"},{"제목":"합이 19 이상이 되는 조건 바꾸기","힌트":"공에 적힌 수의 전체 합은 얼마이고, 한 상자의 합이 $19$ 이상이면 그 상자 밖에 있는 공의 합은 얼마 이하인가?","식":["$1+2+3+4+5+6=21$","밖에 있는 공의 합 $\\le21-19=2$"],"설명":"밖에 있는 공의 합이 $2$ 이하가 되는 경우는 밖에 공이 없거나, $1$번 공만 있거나, $2$번 공만 있는 경우뿐이다.","확인":"21","스킬":"P2","고비":true},{"제목":"합이 19 이상인 상자가 생기는 경우 세기","힌트":"특정한 상자가 합 $19$ 이상일 때, 밖에 있는 공을 다른 두 상자에 넣는 방법은 각각 몇 가지인가?","식":["밖에 공 없음 $1$, $1$번만 밖 $2$, $2$번만 밖 $2$","한 상자당 $1+2+2=5$","상자 $3$개: $5\\times3=15$"],"설명":"밖에 있는 공은 나머지 두 상자 중 하나에 들어가므로 $2$가지이다. 두 상자의 합이 모두 $19$ 이상이면 전체 합 $21$을 넘으므로 상자별로 센 경우는 겹치지 않는다.","확인":"15","스킬":"P2"},{"제목":"전체에서 빼서 구하기","힌트":"$729$에서 합이 $19$ 이상인 상자가 생기는 경우를 빼면?","식":["$729-15=714$"],"설명":"어느 상자에도 합이 $19$ 이상이 되지 않는 경우는 전체에서 한 상자라도 $19$ 이상인 경우를 뺀 것이다.","확인":"714","스킬":"P2"}]},"ns-6b446b8eeab3":{"길":"P₁, P₂ 경유를 합집합으로 세고 선분 BE를 두 번 지나는 경로를 뺀다","단계":[{"제목":"B에서 C까지 가는 경로 수 구하기","힌트":"$\\mathrm{B}$에서 $\\mathrm{C}$까지 오른쪽 몇 칸, 아래쪽 몇 칸이며, 그림에 없는 길을 지나는 경우는 몇 가지인가?","식":["$\\mathrm{B}(3,3)\\to\\mathrm{C}(5,0)$: $\\frac{5!}{2!\\,3!}=10$","오른쪽으로 $2$칸을 먼저 가면 $(5,3)$을 지나는데 길이 없다: $1$가지","$10-1=9$"],"설명":"$\\mathrm{A}$를 원점으로 오른쪽을 $x$, 위쪽을 $y$로 두면 $\\mathrm{P}_{1}(1,0)$, $\\mathrm{P}_{2}(2,1)$, $\\mathrm{B}(3,3)$, $\\mathrm{C}(5,0)$이고 $\\mathrm{B}$ 바로 아래 점을 $\\mathrm{E}(3,2)$라 하자. 오른쪽 위 모서리 칸이 비어 있어 $(5,3)$은 길이 아니다. $(5,3)$을 지나는 경로를 전체 $10$가지에서 뺀다.","확인":"9","스킬":"P2"},{"제목":"P₁을 지나는 경로 수 구하기","힌트":"$\\mathrm{A}$에서 $\\mathrm{P}_{1}$, $\\mathrm{P}_{1}$에서 $\\mathrm{B}$, $\\mathrm{B}$에서 $\\mathrm{C}$까지의 경로 수를 곱한 뒤 같은 길을 두 번 지나는 경우를 빼면?","식":["$\\mathrm{A}\\to\\mathrm{P}_{1}$: $1$, $\\mathrm{P}_{1}\\to\\mathrm{B}$: $\\frac{5!}{2!\\,3!}=10$, $\\mathrm{B}\\to\\mathrm{C}$: $9$이므로 $1\\times10\\times9=90$","선분 $\\mathrm{BE}$를 두 번 지남: $1\\times6\\times6=36$","$90-36=54$"],"설명":"한 번 지난 길은 다시 지나지 않는다. $\\mathrm{P}_{1}$에서 $\\mathrm{B}$로 갈 때 $\\mathrm{E}$를 거쳐 올라오고 $\\mathrm{B}$에서 $\\mathrm{C}$로 갈 때 $\\mathrm{E}$로 내려가면 선분 $\\mathrm{BE}$를 두 번 지난다. $\\mathrm{P}_{1}$에서 $\\mathrm{E}$까지 $\\frac{4!}{2!\\,2!}=6$가지, $\\mathrm{E}$에서 $\\mathrm{C}$까지 $6$가지이다.","확인":"54","스킬":"P2","고비":true},{"제목":"P₂를 지나는 경로 수 구하기","힌트":"같은 방법으로 $\\mathrm{P}_{2}$를 지나는 경로 수에서 선분 $\\mathrm{BE}$를 두 번 지나는 경우를 빼면?","식":["$\\mathrm{A}\\to\\mathrm{P}_{2}$: $3$, $\\mathrm{P}_{2}\\to\\mathrm{B}$: $3$, $\\mathrm{B}\\to\\mathrm{C}$: $9$이므로 $3\\times3\\times9=81$","선분 $\\mathrm{BE}$를 두 번 지남: $3\\times2\\times6=36$","$81-36=45$"],"설명":"$\\mathrm{P}_{2}$에서 $\\mathrm{E}$까지는 오른쪽 $1$칸, 위쪽 $1$칸을 나열하는 $2$가지이고 $\\mathrm{E}$에서 $\\mathrm{C}$까지는 $6$가지이다.","확인":"45","스킬":"P2"},{"제목":"P₁, P₂를 모두 지나는 경로 수 구하기","힌트":"$\\mathrm{A}$에서 $\\mathrm{P}_{1}$, $\\mathrm{P}_{2}$, $\\mathrm{B}$, $\\mathrm{C}$ 순서로 지나는 경로 수에서 같은 길을 두 번 지나는 경우를 빼면?","식":["$\\mathrm{A}\\to\\mathrm{P}_{1}$: $1$, $\\mathrm{P}_{1}\\to\\mathrm{P}_{2}$: $2$, $\\mathrm{P}_{2}\\to\\mathrm{B}$: $3$, $\\mathrm{B}\\to\\mathrm{C}$: $9$이므로 $54$","선분 $\\mathrm{BE}$를 두 번 지남: $1\\times2\\times2\\times6=24$","$54-24=30$"],"설명":"두 지점을 모두 지나는 경로는 앞의 두 값에 모두 들어 있으므로 한 번 빼야 한다. 중복해서 지나는 경우를 뺀 뒤의 개수를 쓴다.","확인":"30","스킬":"P2"},{"제목":"합집합 개수 구하기","힌트":"$\\mathrm{P}_{1}$을 지나는 경우와 $\\mathrm{P}_{2}$를 지나는 경우를 더하고 둘 다 지나는 경우를 빼면?","식":["$54+45-30=69$"],"설명":"적어도 하나를 지나는 경로의 수는 합집합의 개수와 같으므로 겹치는 경우를 한 번 뺀다.","확인":"69","스킬":"P2"}]},"ns-6d164b667c83":{"길":"가운데를 고정하고 검은 칸의 위치 유형으로 회전을 정리한 뒤 나머지를 센다","단계":[{"제목":"남은 칸과 검은 칸의 위치 유형 정하기","힌트":"가운데가 검정이면 남은 칸에 칠할 색은? 남은 검은 칸이 놓일 수 있는 위치는 회전하면 몇 가지 유형으로 모이는가?","식":["남은 $8$칸에 검정 $1$, 회색 $3$, 흰색 $4$","검은 칸의 위치: 변의 가운데 $4$곳, 모서리 $4$곳 → 회전하면 유형 $2$가지"],"설명":"검은 칸이 하나뿐이어서 돌려서 겹치는 경우는 검은 칸의 위치로 정해진다. 변의 가운데 네 곳은 회전하면 한 곳으로, 모서리 네 곳도 한 곳으로 모인다. 검은 칸을 한 곳에 고정하면 나머지 모양은 회전으로 겹치지 않는다.","확인":null,"스킬":"P3","고비":true},{"제목":"검은 칸 위치를 고정했을 때 나머지 칸 칠하기","힌트":"검은 칸을 한 곳에 고정하면 남은 $7$칸에 회색 $3$, 흰색 $4$를 칠하는 방법은 몇 가지인가?","식":["$\\frac{7!}{3!\\,4!}=35$"],"설명":"같은 색끼리는 구별하지 않으므로 같은 것이 있는 순열이다. 변의 가운데에 검은 칸을 둘 때와 모서리에 둘 때 모두 같은 값이다.","확인":"35","스킬":"P3"},{"제목":"위치 유형별 경우를 합하기","힌트":"검은 칸이 변의 가운데에 있는 유형과 모서리에 있는 유형을 더하면?","식":["$35+35=70$"],"설명":"두 유형은 회전해도 서로 겹치지 않으므로 합의 법칙으로 더한다.","확인":"70","스킬":"P3"}]},"ns-746ee2ef12fe":{"길":"최단 경로가 지나는 통로를 따라 A에서 P까지, P에서 B까지 나누어 곱한다","단계":[{"제목":"최단 경로가 지나는 통로 파악하기","힌트":"왼쪽 칸에서 오른쪽 아래 칸으로 이어지는 길은 어디뿐인가?","식":["$\\mathrm{A}(0,3),\\ \\mathrm{B}(3,0),\\ \\mathrm{P}(5,4)$","윗줄 $y=6$을 따라 오른쪽으로 간 뒤 $x=5$인 세로길로 내려온다"],"설명":"$\\mathrm{B}$가 있는 아랫줄을 $y=0$, $\\mathrm{A}$가 있는 왼쪽 세로줄을 $x=0$으로 두고 한 칸을 $1$로 센다. 왼쪽 칸과 오른쪽 아래 칸은 윗줄과 오른쪽의 세로길로만 이어지며, $(4,5)$에서는 아래로 내려가는 길이 없다. 위쪽 가운데 칸은 돌아가는 길이라 최단 경로에 쓰이지 않는다. 따라서 최단 경로는 모두 $\\mathrm{P}$를 지난다.","확인":null,"스킬":"P4"},{"제목":"A에서 윗줄까지 가는 경로 수 구하기","힌트":"$\\mathrm{A}$에서 윗줄의 $(2,6)$까지 오른쪽 몇 칸, 위쪽 몇 칸을 나열하는가?","식":["$\\mathrm{A}\\to(2,6)$: $\\frac{5!}{2!\\,3!}=10$","$(2,6)\\to(4,6)$: 윗줄 한 길이므로 $10$"],"설명":"왼쪽 칸에서는 오른쪽, 위쪽으로만 가는 최단 경로이다. 윗줄에서 $x=2$부터 $x=4$까지는 아래로 내려가는 길이 없어 경로 수가 늘지 않는다.","확인":"10","스킬":"P4"},{"제목":"A에서 P까지 가는 경로 수 구하기","힌트":"$(4,6)$에서 $(5,5)$까지 가는 길은 몇 가지이고, $\\mathrm{A}$에서 $\\mathrm{P}$까지 경로 수는?","식":["$(4,6)\\to(5,6)\\to(5,5)$, $(4,6)\\to(4,5)\\to(5,5)$: $2$가지","$\\mathrm{A}\\to\\mathrm{P}$: $10\\times2=20$"],"설명":"$(5,5)$에서 $\\mathrm{P}(5,4)$로 내려오는 길은 하나뿐이다. $(4,6)$에서 $(5,5)$까지는 $(5,6)$을 거치는 길과 $(4,5)$를 거치는 길이 길이가 같아 모두 최단 경로이다.","확인":"20","스킬":"P4","고비":true},{"제목":"P에서 B까지 가는 경로 수 구하기","힌트":"$\\mathrm{P}$에서 아래쪽 $4$칸, 왼쪽 $2$칸을 나열하되 길이 없는 점을 지나는 경우는 몇 가지 빼는가?","식":["$\\frac{6!}{4!\\,2!}=15$","$x=3$에서는 $y\\le2$인 점만 길이 있으므로 $(3,3)$을 지나는 $3$가지를 뺀다","$15-3=12$"],"설명":"$(3,3)$과 $(3,4)$는 길 위의 점이 아니다. $\\mathrm{P}$에서 $(3,3)$까지는 아래 $1$칸, 왼쪽 $2$칸을 나열하는 $3$가지이고 $(3,3)$에서 $\\mathrm{B}$까지는 $1$가지이다.","확인":"12","스킬":"P2"},{"제목":"곱의 법칙으로 합치기","힌트":"$\\mathrm{A}$에서 $\\mathrm{P}$까지와 $\\mathrm{P}$에서 $\\mathrm{B}$까지의 경로 수를 곱하면?","식":["$20\\times12=240$"],"설명":"$\\mathrm{P}$를 지나는 최단 경로는 앞 구간과 뒤 구간을 차례로 정하는 일이므로 곱한다.","확인":"240","스킬":"P3"}]},"ns-751b0df675a6":{"길":"1, 3, 5를 몇 개 쓰는지와 2, 4의 개수 구성으로 나누어 나열 수를 센다","단계":[{"제목":"사용하는 숫자의 경우 나누기","힌트":"$1,\\ 3,\\ 5$는 각각 몇 번까지 쓸 수 있고, 그중 몇 개를 써야 하는가?","식":["$1,\\ 3,\\ 5$는 각각 $1$번 이하, $2$개 또는 $3$개 사용","나머지 자리는 $2,\\ 4$로 채움"],"설명":"$2$, $4$만 중복 사용할 수 있으므로 $1$, $3$, $5$는 한 번씩만 쓸 수 있다. $1,\\ 3,\\ 5$를 $2$개 쓰면 $2,\\ 4$로 $3$자리를, $3$개 쓰면 $2,\\ 4$로 $2$자리를 채운다.","확인":null,"스킬":"P4"},{"제목":"1, 3, 5 중 2개를 쓰는 경우 세기","힌트":"$1,\\ 3,\\ 5$ 중 $2$개를 고르고 $2,\\ 4$ 세 자리의 구성에 따라 다섯 자리를 나열하면 각각 몇 가지인가?","식":["선택 ${}_{3}\\mathrm{C}_{2}=3$","$2,4,4$ 또는 $2,2,4$ 각각: $3\\times\\frac{5!}{2!}=180$","$2,2,2$ 또는 $4,4,4$ 각각: $3\\times\\frac{5!}{3!}=60$"],"설명":"$2$, $4$ 세 자리의 구성은 $2,2,2$, $2,2,4$, $2,4,4$, $4,4,4$의 네 가지이다. $180+180+60+60=480$이다.","확인":"480","스킬":"P3","고비":true},{"제목":"1, 3, 5를 모두 쓰는 경우 세기","힌트":"남은 두 자리를 $2,\\ 4$로 채우는 구성별로 다섯 자리를 나열하면 각각 몇 가지인가?","식":["$2,2$: $\\frac{5!}{2!}=60$, $4,4$: $\\frac{5!}{2!}=60$","$2,4$: $5!=120$","$60+60+120=240$"],"설명":"남은 두 자리의 구성은 $2,2$, $2,4$, $4,4$의 세 가지이다. 같은 숫자가 둘이면 $2!$로 나눈다.","확인":"240","스킬":"P3"},{"제목":"경우를 모두 더하기","힌트":"$1,\\ 3,\\ 5$를 $2$개 쓰는 경우와 $3$개 쓰는 경우를 더하면?","식":["$480+240=720$"],"설명":"사용하는 $1,\\ 3,\\ 5$의 개수가 다르면 서로 다른 수이므로 합의 법칙으로 더한다.","확인":"720","스킬":"P4"}]},"ns-75c8f6c6c909":{"길":"함수 전체에서 함숫값이 빠지는 경우를 포함배제로 뺀다","단계":[{"제목":"함수 전체의 개수 구하기","힌트":"$X$의 원소 하나는 $Y$의 원소 몇 개 중 하나로 대응하고, $X$의 원소는 몇 개인가?","식":["$3^{6}=729$"],"설명":"$X$의 원소마다 $Y$의 원소 $3$개 중 하나를 고르는 중복순열이다. 치역이 공역보다 작은 함수를 빼기 위해 전체를 먼저 구한다.","확인":"729","스킬":"P2"},{"제목":"함숫값이 두 원소로 제한되는 함수 세기","힌트":"$Y$의 두 원소만 쓰는 함수는 쓰는 두 원소를 고르는 방법과 대응하는 방법을 곱하면 몇 개인가?","식":["${}_{3}\\mathrm{C}_{2}\\times2^{6}=3\\times64=192$"],"설명":"치역이 $3$개가 되지 않으려면 $Y$의 어떤 원소가 쓰이지 않는다. 쓰이지 않는 원소를 정하는 $3$가지에 대해 나머지 두 원소로만 대응하는 함수가 $2^{6}$개이다. 한 원소만 쓰는 함수는 두 번씩 들어 있다.","확인":"192","스킬":"P2"},{"제목":"겹침을 보정해 구하기","힌트":"한 원소만 쓰는 함수는 모두 몇 개이며, 앞의 값에서 두 번 센 만큼을 되돌리면?","식":["${}_{3}\\mathrm{C}_{1}\\times1^{6}=3$","$729-192+3=540$"],"설명":"$Y$의 한 원소만 쓰는 함수는 $3$개이다. 앞 단계에서 두 번씩 세어져 두 번 빠졌으므로 한 번 더해 되돌린다.","확인":"540","스킬":"P2","고비":true}]},"ns-7ab8888de0d9":{"길":"가운데 칸은 제자리이므로 바깥 8칸의 배열만 회전 4가지씩 같다고 본다","단계":[{"제목":"가운데 칸과 바깥 칸 나누기","힌트":"$90^{\\circ}$ 회전하면 가운데 칸은 어디로 가는가? 바깥 칸은 몇 칸씩 자리를 바꾸는가?","식":["가운데 칸의 색 $9$가지","바깥 $8$칸은 $8$색을 모두 사용"],"설명":"가운데 칸은 회전해도 제자리이므로 색을 고르는 것으로 정해진다. 바깥 $8$칸은 회전하면 서로 자리를 바꾼다. $9$색이 모두 다르므로 어떤 배열도 $90^{\\circ}$, $180^{\\circ}$, $270^{\\circ}$ 돌리면 다른 배열이 된다.","확인":null,"스킬":"P3"},{"제목":"회전을 같은 것으로 보고 바깥 칸 칠하기","힌트":"바깥 $8$칸을 $8$색으로 칠하는 방법을 구하고 회전으로 겹치는 $4$가지를 하나로 보면?","식":["$8!=40320$","$\\frac{8!}{4}=10080$"],"설명":"회전하여 일치하는 $4$가지가 한 경우이므로 전체를 $4$로 나눈다.","확인":"10080","스킬":"P3","고비":true},{"제목":"가운데 칸을 곱해 정리하기","힌트":"가운데 칸의 색 $9$가지와 곱한 값을 $7!$를 이용한 꼴로 나타내면?","식":["$9\\times\\frac{8!}{4}=90720$","$9\\times\\frac{8\\times7!}{4}=18\\times7!$"],"설명":"가운데 칸을 정하는 일과 바깥 칸을 칠하는 일이 차례로 일어나므로 곱한다. $\\frac{9\\times8}{4}=18$이므로 $18\\times7!$이다.","확인":"90720","스킬":"P3"}]},"ns-7e22ddaf3227":{"길":"정사각형에 쓸 색을 고르고 회전을 정리한 뒤 삼각형을 칠해 13!과 비교한다","단계":[{"제목":"정사각형 6개에 쓸 색 고르기","힌트":"서로 다른 $14$가지 색에서 정사각형 $6$개에 쓸 색 $6$가지를 고르는 방법은 몇 가지인가?","식":["${}_{14}\\mathrm{C}_{6}=3003$"],"설명":"육팔면체의 정사각형 면은 $6$개이고 색은 모두 다르다. 색을 놓는 순서는 아직 따지지 않으므로 조합으로 센다.","확인":"3003","스킬":"P3"},{"제목":"정사각형 6개를 회전 고려해 칠하기","힌트":"고른 색 $6$가지를 정사각형 $6$개에 칠하는 것은 정육면체의 면을 칠하는 것과 같다. 회전하여 일치하는 것을 같게 보면 몇 가지인가?","식":["위쪽 면의 색을 고정하면 아래쪽 면의 색은 $5$가지","옆면 $4$개는 원순열: $(4-1)!=3!$","$5\\times3!=30$"],"설명":"정사각형 $6$개는 정육면체의 면과 같은 배치이므로 회전으로 한 색을 위쪽에 고정할 수 있다. 위쪽 색을 고정하면 아래쪽에 올 색이 $5$가지이고, 옆면 $4$개는 돌려서 겹치는 것을 같게 보는 원순열이다.","확인":"30","스킬":"P3","고비":true},{"제목":"정삼각형 8개 칠하기","힌트":"정사각형 $6$개를 서로 다른 색으로 칠하면 회전으로 겹치지 않는다. 남은 색 $8$가지를 정삼각형 $8$개에 칠하는 방법은?","식":["$8!=40320$"],"설명":"정사각형의 색이 모두 달라 모양이 고정되었으므로 삼각형 $8$개의 자리는 서로 구별된다. 남은 $8$가지 색을 일렬로 나열하는 것과 같다.","확인":"40320","스킬":"P3"},{"제목":"경우의 수를 13!과 비교해 k 구하기","힌트":"세 값을 곱한 경우의 수에서 ${}_{14}\\mathrm{C}_{6}=\\frac{14!}{6!\\,8!}$로 바꾸면 $14!$의 몇 분의 몇이 되는가?","식":["${}_{14}\\mathrm{C}_{6}\\times30\\times8!=\\frac{14!}{6!\\,8!}\\times30\\times8!=\\frac{1}{24}\\times14!$","$\\frac{14\\times13!}{24}=\\frac{7}{12}\\times13!$"],"설명":"$14!$을 $24$로 나눈 값이며, 육팔면체를 돌려 겹치는 경우가 $24$가지인 것과 같다. $14!=14\\times13!$로 바꾸어 $k\\times13!$ 꼴과 비교한다.","확인":"7/12","스킬":"P3"}]},"ns-85e89795d8f3":{"길":"한 꼭짓점 둘레의 수를 고르고 원순열로 센 뒤 꼭짓점 수로 나눈다","단계":[{"제목":"마주 보는 면의 수 쌍에서 하나씩 고르기","힌트":"한 꼭짓점을 둘러싼 $4$개 면에는 서로 마주 보는 면이 없다. 합이 $9$인 수의 쌍에서 각각 하나씩 고르는 방법은 몇 가지인가?","식":["합이 $9$인 쌍: $(1,\\,8),\\,(2,\\,7),\\,(3,\\,6),\\,(4,\\,5)$","$2\\times2\\times2\\times2=16$"],"설명":"정팔면체의 면 $8$개는 마주 보는 $4$쌍이고, 한 꼭짓점 둘레의 $4$개 면은 각 쌍에서 하나씩이다. 위 꼭짓점 둘레에 놓을 수를 네 쌍에서 하나씩 고르면 나머지 네 면의 수는 마주 보는 면에 의해 정해진다.","확인":"16","스킬":"P3"},{"제목":"꼭짓점 둘레의 면에 원순열로 배열하기","힌트":"고른 $4$개의 수를 한 꼭짓점을 둘러싼 $4$개의 면에 놓는 방법은 돌려서 겹치는 것을 같게 보면 몇 가지인가?","식":["$(4-1)!=6$"],"설명":"위 꼭짓점을 고정하면 그 둘레의 면 $4$개는 돌려서 겹치는 것을 같게 보는 원순열이다. 아래 꼭짓점 둘레의 면에는 마주 보는 수가 정해져 있어 더 셀 것이 없다.","확인":"6","스킬":"P3","고비":true},{"제목":"꼭짓점 수로 나누어 경우의 수 구하기","힌트":"위로 놓은 꼭짓점을 고정해 센 경우는 같은 정팔면체를 몇 번씩 센 것인가?","식":["$\\frac{16\\times6}{6}=16$"],"설명":"정팔면체는 돌려서 꼭짓점 $6$개 중 어느 것이든 위로 보낼 수 있다. 위 꼭짓점을 고정해 센 $16\\times6$은 같은 정팔면체를 $6$번씩 센 값이므로 $6$으로 나눈다.","확인":"16","스킬":"P3"}]},"ns-85f3440428d1":{"길":"여학생을 원탁에 먼저 앉히고 사이 남학생 수를 나눈 뒤 남학생을 앉힌다","단계":[{"제목":"여학생 3명을 원탁에 앉히기","힌트":"돌려서 일치하는 것을 같게 볼 때 여학생 $3$명이 원탁에 앉는 방법은 몇 가지인가?","식":["$(3-1)!=2$"],"설명":"원탁에서는 돌려서 겹치는 배열을 같게 보므로 원순열이다. 여학생을 먼저 앉히면 원탁의 기준이 정해져 남은 자리는 서로 구별된다.","확인":"2","스킬":"P3"},{"제목":"여학생 사이에 앉을 남학생 수 나누기","힌트":"여학생 사이 세 곳에 남학생 $6$명을 각각 $1$명 이상 나누어 앉히는 방법은 몇 가지인가? 세 곳은 서로 구별된다.","식":["$(4,\\,1,\\,1)$: $4$명이 앉을 곳을 고르는 $3$가지","$(3,\\,2,\\,1)$: 곳마다 인원을 정하는 $3!=6$가지","$(2,\\,2,\\,2)$: $1$가지","$3+6+1=10$"],"설명":"여학생이 이미 앉아 있어 사이 세 곳이 서로 구별된다. 합이 $6$이고 각각 $1$ 이상인 수의 묶음은 $(4,\\,1,\\,1)$, $(3,\\,2,\\,1)$, $(2,\\,2,\\,2)$뿐이며 묶음마다 세 곳에 배정하는 방법을 센다.","확인":"10","스킬":"C2","고비":true},{"제목":"자리 배치를 곱해 n의 값 구하기","힌트":"여학생이 앉는 방법과 남학생 수를 나누는 방법을 곱한 값에, 남은 $6$자리에 남학생 $6$명이 앉는 $6!$이 곱해지면 $n$은?","식":["$2\\times10=20$","$20\\times6!$이므로 $n=20$"],"설명":"여학생을 앉히면 원탁이 고정되므로 남학생 $6$명은 남은 $6$자리에 일렬로 앉는 것과 같다. 따라서 $6!$이 곱해지고 앞의 곱이 $n$이 된다.","확인":"20","스킬":"P3"}]},"ns-8d5db2c99716":{"길":"♘의 개수로 나누어 ♚를 사이사이에 넣는 중복조합으로 센다","단계":[{"제목":"넣을 수 있는 ♘ 개수의 범위 정하기","힌트":"♘을 연달아 넣지 않으면 $10$칸에 ♘은 최대 몇 개까지 넣을 수 있는가?","식":["♘이 $k$개이면 ♚는 $10-k$개","$k=0,\\,1,\\,\\cdots,\\,5$"],"설명":"♘ 사이에는 ♚가 하나 이상 있어야 하므로 ♘을 $6$개 넣으려면 적어도 $11$칸이 필요하다. 따라서 ♘은 최대 $5$개이다.","확인":"5","스킬":"P3"},{"제목":"♚의 개수를 변수로 두고 식 세우기","힌트":"♘의 앞, 뒤, 사이사이 $k+1$곳에 들어갈 ♚의 개수를 $x_{0},\\,x_{1},\\,\\cdots,\\,x_{k}$라 할 때 합과 조건은?","식":["$x_{0}+x_{1}+\\cdots+x_{k}=10-k$, 단 $x_{1},\\,\\cdots,\\,x_{k-1}\\ge1$","$x_{0}+(x_{1}-1)+\\cdots+(x_{k-1}-1)+x_{k}=11-2k$"],"설명":"사이사이 $k-1$곳은 ♘이 붙지 않도록 ♚가 하나 이상이어야 한다. 이 $k-1$곳에서 하나씩 빼면 모든 변수가 $0$ 이상이 되고 합은 $(10-k)-(k-1)=11-2k$이다.","확인":null,"스킬":"P3","고비":true},{"제목":"♘이 k개일 때의 경우의 수 구하기","힌트":"음이 아닌 정수 $k+1$개의 합이 $11-2k$인 해의 개수는 중복조합으로 어떻게 나타내는가?","식":["${}_{k+1}\\mathrm{H}_{11-2k}={}_{11-k}\\mathrm{C}_{11-2k}={}_{11-k}\\mathrm{C}_{k}$"],"설명":"서로 다른 $k+1$곳에 같은 것 $11-2k$개를 나누어 놓는 중복조합이다. $_{n}\\mathrm{H}_{r}={}_{n+r-1}\\mathrm{C}_{r}$을 쓰고 ${}_{n}\\mathrm{C}_{r}={}_{n}\\mathrm{C}_{n-r}$로 바꾼다.","확인":null,"스킬":"P3"},{"제목":"k=0부터 5까지의 경우의 수 합하기","힌트":"$k=0,\\,1,\\,\\cdots,\\,5$일 때의 ${}_{11-k}\\mathrm{C}_{k}$를 모두 더하면?","식":["${}_{11}\\mathrm{C}_{0}+{}_{10}\\mathrm{C}_{1}+{}_{9}\\mathrm{C}_{2}+{}_{8}\\mathrm{C}_{3}+{}_{7}\\mathrm{C}_{4}+{}_{6}\\mathrm{C}_{5}$","$=1+10+36+56+35+6=144$"],"설명":"♘의 개수가 다르면 서로 다른 경우이므로 합의 법칙으로 더한다.","확인":"144","스킬":"P3"}]},"ns-94ad149de6cf":{"길":"조건 없는 전체에서 P를 지나는 경로를 빼고 P에서 꺾는 경로만 더한다","단계":[{"제목":"조건 없이 A에서 B까지 가는 경로 수 구하기","힌트":"오른쪽으로 $5$칸, 위쪽으로 $4$칸 이동하는 순서를 나열하는 방법은 몇 가지인가?","식":["$\\frac{9!}{5!\\,4!}=126$"],"설명":"최단 거리로 가려면 오른쪽과 위쪽으로만 이동한다. 오른쪽 $5$번과 위쪽 $4$번을 일렬로 나열하는 같은 것이 있는 순열이다.","확인":"126","스킬":"P3"},{"제목":"P를 지나는 경로 수 구하기","힌트":"$\\mathrm{P}$는 $\\mathrm{A}$에서 오른쪽 $3$칸, 위쪽 $2$칸인 지점이다. $\\mathrm{A}$에서 $\\mathrm{P}$까지와 $\\mathrm{P}$에서 $\\mathrm{B}$까지의 경로 수를 곱하면?","식":["$\\mathrm{A}\\to\\mathrm{P}$: $\\frac{5!}{3!\\,2!}=10$","$\\mathrm{P}\\to\\mathrm{B}$: $\\frac{4!}{2!\\,2!}=6$","$10\\times6=60$"],"설명":"직진과 꺾임을 가리지 않고 $\\mathrm{P}$를 지나는 경로를 모두 센 값이다. 이 중 $\\mathrm{P}$에서 직진하는 경로는 허용되지 않는다.","확인":"60","스킬":"P2"},{"제목":"P에서 꺾어 지나는 경로 수 구하기","힌트":"$\\mathrm{P}$의 왼쪽 점을 $\\mathrm{C}$, 위쪽 점을 $\\mathrm{D}$, 아래쪽 점을 $\\mathrm{E}$, 오른쪽 점을 $\\mathrm{F}$라 할 때 허용되는 경로는 몇 가지인가?","식":["$\\mathrm{C}\\to\\mathrm{P}\\to\\mathrm{D}$: $\\frac{4!}{2!\\,2!}\\times\\frac{3!}{2!\\,1!}=6\\times3=18$","$\\mathrm{E}\\to\\mathrm{P}\\to\\mathrm{F}$: $\\frac{4!}{3!\\,1!}\\times\\frac{3!}{1!\\,2!}=4\\times3=12$","$18+12=30$"],"설명":"직진할 수 없으므로 왼쪽에서 들어와 위쪽으로 나가거나 아래쪽에서 들어와 오른쪽으로 나가야 한다. $\\mathrm{A}$에서 $\\mathrm{C}$, $\\mathrm{E}$까지와 $\\mathrm{D}$, $\\mathrm{F}$에서 $\\mathrm{B}$까지는 $\\mathrm{P}$를 지나지 않는다.","확인":"30","스킬":"P2","고비":true},{"제목":"빼고 더해 전체 경로 수 구하기","힌트":"조건 없는 경로 수에서 $\\mathrm{P}$를 지나는 모든 경로를 빼고 꺾어서 지나는 경로를 더하면?","식":["$126-60+30=96$"],"설명":"$\\mathrm{P}$를 지나는 경로 중 허용되는 것은 꺾는 경로뿐이므로 $\\mathrm{P}$를 지나는 전체를 빼고 허용되는 경우만 다시 더한다.","확인":"96","스킬":"P2"}]},"ns-a2b8365002af":{"길":"탁자가 겹치는 회전을 찾아 자리를 구별한 12!을 그 수로 나눈다","단계":[{"제목":"탁자가 겹치는 회전 찾기","힌트":"육각형 탁자를 돌렸을 때 처음과 같은 모양이 되는 회전은 $0^{\\circ}$ 회전을 포함해 몇 가지인가?","식":["$0^{\\circ}$ 회전, $180^{\\circ}$ 회전","$2$가지"],"설명":"길이가 다른 한 쌍의 변이 서로 마주 보고 나머지 네 변은 길이가 같으므로 $180^{\\circ}$ 돌렸을 때만 탁자가 겹친다. 정육각형과 달리 $60^{\\circ}$ 간격으로는 겹치지 않는다.","확인":"2","스킬":"P3","고비":true},{"제목":"자리를 구별해 12명을 앉히는 경우 구하기","힌트":"회전을 생각하지 않고 의자 $12$개를 서로 다른 자리로 보면 $12$명이 앉는 방법은 몇 가지인가?","식":["$12!$"],"설명":"자리를 서로 구별하면 $12$명을 $12$개의 자리에 일렬로 나열하는 순열이다.","확인":null,"스킬":"P3"},{"제목":"회전으로 겹치는 경우를 묶어 구하기","힌트":"$12$명이 모두 다르므로 $180^{\\circ}$ 돌린 배열은 처음 배열과 다른 나열이다. 같은 모양이 몇 번씩 세어졌는가?","식":["$\\frac{12!}{2}=\\frac{12\\times11!}{2}=6\\times11!$"],"설명":"한 배열을 $180^{\\circ}$ 돌린 배열은 같은 모양이므로 $12!$은 같은 경우를 $2$번씩 센 값이다. 그래서 $2$로 나눈다.","확인":null,"스킬":"P3"}]},"ns-a32839e228c8":{"길":"전체 경로에서 P를 왼쪽에서 들어와 위로 나가는 경로를 뺀다","단계":[{"제목":"조건 없이 A에서 B까지 가는 경로 수 구하기","힌트":"오른쪽으로 $6$칸, 위쪽으로 $4$칸 이동하는 순서를 나열하는 방법은 몇 가지인가?","식":["$\\frac{10!}{6!\\,4!}=210$"],"설명":"최단 거리로 가려면 오른쪽과 위쪽으로만 이동한다. 오른쪽 $6$번과 위쪽 $4$번을 일렬로 나열하는 같은 것이 있는 순열이다.","확인":"210","스킬":"P3"},{"제목":"P에서 좌회전하는 경로의 모양 찾기","힌트":"오른쪽과 위쪽으로만 이동할 때 $\\mathrm{P}$에서 좌회전하려면 $\\mathrm{P}$에 어느 방향으로 들어와 어느 방향으로 나가야 하는가?","식":["$\\mathrm{P}$의 왼쪽 점을 $\\mathrm{C}$, 위쪽 점을 $\\mathrm{D}$라 하면","좌회전: $\\mathrm{C}\\to\\mathrm{P}\\to\\mathrm{D}$"],"설명":"오른쪽으로 가다가 위쪽으로 꺾는 것이 좌회전이다. 위쪽으로 가다가 왼쪽으로 꺾는 길은 최단 거리 경로에 없으므로 좌회전하는 경로는 $\\mathrm{C}\\to\\mathrm{P}\\to\\mathrm{D}$를 지나는 경로뿐이다.","확인":null,"스킬":"P2","고비":true},{"제목":"좌회전하는 경로 수 구하기","힌트":"$\\mathrm{P}$는 $\\mathrm{A}$에서 오른쪽 $4$칸, 위쪽 $1$칸인 지점이다. $\\mathrm{A}$에서 $\\mathrm{C}$까지와 $\\mathrm{D}$에서 $\\mathrm{B}$까지의 경로 수를 곱하면?","식":["$\\mathrm{A}\\to\\mathrm{C}$: 오른쪽 $3$칸, 위쪽 $1$칸이므로 $\\frac{4!}{3!\\,1!}=4$","$\\mathrm{D}\\to\\mathrm{B}$: 오른쪽 $2$칸, 위쪽 $2$칸이므로 $\\frac{4!}{2!\\,2!}=6$","$4\\times6=24$"],"설명":"$\\mathrm{C}\\to\\mathrm{P}\\to\\mathrm{D}$ 구간은 정해져 있고 앞뒤 경로는 서로 영향을 주지 않으므로 곱의 법칙으로 센다.","확인":"24","스킬":"P3"},{"제목":"전체에서 빼서 경로 수 구하기","힌트":"조건 없는 경로 수에서 좌회전하는 경로 수를 빼면?","식":["$210-24=186$"],"설명":"좌회전하는 경로는 허용되지 않으므로 전체에서 뺀다. 나머지는 $\\mathrm{P}$를 지나지 않거나 $\\mathrm{P}$에서 좌회전하지 않는 경로이다.","확인":"186","스킬":"P2"}]},"ns-a9a6a165945e":{"길":"원 도로망을 마름모 격자로 바꾸고 가운데 두 지점에서 만나는 경우만 센다","단계":[{"제목":"원 도로망을 격자로 바꾸고 만나는 지점 찾기","힌트":"원을 정사각형(마름모)으로 바꾸어도 경로 수는 같다. 같은 속력으로 최단 거리를 가면 만나는 지점은 $\\mathrm{A}$와 $\\mathrm{B}$에서 길 따라 같은 거리에 있다. 만날 수 있는 지점은 몇 곳인가?","식":["위쪽 줄 가운데 두 원이 맞닿는 점 $\\mathrm{G}$","아래쪽 줄 가운데 두 원이 맞닿는 점 $\\mathrm{H}$","만나는 지점: $\\mathrm{G}$, $\\mathrm{H}$의 $2$곳"],"설명":"원을 정사각형으로 바꾸면 도로망은 마름모 모양 격자이고 $\\mathrm{A}$에서 $\\mathrm{B}$까지 최단 거리는 변 $8$개를 지나는 길이다. 같은 속력이므로 각자 $4$개씩 이동해 만나고, 그 자리에 있는 점은 $\\mathrm{G}$와 $\\mathrm{H}$뿐이다.","확인":"2","스킬":"P3"},{"제목":"갑이 G까지 가는 경우의 수 구하기","힌트":"마름모 격자에서 $\\mathrm{A}$에서 $\\mathrm{G}$까지 오른쪽 위로 몇 칸, 오른쪽 아래로 몇 칸 가야 하는가?","식":["오른쪽 위로 $3$칸, 오른쪽 아래로 $1$칸","$\\frac{4!}{3!\\,1!}=4$"],"설명":"$\\mathrm{A}$에서 $\\mathrm{G}$까지는 $4$칸이며 오른쪽 위 $3$번과 오른쪽 아래 $1$번을 나열한다. 이 길은 모두 도로망 안에 있다.","확인":"4","스킬":"P3"},{"제목":"을이 G까지 가는 경우의 수 구하기","힌트":"$\\mathrm{B}$에서 $\\mathrm{G}$까지 가는 모든 방법에서 도로가 없는 길로 가는 경우를 빼면?","식":["$\\mathrm{B}$에서 $\\mathrm{G}$까지: 왼쪽 위 $2$칸, 왼쪽 아래 $2$칸이므로 $\\frac{4!}{2!\\,2!}=6$","왼쪽 위로 $2$칸을 먼저 가는 경우는 도로망 밖: $1$가지","$6-1=5$"],"설명":"$\\mathrm{B}$에서 왼쪽 위로 연달아 두 칸 가면 도로망에 없는 점에 닿는다. 이 길은 도로가 없으므로 제외한다.","확인":"5","스킬":"P2","고비":true},{"제목":"G, H에서 만나는 경우의 수 합하기","힌트":"$\\mathrm{H}$는 도로망을 $180^{\\circ}$ 돌리면 $\\mathrm{G}$와 겹치는 점이다. 각 지점에서 갑과 을의 경우를 곱하고 두 지점의 경우를 더하면?","식":["$\\mathrm{G}$: $4\\times5=20$","$\\mathrm{H}$: $5\\times4=20$","$20+20=40$"],"설명":"도로망이 점대칭이라 갑이 $\\mathrm{H}$까지 가는 경우는 을이 $\\mathrm{G}$까지 가는 $5$가지와 같고, 을이 $\\mathrm{H}$까지 가는 경우는 갑이 $\\mathrm{G}$까지 가는 $4$가지와 같다. 같은 지점에서 만날 때 갑과 을의 경로는 서로 독립이므로 곱하고, 두 지점의 경우는 더한다.","확인":"40","스킬":"P3"}]},"ns-bb52758d9d95":{"길":"경로를 가장 높이 올라간 줄로 나누어 겹치지 않게 더한다","단계":[{"제목":"경로를 가장 높이 올라간 줄로 나누기","힌트":"집에서 서점까지의 경로는 올라가기만 하다가 내려가기만 한다. 같은 경로를 두 번 세지 않으려면 무엇을 기준으로 나누어야 하는가?","식":["연락받기 전: 오른쪽, 위쪽으로만 이동(도서관 방향)","연락받은 뒤: 오른쪽, 아래쪽으로만 이동(서점 방향)","맨 아래 줄을 $l_{0}$, 가운데 줄을 $l_{1}$, 맨 위 줄을 $l_{2}$라 하고 가장 높이 올라간 줄로 나눈다"],"설명":"연락받은 위치가 달라도 지나온 길이 같으면 같은 경로이므로 연락받은 위치가 아니라 길의 모양으로 센다. 가장 높이 올라간 줄이 다르면 서로 다른 경로이고, 같은 줄이면 위로 가는 이동이 모두 아래로 가는 이동보다 먼저 온다.","확인":null,"스킬":"C2"},{"제목":"가운데 줄까지 올라가는 경로 수 구하기","힌트":"오른쪽 $4$번, 위로 $1$번, 아래로 $1$번 이동하는 경로에서 위로 가는 이동이 아래로 가는 이동보다 먼저 오는 방법은 몇 가지인가?","식":["이동 $6$번 중 위, 아래 이동 $2$번의 자리를 고르면 순서가 정해진다","$\\frac{6!}{4!\\,2!}=15$"],"설명":"위로 가는 이동이 아래로 가는 이동보다 먼저 와야 하므로 두 이동의 자리를 고르면 순서는 하나뿐이다. 나머지 자리는 모두 오른쪽 이동이다.","확인":"15","스킬":"P3","고비":true},{"제목":"맨 위 줄까지 올라가는 경로 수 구하기","힌트":"오른쪽 $4$번, 위로 $2$번, 아래로 $2$번 이동하는 경로에서 위로 가는 이동이 모두 아래로 가는 이동보다 먼저 오는 방법은 몇 가지인가?","식":["이동 $8$번 중 위, 아래 이동 $4$번의 자리를 고르면 위 $2$번, 아래 $2$번의 순서가 정해진다","$\\frac{8!}{4!\\,4!}=70$"],"설명":"도서관에 도착한 뒤 서점으로 가는 경우도 이 줄에 포함된다. 위로 가는 두 이동이 먼저, 아래로 가는 두 이동이 나중이므로 자리만 고르면 된다.","확인":"70","스킬":"P3"},{"제목":"줄별 경로 수 합하기","힌트":"올라가지 않고 오른쪽으로만 가는 경로는 $1$가지이다. 세 경우를 모두 더하면?","식":["$1+15+70=86$"],"설명":"가장 높이 올라간 줄이 다르면 서로 다른 경로이므로 겹치지 않는다. 합의 법칙으로 더한다.","확인":"86","스킬":"C2"}]},"ns-beb4332b9cbf":{"길":"꺾는 횟수마다 이동을 덩어리로 나누고 각 덩어리를 1칸 이상으로 센다","단계":[{"제목":"꺾는 횟수에 따른 이동 모양 정하기","힌트":"오른쪽으로 $4$번, 위쪽으로 $6$번 이동한다. 같은 방향으로 이어서 가는 구간을 한 덩어리로 보면 꺾는 횟수와 덩어리 수는 어떤 관계인가?","식":["꺾는 횟수 $=$ 덩어리 수 $-1$","짝수인 꺾는 횟수: $2,\\,4,\\,6,\\,8$번 (덩어리 $3,\\,5,\\,7,\\,9$개)","덩어리는 (오, 위, 오, $\\cdots$) 또는 (위, 오, 위, $\\cdots$)로 번갈아 나온다"],"설명":"덩어리는 방향이 번갈아 바뀌므로 꺾는 횟수가 짝수이면 덩어리 수는 홀수이다. 꺾는 횟수가 $0$인 경우는 없고, 오른쪽 덩어리는 최대 $4$개, 위쪽 덩어리는 최대 $6$개이므로 꺾는 횟수는 $8$번까지 가능하다.","확인":null,"스킬":"C2"},{"제목":"꺾는 횟수가 2번인 경우 구하기","힌트":"덩어리 $3$개이므로 (오, 위, 오)와 (위, 오, 위)이다. 각 덩어리가 $1$칸 이상이 되도록 나누는 방법은 몇 가지인가?","식":["(오, 위, 오): 오른쪽 $2$덩어리 ${}_{2}\\mathrm{H}_{2}=3$, 위쪽 $1$덩어리 $1$","(위, 오, 위): 위쪽 $2$덩어리 ${}_{2}\\mathrm{H}_{4}=5$, 오른쪽 $1$덩어리 $1$","$3+5=8$"],"설명":"한 방향의 $n$칸을 $a$덩어리로 나누되 각 덩어리가 $1$칸 이상이려면 먼저 $1$칸씩 놓고 남은 $n-a$칸을 $a$덩어리에 나누면 되므로 ${}_{a}\\mathrm{H}_{n-a}$이다.","확인":"8","스킬":"P3"},{"제목":"꺾는 횟수가 4번인 경우 구하기","힌트":"덩어리 $5$개이므로 (오, 위, 오, 위, 오)와 (위, 오, 위, 오, 위)이다. 두 방향의 덩어리 수가 서로 다름에 주의하여 구하면?","식":["(오, 위, 오, 위, 오): 오른쪽 $3$덩어리, 위쪽 $2$덩어리이므로 ${}_{3}\\mathrm{H}_{1}\\times{}_{2}\\mathrm{H}_{4}=3\\times5=15$","(위, 오, 위, 오, 위): 위쪽 $3$덩어리, 오른쪽 $2$덩어리이므로 ${}_{3}\\mathrm{H}_{3}\\times{}_{2}\\mathrm{H}_{2}=10\\times3=30$","$15+30=45$"],"설명":"오른쪽 이동의 나누기와 위쪽 이동의 나누기는 서로 독립이므로 곱하고, 두 모양은 서로 다른 경로이므로 더한다.","확인":"45","스킬":"P3","고비":true},{"제목":"꺾는 횟수가 6번인 경우 구하기","힌트":"덩어리 $7$개이므로 (오, 위, 오, 위, 오, 위, 오)와 (위, 오, 위, 오, 위, 오, 위)이다. 각 방향의 덩어리 수에 맞게 나누면?","식":["(오, 위, 오, 위, 오, 위, 오): 오른쪽 $4$덩어리, 위쪽 $3$덩어리이므로 ${}_{4}\\mathrm{H}_{0}\\times{}_{3}\\mathrm{H}_{3}=1\\times10=10$","(위, 오, 위, 오, 위, 오, 위): 위쪽 $4$덩어리, 오른쪽 $3$덩어리이므로 ${}_{4}\\mathrm{H}_{2}\\times{}_{3}\\mathrm{H}_{1}=10\\times3=30$","$10+30=40$"],"설명":"오른쪽 $4$칸을 $4$덩어리로 나누면 덩어리마다 $1$칸이어서 방법이 $1$가지이다.","확인":"40","스킬":"P3"},{"제목":"꺾는 횟수가 8번인 경우를 구해 모두 합하기","힌트":"덩어리 $9$개일 때 가능한 모양은 무엇인가? 짝수 번 꺾는 경우를 모두 더하면?","식":["(위, 오, 위, 오, 위, 오, 위, 오, 위): 위쪽 $5$덩어리, 오른쪽 $4$덩어리이므로 ${}_{5}\\mathrm{H}_{1}\\times{}_{4}\\mathrm{H}_{0}=5\\times1=5$","$8+45+40+5=98$"],"설명":"오른쪽 덩어리가 $5$개이면 오른쪽 이동이 $4$번뿐이라 불가능하므로 위쪽으로 시작하는 모양만 가능하다. 꺾는 횟수가 다르면 서로 다른 경로이므로 더한다.","확인":"98","스킬":"C2"}]},"ns-bfb9dbd348e6":{"길":"부등호를 등호 꼴로 바꿔 중복조합으로 센 뒤 곱이 음수인 경우를 뺀다","단계":[{"제목":"(1) 부등식을 등호 있는 꼴로 바꾸기","힌트":"$f(b)<f(c)$를 $f(b)\\le f(c)-1$로 바꾸고 $f(c)-1=c'$이라 하면 세 값은 어떤 순서로 놓이며 어느 범위에서 고르는가?","식":["$f(a)\\le f(b)<f(c)\\iff f(a)\\le f(b)\\le f(c)-1$","$f(c)-1=c'$이라 하면 $f(a)\\le f(b)\\le c'$","세 값을 고르는 범위: $-3,\\,-2,\\,\\cdots,\\,2$"],"설명":"정수이므로 $f(b)<f(c)$는 $f(b)\\le f(c)-1$과 같다. $f(c)\\le3$이므로 $c'\\le2$이고 $f(a)\\le f(b)\\le c'$이므로 세 값 모두 $-3$ 이상 $2$ 이하의 정수에서 고른다.","확인":null,"스킬":"P3","고비":true},{"제목":"(1) 함수의 개수 구하기","힌트":"서로 다른 $6$개의 정수에서 중복을 허락해 $3$개를 고르는 방법은 몇 가지인가?","식":["${}_{6}\\mathrm{H}_{3}={}_{8}\\mathrm{C}_{3}=56$"],"설명":"같은 값을 여러 번 골라도 크기순으로 놓으면 $f(a)\\le f(b)\\le c'$ 하나가 정해지므로 중복조합이다.","확인":"56","스킬":"P3"},{"제목":"(2) 곱이 음수인 경우의 조건 정하기","힌트":"$f(a)\\,f(b)\\,f(c)<0$이 되려면 $0$이 없어야 하고 음수가 몇 개여야 하는가?","식":["곱이 음수: $0$이 없고 음수가 홀수 개","음수 $1$개: $f(a)<0<f(b)<f(c)$","음수 $3$개: $f(a)\\le f(b)<f(c)<0$"],"설명":"곱이 $0$ 이상인 경우는 (1)의 개수에서 곱이 음수인 경우를 빼서 구한다. 크기 순서가 정해져 있어 음수는 앞에서부터 놓인다.","확인":null,"스킬":"C2"},{"제목":"(2) 곱이 음수인 함수의 개수 구하기","힌트":"음수가 $1$개인 경우와 $3$개인 경우를 각각 세어 더하면?","식":["음수 $1$개: $f(a)$는 $-3,\\,-2,\\,-1$ 중 하나, $f(b)<f(c)$는 $1,\\,2,\\,3$ 중 서로 다른 둘이므로 $3\\times{}_{3}\\mathrm{C}_{2}=9$","음수 $3$개: $f(c)-1=c'$이라 하면 $f(a)\\le f(b)\\le c'$이고 값은 $-3,\\,-2$ 중에서 고르므로 ${}_{2}\\mathrm{H}_{3}=4$","$9+4=13$"],"설명":"음수 $3$개인 경우 $f(c)\\le-1$이므로 $c'\\le-2$이다. 그래서 세 값은 $-3$과 $-2$ 중에서 중복을 허락해 고른다.","확인":"13","스킬":"P3"},{"제목":"(2) 곱이 0 이상인 함수의 개수 구하기","힌트":"(1)의 개수에서 곱이 음수인 경우를 빼면?","식":["$56-13=43$"],"설명":"곱이 $0$ 이상인 경우는 곱이 음수가 아닌 경우이므로 전체에서 음수인 경우를 뺀 것과 같다.","확인":"43","스킬":"C2"}]},"ns-c2d83fa6d212":{"길":"세 방향 이동을 모두 나열한 뒤 정육면체 한가운데 점을 지나는 경우를 뺀다","단계":[{"제목":"방향별로 가야 하는 칸 수 정하기","힌트":"$\\mathrm{A}$와 $\\mathrm{B}$는 정육면체에서 서로 마주 보는 꼭짓점이다. 모서리와 점선을 따라 최단 거리로 가려면 세 방향으로 각각 몇 칸씩 가야 하며 모두 몇 칸인가?","식":["오른쪽 $2$칸, 뒤쪽 $2$칸, 아래쪽 $2$칸","$2+2+2=6$칸"],"설명":"점선이 각 모서리를 $2$등분하므로 한 방향으로 $2$칸씩 간다. 최단 거리는 되돌아가지 않고 세 방향으로만 이동하는 길이다.","확인":"6","스킬":"P3"},{"제목":"조건 없이 세 방향 이동 나열하기","힌트":"오른쪽 $2$번, 뒤쪽 $2$번, 아래쪽 $2$번을 일렬로 나열하는 방법은 몇 가지인가?","식":["$\\frac{6!}{2!\\,2!\\,2!}=90$"],"설명":"같은 방향의 이동은 서로 구별되지 않으므로 같은 것이 있는 순열이다. 이 중에는 정육면체 안쪽을 지나는 경로가 섞여 있다.","확인":"90","스킬":"P3"},{"제목":"정육면체 한가운데 점을 지나는 경로 수 구하기","힌트":"길은 겉면의 모서리와 점선뿐이다. 정육면체 한가운데 점을 지나는 경로는 $\\mathrm{A}$에서 그 점까지와 그 점에서 $\\mathrm{B}$까지를 곱하면 몇 가지인가?","식":["$\\mathrm{A}\\to$ 한가운데 점: 세 방향으로 $1$칸씩이므로 $3!=6$","한가운데 점 $\\to\\mathrm{B}$: 세 방향으로 $1$칸씩이므로 $3!=6$","$6\\times6=36$"],"설명":"겉면의 점은 모두 길 위에 있지만 정육면체 한가운데 점은 안쪽에 있어 길이 아니다. 그 점을 지나는 경로는 겉면만 따라가는 경로가 아니므로 빼야 한다.","확인":"36","스킬":"P2","고비":true},{"제목":"전체에서 빼서 경로 수 구하기","힌트":"조건 없이 나열한 경우의 수에서 한가운데 점을 지나는 경우의 수를 빼면?","식":["$90-36=54$"],"설명":"한가운데 점을 지나지 않는 경로는 모두 겉면의 모서리와 점선만 따라가는 경로이다.","확인":"54","스킬":"P2"}]},"ns-c56beca191ce":{"길":"출발 방향별로 좌회전하는 줄을 골라 센다","단계":[{"제목":"좌회전의 뜻과 출발 방향별 경우 나누기","힌트":"오른쪽과 위쪽으로만 이동할 때 어느 방향 전환이 좌회전이며, 출발 방향에 따라 어떻게 나누는가?","식":["좌회전: 오른쪽 $\\to$ 위쪽으로 꺾기","우회전: 위쪽 $\\to$ 오른쪽으로 꺾기","(ⅰ) 오른쪽으로 출발하는 경우, (ⅱ) 위쪽으로 출발하는 경우"],"설명":"최단 거리로 가려면 오른쪽과 위쪽으로만 이동한다. 왼쪽부터 세로줄을 $\\mathrm{a},\\,\\mathrm{b},\\,\\cdots,\\,\\mathrm{g}$, 아래부터 가로줄을 첫 번째, 두 번째, $\\cdots$, 여섯 번째 줄이라 하자. 좌회전이 정확히 $2$번이면 출발 방향에 따라 꺾는 순서가 정해진다.","확인":null,"스킬":"C2"},{"제목":"(ⅰ) 오른쪽으로 출발하는 경우 구하기","힌트":"첫 번째 좌회전은 어느 가로줄에서 일어나는가? 두 번째 좌회전이 일어날 수 있는 가로줄과 좌회전할 두 세로줄을 고르면?","식":["첫 번째 좌회전: 맨 아래 가로줄에서","두 번째 좌회전이 일어나는 가로줄: 아래부터 $2,\\,3,\\,4,\\,5$번째 줄의 $4$가지","좌회전하는 세로줄 두 개: $\\mathrm{a}$를 제외한 $6$개 중 $2$개이므로 ${}_{6}\\mathrm{C}_{2}=15$","$4\\times15=60$"],"설명":"오른쪽으로 출발하면 맨 아래 가로줄을 따라가다 위쪽으로 꺾는 것이 첫 번째 좌회전이다. 이후 위쪽으로 가다 우회전하여 오른쪽으로 간 뒤 다시 위쪽으로 꺾는 것이 두 번째 좌회전이며, 맨 위 가로줄에서 우회전하면 좌회전을 더 할 수 없으므로 두 번째부터 다섯 번째 가로줄만 가능하다. 두 세로줄은 왼쪽이 첫 번째이므로 고르기만 하면 순서가 정해지고 $\\mathrm{a}$에서는 처음부터 오른쪽으로 가므로 제외한다.","확인":"60","스킬":"P3"},{"제목":"(ⅱ) 위쪽으로 출발하는 경우 구하기","힌트":"위쪽으로 출발하면 처음에는 어느 세로줄을 따라 가는가? 우회전하는 가로줄 두 개와 좌회전하는 세로줄 두 개를 고르면?","식":["첫 번째 꺾기는 맨 왼쪽 세로줄 $\\mathrm{a}$에서 우회전","우회전하는 가로줄 두 개: 아래부터 $2,\\,3,\\,4,\\,5$번째 줄 중 $2$개이므로 ${}_{4}\\mathrm{C}_{2}=6$","좌회전하는 세로줄 두 개: $\\mathrm{b},\\,\\cdots,\\,\\mathrm{g}$ 중 $2$개이므로 ${}_{6}\\mathrm{C}_{2}=15$","$6\\times15=90$"],"설명":"위쪽으로 출발하면 세로줄 $\\mathrm{a}$를 따라 올라가다 우회전하고, 이후 좌회전이 두 번 일어난다. 맨 위 가로줄에서 우회전하면 좌회전을 두 번 할 수 없으므로 우회전은 두 번째부터 다섯 번째 가로줄에서만 한다. 가로줄 두 개와 세로줄 두 개는 각각 고르기만 하면 꺾는 순서가 정해진다.","확인":"90","스킬":"P3","고비":true},{"제목":"두 경우를 더해 경로 수 구하기","힌트":"오른쪽으로 출발하는 경우와 위쪽으로 출발하는 경우를 더하면?","식":["$60+90=150$"],"설명":"출발 방향이 다르면 서로 다른 경로이므로 합의 법칙으로 더한다.","확인":"150","스킬":"C2"}]},"ns-c98a5ce0cf3f":{"길":"마주 보는 쌍마다 홀짝을 하나씩 두고 센 뒤 회전 수로 나눈다","단계":[{"제목":"마주 보는 부채꼴 쌍의 조건 정하기","힌트":"부채꼴 $8$개에서 중심각이 서로 맞꼭지각인 쌍은 몇 쌍이며, 두 수의 합이 홀수이려면 두 수의 홀짝은 어떠해야 하는가?","식":["마주 보는 쌍: $4$쌍","합이 홀수: 한 수는 홀수, 다른 수는 짝수"],"설명":"맞꼭지각인 부채꼴은 원의 중심을 지나는 선의 양쪽에 놓이므로 $8$개가 $4$쌍으로 묶인다. 홀수와 홀수, 짝수와 짝수의 합은 짝수이므로 합이 홀수이려면 한 쌍에 홀수와 짝수가 하나씩 들어간다.","확인":"4","스킬":"N5"},{"제목":"조각을 차례로 채우는 경우의 수 구하기","힌트":"한 쌍씩 채운다. 한 조각에 수를 쓰고 마주 보는 조각에는 홀짝이 반대인 수를 쓸 때, 쌍마다 남은 수에 따라 경우의 수는 어떻게 달라지는가?","식":["첫째 쌍: 아무 수 $10$가지, 마주 보는 조각은 홀짝이 반대인 $5$가지","남은 수는 홀수 $4$개, 짝수 $4$개: 둘째 쌍 $8\\times4$","남은 수 $6$개(홀수 $3$, 짝수 $3$): 셋째 쌍 $6\\times3$","남은 수 $4$개(홀수 $2$, 짝수 $2$): 넷째 쌍 $4\\times2$","$(10\\times5)\\times(8\\times4)\\times(6\\times3)\\times(4\\times2)=230400$"],"설명":"한 쌍을 채울 때마다 남은 수에서 홀수와 짝수가 하나씩 줄어든다. 조각마다 자리가 정해져 있어 곱의 법칙으로 센다.","확인":"230400","스킬":"P3","고비":true},{"제목":"회전으로 겹치는 경우를 묶어 구하기","힌트":"$8$개의 수가 모두 다르므로 돌려서 겹치는 배열은 몇 가지씩 중복되어 세어졌는가?","식":["$\\frac{230400}{8}=28800$"],"설명":"부채꼴이 $8$개이고 쓰인 수가 모두 달라서 한 배열을 돌린 $8$가지는 모두 다른 배열로 세어졌다. 회전하여 일치하는 것은 같게 보므로 $8$로 나눈다.","확인":"28800","스킬":"P3"},{"제목":"소인수분해해 a+b+c 구하기","힌트":"$28800$을 $2^{a}\\times3^{b}\\times5^{c}$ 꼴로 나타내면 $a$, $b$, $c$는?","식":["$28800=288\\times100=2^{5}\\times3^{2}\\times2^{2}\\times5^{2}=2^{7}\\times3^{2}\\times5^{2}$","$a=7,\\ b=2,\\ c=2$","$a+b+c=11$"],"설명":"$288=2^{5}\\times3^{2}$이고 $100=2^{2}\\times5^{2}$이므로 거듭제곱의 지수를 더해 정리한다.","확인":"11","스킬":"N1"}]},"ns-d37466981301":{"길":"쓰는 색의 수로 나누어 원순열로 센 뒤 모두 더한다","단계":[{"제목":"쓸 수 있는 색의 수 정하기","힌트":"원을 $5$등분하여 이웃한 부분을 서로 다른 색으로 칠할 때 $1$가지나 $2$가지 색만으로 칠할 수 있는가?","식":["$2$가지 색은 번갈아 칠해야 하는데 $5$조각은 홀수이므로 불가능","쓰는 색의 수: $5,\\,4,\\,3$가지"],"설명":"$2$가지 색으로 이웃한 조각을 다르게 칠하면 번갈아 칠해야 하는데 조각이 $5$개로 홀수이므로 처음과 끝 조각이 같은 색이 되어 이웃과 겹친다. 그래서 $3$가지 이상의 색이 필요하다.","확인":null,"스킬":"C2"},{"제목":"5가지 색을 모두 쓰는 경우 구하기","힌트":"서로 다른 $5$가지 색으로 원을 $5$등분한 부분을 칠하는 경우는 원순열이다. 몇 가지인가?","식":["$(5-1)!=24$"],"설명":"색이 모두 다르면 이웃한 부분은 항상 다른 색이다. 돌려서 겹치는 것을 같게 보므로 원순열로 센다.","확인":"24","스킬":"P3"},{"제목":"4가지 색을 쓰는 경우 구하기","힌트":"쓸 $4$가지 색을 고르고, 두 번 쓰이는 색을 정한 뒤 돌려서 같은 것을 하나로 보면 칠하는 방법은 몇 가지인가?","식":["색 $4$가지를 고르는 방법: ${}_{5}\\mathrm{C}_{4}$","두 번 쓰이는 색을 정하는 방법: $4$가지","같은 색의 두 조각은 이웃하지 않으므로 돌려서 위치가 하나로 정해지고, 나머지 세 조각에 남은 세 색을 놓는 방법: $3!$","${}_{5}\\mathrm{C}_{4}\\times4\\times3!=120$"],"설명":"$4$가지 색으로 $5$조각을 칠하면 한 색이 두 번 쓰이고 두 조각은 이웃하지 않아야 한다. 이웃하지 않는 두 조각을 같은 색으로 칠하는 위치는 돌리면 하나로 겹치므로, 나머지 세 조각에 서로 다른 세 색을 놓는 방법만 센다.","확인":"120","스킬":"P3","고비":true},{"제목":"3가지 색을 쓰는 경우 구하기","힌트":"쓸 $3$가지 색을 고르고, 한 번만 쓰이는 색을 정한 뒤 나머지 두 색을 이웃하지 않게 놓는 방법은?","식":["색 $3$가지를 고르는 방법: ${}_{5}\\mathrm{C}_{3}$","한 번만 쓰이는 색을 정하는 방법: $3$가지","나머지 네 조각에 두 색이 번갈아 놓이는 방법: $2$가지","${}_{5}\\mathrm{C}_{3}\\times3\\times2=60$"],"설명":"$3$가지 색으로 $5$조각을 칠하면 색은 $2$번, $2$번, $1$번씩 쓰인다. 한 번만 쓰인 색의 조각을 고정하면 나머지 네 조각은 이웃이 서로 달라야 하므로 두 색이 번갈아 놓이는 $2$가지이다.","확인":"60","스킬":"P3"},{"제목":"경우의 수 합하기","힌트":"쓰는 색의 수가 $5$가지, $4$가지, $3$가지인 경우를 모두 더하면?","식":["$24+120+60=204$"],"설명":"쓰는 색의 수가 다르면 서로 다른 경우이므로 합의 법칙으로 더한다.","확인":"204","스킬":"C2"}]},"ns-d4d13593f733":{"길":"수의 개수를 미지수로 두고 정수해를 구한 뒤 순열로 센다","단계":[{"제목":"수의 개수를 미지수로 두고 식 세우기","힌트":"$-1,\\,1,\\,2,\\,4$가 여섯 수에 각각 몇 번 쓰였는지를 $a,\\,b,\\,c,\\,d$라 하면 개수의 합과 수의 합은 어떤 식인가?","식":["$a+b+c+d=6$","$-a+b+2c+4d=8$"],"설명":"순서쌍은 여섯 수의 나열이므로 어떤 수가 몇 번 쓰였는지가 정해지면 같은 것이 있는 순열로 센다. 개수의 합은 $6$이고 수를 모두 더하면 $8$이다.","확인":null,"스킬":"A10","고비":true},{"제목":"조건에 맞는 개수의 해 찾기","힌트":"두 식을 변변 빼서 $c$와 $b$를 $a$, $d$로 나타낸 뒤 $a,\\,b,\\,c,\\,d$가 모두 $0$ 이상의 정수가 되는 경우는 모두 몇 가지인가?","식":["두 식을 변변 빼면 $-2a+c+3d=2$, 즉 $c=2+2a-3d$","$b=4-3a+2d$","$(a,\\,b,\\,c,\\,d)=(0,\\,4,\\,2,\\,0),\\,(1,\\,1,\\,4,\\,0),\\,(1,\\,3,\\,1,\\,1),\\,(2,\\,0,\\,3,\\,1),\\,(2,\\,2,\\,0,\\,2)$"],"설명":"$d$를 $0,\\,1,\\,2,\\,3$으로 두고 $a$에 수를 넣어 $b,\\,c$가 음수가 되지 않는 경우만 남긴다. $d=3$이면 $b$와 $c$가 모두 $0$ 이상이 되는 $a$가 없다.","확인":"5","스킬":"A10"},{"제목":"해마다 순서쌍의 개수 구하기","힌트":"각 해에서 $-1,\\,1,\\,2,\\,4$를 $a,\\,b,\\,c,\\,d$번씩 쓴 여섯 수를 나열하는 방법은 몇 가지인가?","식":["$(0,\\,4,\\,2,\\,0)$: $\\frac{6!}{4!\\,2!}=15$","$(1,\\,1,\\,4,\\,0)$: $\\frac{6!}{1!\\,1!\\,4!}=30$","$(1,\\,3,\\,1,\\,1)$: $\\frac{6!}{3!}=120$","$(2,\\,0,\\,3,\\,1)$: $\\frac{6!}{2!\\,3!}=60$","$(2,\\,2,\\,0,\\,2)$: $\\frac{6!}{2!\\,2!\\,2!}=90$"],"설명":"같은 수끼리는 구별하지 않으므로 같은 것이 있는 순열이다. $0$번 쓰인 수는 나열에서 빠진다.","확인":null,"스킬":"P3"},{"제목":"경우의 수 합하기","힌트":"다섯 가지 해에서 구한 순서쌍의 개수를 모두 더하면?","식":["$15+30+120+60+90=315$"],"설명":"해가 다르면 쓰인 수의 개수가 다르므로 서로 다른 순서쌍이다. 합의 법칙으로 더한다.","확인":"315","스킬":"P3"}]},"ns-d7695c5043f1":{"길":"직사각형으로 보고 센 뒤 도로 없는 모서리와 P를 지나는 경로를 뺀다","단계":[{"제목":"직사각형으로 보고 경로 수 구하기","힌트":"도로망은 오른쪽으로 $5$칸, 위쪽으로 $4$칸인 직사각형에서 오른쪽 아래와 왼쪽 위의 모서리 한 칸씩이 빠진 모양이다. 빠진 곳을 무시하고 직사각형으로 보면 $\\mathrm{A}$에서 $\\mathrm{B}$까지 최단 경로는 몇 가지인가?","식":["$\\frac{9!}{5!\\,4!}=126$"],"설명":"오른쪽 $5$번과 위쪽 $4$번을 일렬로 나열하는 같은 것이 있는 순열이다. 빠진 모서리 때문에 이 중 일부는 길이 없어 지나지 못한다.","확인":"126","스킬":"P3"},{"제목":"도로가 없는 꼭짓점을 지나는 경로 빼기","힌트":"직사각형의 오른쪽 아래 꼭짓점 $\\mathrm{C}$와 왼쪽 위 꼭짓점 $\\mathrm{D}$는 도로망에 없다. 직사각형의 경로 중 $\\mathrm{C}$를 지나는 경로와 $\\mathrm{D}$를 지나는 경로를 빼면?","식":["$\\mathrm{C}$를 지나는 경로: 맨 아래 줄을 끝까지 간 뒤 오른쪽 변을 올라가는 $1$가지","$\\mathrm{D}$를 지나는 경로: 왼쪽 변을 끝까지 올라간 뒤 맨 위 줄을 가는 $1$가지","$126-1-1=124$"],"설명":"$\\mathrm{C}$를 지나려면 $\\mathrm{A}$에서 오른쪽으로만 가다가 올라가야 하고, $\\mathrm{D}$를 지나려면 위쪽으로만 가다가 오른쪽으로 가야 하므로 경로가 각각 하나뿐이다. 두 경로는 서로 다르다.","확인":"124","스킬":"P2","고비":true},{"제목":"P를 지나는 경로 수 구하기","힌트":"$\\mathrm{P}$는 $\\mathrm{A}$에서 오른쪽 $2$칸, 위쪽 $2$칸인 지점이다. $\\mathrm{A}$에서 $\\mathrm{P}$까지와 $\\mathrm{P}$에서 $\\mathrm{B}$까지의 경로 수를 곱하면?","식":["$\\mathrm{A}\\to\\mathrm{P}$: $\\frac{4!}{2!\\,2!}=6$","$\\mathrm{P}\\to\\mathrm{B}$: 오른쪽 $3$칸, 위쪽 $2$칸이므로 $\\frac{5!}{3!\\,2!}=10$","$6\\times10=60$"],"설명":"두 구간의 경로는 모두 도로가 있는 구간 안에 있으므로 곱의 법칙으로 센다.","확인":"60","스킬":"P3"},{"제목":"전체에서 빼서 경로 수 구하기","힌트":"도로망 전체의 경로 수에서 $\\mathrm{P}$를 지나는 경로 수를 빼면?","식":["$124-60=64$"],"설명":"$\\mathrm{P}$를 지나지 않는 경로는 전체 경로에서 $\\mathrm{P}$를 지나는 경로를 뺀 것이다.","확인":"64","스킬":"P2"}]},"ns-dc655802b626":{"길":"대각선 이동은 칸의 색이 변하지 않음을 이용해 두 이동을 나열한다","단계":[{"제목":"대각선 이동에서 칸의 색 확인하기","힌트":"대각선 방향으로 한 칸 위로 이동하면 칸의 색은 어떻게 되는가? 출발 칸 $\\mathrm{A}$와 도착 칸 $\\mathrm{B}$의 색은 무엇인가?","식":["대각선으로 한 칸 이동하면 같은 색의 칸","$\\mathrm{A}$, $\\mathrm{B}$ 모두 흰 칸"],"설명":"바둑판 무늬에서 대각선으로 이웃한 칸은 색이 같다. $\\mathrm{A}$와 $\\mathrm{B}$가 모두 흰 칸이므로 대각선으로만 위로 가면 흰 칸만 지나고 검은 칸은 저절로 피해진다.","확인":null,"스킬":"P3"},{"제목":"왼쪽 위·오른쪽 위 이동 횟수 정하기","힌트":"$\\mathrm{A}$는 맨 아래 줄, $\\mathrm{B}$는 맨 위 줄에 있다. 위로 몇 번 이동해야 하며, 가로로는 어느 쪽으로 몇 칸 차이 나는가?","식":["위로 $7$번 이동 ($8$줄)","$\\mathrm{B}$는 $\\mathrm{A}$보다 한 칸 왼쪽: 왼쪽 위 $4$번, 오른쪽 위 $3$번"],"설명":"한 번 이동할 때마다 한 줄 위로 가고 가로로 한 칸 움직인다. 왼쪽 위로 $a$번, 오른쪽 위로 $b$번 가면 $a+b=7$, $a-b=1$이다.","확인":"4","스킬":"P3"},{"제목":"이동을 나열해 방법의 수 구하기","힌트":"왼쪽 위 $4$번, 오른쪽 위 $3$번을 일렬로 나열하는 방법은 몇 가지인가?","식":["$\\frac{7!}{4!\\,3!}=35$"],"설명":"같은 방향의 이동은 구별하지 않으므로 같은 것이 있는 순열이다. 어떤 순서로 가도 바둑판 밖으로 나가지 않는다. $\\mathrm{A}$의 왼쪽에 $4$칸, 오른쪽에 $3$칸이 있어 왼쪽 위로만 먼저 $4$번 가도, 오른쪽 위로만 먼저 $3$번 가도 판 안에 있기 때문이다.","확인":"35","스킬":"P3","고비":true}]},"ns-dee83e8a51bc":{"길":"쌓는 순서는 크기로 정해지므로 고르는 원판의 종류만 센다","단계":[{"제목":"쌓는 순서가 정해짐을 확인하기","힌트":"작은 원판은 큰 원판 위에 쌓는다는 규칙에서 원판 $3$개를 고르면 쌓는 방법은 몇 가지로 정해지는가?","식":["원판 $3$개를 고르면 쌓는 방법은 $1$가지"],"설명":"반지름이 작은 것이 위로 가므로 순서가 크기로 정해진다. 같은 반지름의 원판은 구별하지 않으므로 서로 자리를 바꾸어도 따로 세지 않는다. 그래서 어떤 원판을 고르는지만 세고, 같은 크기는 $2$개씩뿐이므로 $3$개를 모두 같은 크기로 고를 수는 없다.","확인":null,"스킬":"P3"},{"제목":"크기가 모두 다른 원판 3개 고르기","힌트":"여섯 종류의 원판에서 서로 다른 세 종류를 고르는 방법은 몇 가지인가?","식":["${}_{6}\\mathrm{C}_{3}=20$"],"설명":"서로 다른 크기를 하나씩 고르면 쌓는 순서가 하나로 정해지므로 조합으로 센다.","확인":"20","스킬":"P3"},{"제목":"같은 크기 2개와 다른 크기 1개 고르기","힌트":"원판을 $2$개 쓸 종류와 $1$개 쓸 다른 종류를 차례로 정하면 몇 가지인가?","식":["$2$개를 쓸 종류: $6$가지","$1$개를 쓸 다른 종류: $5$가지","$6\\times5=30$"],"설명":"크기가 같은 두 원판을 모두 쓰는 종류를 정하고 나머지 한 원판은 다른 다섯 종류 중에서 고른다. 같은 종류의 원판은 구별하지 않으므로 종류만 정하면 된다.","확인":"30","스킬":"P3","고비":true},{"제목":"경우의 수 합하기","힌트":"크기가 모두 다른 경우와 같은 크기 두 개가 포함되는 경우를 더하면?","식":["$20+30=50$"],"설명":"두 경우는 겹치지 않으므로 합의 법칙으로 더한다.","확인":"50","스킬":"C2"}]},"ns-e27a846f0d06":{"길":"의자에 번호를 붙여 센 뒤 탁자를 돌려 겹치는 수로 나눈다","단계":[{"제목":"남녀가 번갈아 앉는 자리 정하기","힌트":"의자 $8$개에 둘레를 따라 번호를 붙이면 남학생이 앉을 수 있는 의자는 어떻게 정해지는가?","식":["의자를 둘레를 따라 $1,\\,2,\\,\\cdots,\\,8$번이라 하면","남학생은 홀수 번 또는 짝수 번 의자: $2$가지"],"설명":"남녀가 번갈아 앉으면 이웃한 의자의 성별이 서로 다르다. 한 의자의 성별이 정해지면 나머지 의자의 성별이 모두 정해지므로 두 가지뿐이다.","확인":"2","스킬":"P3"},{"제목":"학생을 자리에 앉히는 경우의 수 구하기","힌트":"남학생 자리 $4$곳에 남학생 $4$명, 여학생 자리 $4$곳에 여학생 $4$명을 앉히는 방법과 자리 배정을 곱하면?","식":["$2\\times4!\\times4!=1152$"],"설명":"남학생 $4$명이 $4$개의 자리에 앉는 방법은 $4!$, 여학생도 $4!$이다. 자리 배정 $2$가지를 곱하면 의자에 번호를 붙여 구별해 센 경우의 수이다.","확인":"1152","스킬":"P3"},{"제목":"탁자를 돌려 겹치는 경우 묶기","힌트":"정사각형 탁자를 돌렸을 때 처음과 같아지는 회전은 몇 가지인가? 번호를 붙여 센 경우는 같은 배열을 몇 번씩 센 것인가?","식":["정사각형 탁자는 $90^{\\circ}$씩 돌려 $4$가지가 겹친다","$\\frac{1152}{4}=288$"],"설명":"$8$명이 모두 다르므로 탁자를 돌린 배열은 번호를 붙인 의자에서 서로 다른 배열로 세어졌다. 돌려서 겹치는 $4$가지를 같은 방법으로 보므로 $4$로 나눈다.","확인":"288","스킬":"P3","고비":true}]},"ns-ee1d90b84555":{"길":"6번 만에 돌아오는 전체에서 2번째, 4번째에 먼저 돌아온 경우를 뺀다","단계":[{"제목":"6번 만에 돌아오는 모든 경우 구하기","힌트":"$6$번 움직여 $\\mathrm{O}$로 돌아오려면 동과 서의 이동 횟수가 같고 남과 북의 이동 횟수도 같아야 한다. 한 축으로만 움직이는 경우와 두 축 모두 움직이는 경우로 나누어 구하면?","식":["한 축만: (동 $3$, 서 $3$) 또는 (북 $3$, 남 $3$)이므로 $2\\times\\frac{6!}{3!\\,3!}=40$","두 축 모두: (북 $2$, 남 $2$, 서 $1$, 동 $1$) 또는 (북 $1$, 남 $1$, 서 $2$, 동 $2$)이므로 $2\\times\\frac{6!}{2!\\,2!\\,1!\\,1!}=360$","$40+360=400$"],"설명":"같은 방향의 이동은 구별하지 않으므로 같은 것이 있는 순열로 센다. 이 $400$가지에는 중간에 $\\mathrm{O}$를 지나는 경우가 섞여 있어 처음으로 돌아오는 경우만 남기려면 빼야 한다.","확인":"400","스킬":"P3"},{"제목":"2번째에 먼저 돌아온 경우 구하기","힌트":"$2$번 움직여 처음으로 $\\mathrm{O}$로 돌아오는 방법과, 그 뒤 남은 $4$번으로 $\\mathrm{O}$로 돌아오는 방법을 곱하면?","식":["$2$번 만에 처음 돌아오는 경우: 동서, 서동, 북남, 남북의 $4$가지","남은 $4$번으로 돌아오는 경우: $2\\times\\frac{4!}{2!\\,2!}+4!=36$","$4\\times36=144$"],"설명":"$2$번째에 처음 돌아온 뒤 $4$번을 더 움직여 다시 돌아오는 경우가 $400$가지 안에 들어 있다. 남은 $4$번은 (북, 북, 남, 남) 또는 (동, 동, 서, 서)를 나열하거나 동서남북을 한 번씩 나열한다.","확인":"144","스킬":"P2","고비":true},{"제목":"4번째에 먼저 돌아온 경우 구하기","힌트":"$4$번 움직여 처음으로 $\\mathrm{O}$로 돌아오는 방법과, 그 뒤 남은 $2$번으로 $\\mathrm{O}$로 돌아오는 방법을 곱하면?","식":["(북, 북, 남, 남) 중 $2$번째에 돌아오지 않는 경우는 $2$가지, (동, 동, 서, 서)도 $2$가지","동서남북을 한 번씩 나열하되 앞의 두 번에 돌아오지 않는 경우: $4\\times2\\times2\\times1=16$","$4$번 만에 처음 돌아오는 경우: $2+2+16=20$","남은 $2$번으로 돌아오는 경우: $4$가지","$20\\times4=80$"],"설명":"처음 두 번 움직여 돌아오면 $2$번째에 먼저 돌아온 경우와 겹치므로 앞의 두 이동이 서로 반대 방향이 아닌 나열만 센다. 이미 센 $2$번째 경우와 겹치지 않는다.","확인":"80","스킬":"P2"},{"제목":"처음으로 돌아오는 경우의 수 구하기","힌트":"$6$번 만에 돌아오는 모든 경우에서 $2$번째와 $4$번째에 먼저 돌아온 경우를 빼면?","식":["$400-144-80=176$"],"설명":"먼저 돌아온 시점이 다르면 서로 겹치지 않는 경우이므로 한꺼번에 뺄 수 있다. 남은 것이 $6$번째에 처음 돌아오는 경우이다.","확인":"176","스킬":"P2"}]},"ns-efd4269e3ee4":{"길":"같은 종류의 순서를 고정하고 종류만 나열한 뒤 대칭으로 절반을 취한다","단계":[{"제목":"종류만 보고 배열하는 경우의 수 구하기","힌트":"같은 종류는 크기가 작은 것부터 왼쪽에 놓으므로 종류만 정하면 배열이 하나로 정해진다. 사파이어 $3$개, 루비 $3$개, 다이아몬드 $2$개를 종류만 구별해 나열하면 몇 가지인가?","식":["$\\frac{8!}{3!\\,3!\\,2!}=560$"],"설명":"조건 ㄱ 때문에 같은 종류의 보석은 놓는 순서가 정해져 있다. 따라서 어느 자리에 어느 종류가 오는지만 세면 되고 같은 것이 있는 순열이다.","확인":"560","스킬":"P3"},{"제목":"조건 ㄴ을 배열의 위치로 바꾸기","힌트":"같은 종류는 작은 것부터 왼쪽이므로 두 번째로 큰 사파이어는 사파이어 중 왼쪽에서 몇 번째에 놓이는가?","식":["두 번째로 큰 사파이어 $=$ 사파이어 중 왼쪽에서 $2$번째","두 번째로 큰 루비 $=$ 루비 중 왼쪽에서 $2$번째","조건 ㄴ: 사파이어의 $2$번째가 루비의 $2$번째보다 왼쪽"],"설명":"같은 종류가 $3$개씩이고 작은 것부터 왼쪽에 놓이므로 두 번째로 큰 보석은 가운데 보석이다. 조건 ㄴ은 두 종류의 가운데 보석의 좌우 관계를 정한다.","확인":null,"스킬":"C7"},{"제목":"사파이어와 루비를 바꿔 절반으로 나누기","힌트":"사파이어와 루비의 종류를 서로 바꾸면 조건 ㄴ의 좌우는 어떻게 되는가? 두 경우는 각각 몇 가지씩인가?","식":["사파이어와 루비를 서로 바꾸면 ‘사파이어의 $2$번째가 루비의 $2$번째보다 왼쪽’인 배열과 ‘오른쪽’인 배열이 일대일로 대응","$\\frac{560}{2}=280$"],"설명":"두 가운데 보석은 서로 다른 자리에 있으므로 어느 한쪽이 반드시 더 왼쪽이다. 사파이어와 루비의 개수가 같아 종류를 바꾸어도 배열이 그대로 유지되므로 두 경우의 수가 같다.","확인":"280","스킬":"P3","고비":true}]},"ns-f1dd1d85db84":{"길":"조의 크기가 2장인 경우와 3장인 경우로 나누고 나머지는 서로 다른 숫자로 고른다","단계":[{"제목":"조의 크기로 경우 나누기","힌트":"조의 개수가 $1$이면 같은 숫자가 $2$장 또는 $3$장인 숫자가 정확히 하나이다. 이때 나머지 카드는 어떻게 뽑혀야 하는가?","식":["(ⅰ) 조가 $2$장: 같은 숫자 $2$장과 나머지 서로 다른 숫자 $3$장","(ⅱ) 조가 $3$장: 같은 숫자 $3$장과 나머지 서로 다른 숫자 $2$장"],"설명":"조가 하나뿐이므로 나머지 카드의 숫자는 모두 달라야 한다. 같은 숫자의 카드는 $3$종류뿐이므로 한 숫자에서 뽑을 수 있는 카드는 최대 $3$장이다.","확인":null,"스킬":"C2"},{"제목":"조가 2장인 경우 구하기","힌트":"조를 이루는 숫자와 그 숫자의 카드 $2$장을 고르고, 나머지 $3$장은 남은 숫자 $4$개 중 서로 다른 $3$개를 골라 숫자마다 종류를 정하면 몇 가지인가?","식":["조: 숫자 $5$가지, 카드 $2$장은 $3$종류 중 $2$개이므로 $5\\times{}_{3}\\mathrm{C}_{2}=15$","나머지 $3$장: 남은 숫자 $4$개 중 $3$개를 고르고 숫자마다 종류 $3$가지이므로 ${}_{4}\\mathrm{C}_{3}\\times3^{3}=108$","$15\\times108=1620$"],"설명":"카드는 숫자와 종류로 정해진다. 나머지 $3$장은 숫자가 서로 다르므로 숫자를 먼저 고르고, 각 숫자에서 한 장을 뽑을 때의 종류 $3$가지를 곱한다.","확인":"1620","스킬":"P3","고비":true},{"제목":"조가 3장인 경우 구하기","힌트":"조를 이루는 숫자를 고르고 그 숫자의 카드 $3$장을 모두 뽑는다. 나머지 $2$장은 몇 가지로 뽑는가?","식":["조: 숫자 $5$가지, 카드 $3$장은 $1$가지이므로 $5\\times1=5$","나머지 $2$장: ${}_{4}\\mathrm{C}_{2}\\times3^{2}=54$","$5\\times54=270$"],"설명":"조가 $3$장이면 그 숫자의 카드를 모두 뽑으므로 종류를 고를 필요가 없다. 나머지 $2$장은 남은 숫자 $4$개 중 $2$개를 고르고 숫자마다 종류를 정한다.","확인":"270","스킬":"P3"},{"제목":"경우의 수 합하기","힌트":"조가 $2$장인 경우와 $3$장인 경우를 더하면?","식":["$1620+270=1890$"],"설명":"두 경우는 겹치지 않으므로 합의 법칙으로 더한다.","확인":"1890","스킬":"C2"}]},"ns-f293b32e1308":{"길":"B 직전은 N뿐이므로 큰 원의 왼쪽 길과 아래쪽 길로 나누어 센다","단계":[{"제목":"막힌 곳을 피하는 길의 모양 정하기","힌트":"$\\mathrm{B}$의 바로 아래 점을 $\\mathrm{N}$이라 하자. $\\mathrm{B}$에는 어느 점에서 도착할 수 있으며, 큰 원이 가운데를 막고 있을 때 $\\mathrm{A}$에서 $\\mathrm{N}$까지 가는 길은 어떤 두 갈래인가?","식":["$\\mathrm{B}$의 왼쪽 점은 공사 구간이므로 $\\mathrm{N}\\to\\mathrm{B}$로만 도착","$\\mathrm{A}$에서 오른쪽 $1$칸, 위쪽 $3$칸인 점을 $\\mathrm{P}$, 맨 아래 가로줄에서 오른쪽 $4$칸인 점을 $\\mathrm{Q}$라 하면","왼쪽 길: $\\mathrm{A}\\to\\mathrm{P}\\to\\mathrm{N}\\to\\mathrm{B}$","아래쪽 길: $\\mathrm{A}\\to\\mathrm{Q}\\to\\mathrm{N}\\to\\mathrm{B}$"],"설명":"최단 경로는 오른쪽과 위쪽으로만 가므로 $\\mathrm{B}$에는 왼쪽 또는 아래쪽에서 도착하는데 왼쪽 점이 막혀 있다. 큰 원은 가운데의 길을 막으므로 왼쪽 가장자리의 세로줄을 따라 올라가 위쪽 가로줄로 가거나, 맨 아래 가로줄을 따라 오른쪽으로 간 뒤 올라가야 한다.","확인":null,"스킬":"P4","고비":true},{"제목":"P를 지나는 경로 수 구하기","힌트":"$\\mathrm{A}$에서 $\\mathrm{P}$까지의 방법과 $\\mathrm{P}$에서 $\\mathrm{B}$까지의 방법을 곱하면? $\\mathrm{P}$에서는 공사 구간 때문에 한 줄로만 갈 수 있다.","식":["$\\mathrm{A}\\to\\mathrm{P}$: 오른쪽 $1$칸, 위쪽 $3$칸이므로 $\\frac{4!}{3!\\,1!}=4$","$\\mathrm{P}\\to\\mathrm{N}\\to\\mathrm{B}$: $1$가지","$4\\times1=4$"],"설명":"$\\mathrm{P}$에서 위쪽 가로줄로 올라가면 $\\mathrm{B}$에 이르기 전에 공사 구간에 막히므로 $\\mathrm{P}$에서는 오른쪽으로 끝까지 가서 $\\mathrm{N}$을 지나 올라가야 한다.","확인":"4","스킬":"P3"},{"제목":"Q를 지나는 경로 수 구하기","힌트":"$\\mathrm{A}$에서 $\\mathrm{Q}$까지, $\\mathrm{Q}$에서 $\\mathrm{N}$까지, $\\mathrm{N}$에서 $\\mathrm{B}$까지의 방법을 곱하면?","식":["$\\mathrm{A}\\to\\mathrm{Q}$: 맨 아래 가로줄을 따라 $1$가지","$\\mathrm{Q}\\to\\mathrm{N}$: 오른쪽 $2$칸, 위쪽 $3$칸이므로 $\\frac{5!}{2!\\,3!}=10$","$\\mathrm{N}\\to\\mathrm{B}$: $1$가지","$1\\times10\\times1=10$"],"설명":"$\\mathrm{Q}$ 오른쪽에는 큰 원이 걸치지 않아 모든 길이 열려 있다. $\\mathrm{Q}$에서 $\\mathrm{N}$까지는 오른쪽 $2$번과 위쪽 $3$번을 나열하는 방법이다.","확인":"10","스킬":"P3"},{"제목":"두 길의 경로 수 합하기","힌트":"$\\mathrm{P}$를 지나는 경로와 $\\mathrm{Q}$를 지나는 경로를 더하면?","식":["$4+10=14$"],"설명":"$\\mathrm{P}$를 지나는 경로는 왼쪽 길, $\\mathrm{Q}$를 지나는 경로는 아래쪽 길이어서 서로 겹치지 않는다.","확인":"14","스킬":"P4"}]},"ns-f8d95f7c78e7":{"길":"정차역 사이의 통과역 수를 변수로 두고 0 이상으로 바꾸어 중복조합으로 센다","단계":[{"제목":"정차역 사이의 통과역 수를 변수로 두기","힌트":"$\\mathrm{A}$에서 시작해 한 바퀴 돌며 정차역 $4$개 사이의 통과역 수를 차례로 $x_{1},\\,x_{2},\\,x_{3},\\,x_{4}$라 하면 합과 각각의 조건은 무엇인가?","식":["통과역의 수: $12-4=8$","$x_{1}+x_{2}+x_{3}+x_{4}=8$, $x_{i}\\ge1$"],"설명":"$\\mathrm{A}$가 정차역으로 정해져 있으므로 $\\mathrm{A}$ 다음부터 차례로 사이의 통과역 수를 정하면 정차역의 위치가 하나로 정해진다. 두 정차역 사이에는 통과역이 적어도 $1$개이므로 각 $x_{i}$는 $1$ 이상이다.","확인":"8","스킬":"P3"},{"제목":"0 이상인 변수로 바꾸기","힌트":"각 $x_{i}$에서 $1$씩 빼서 $y_{i}=x_{i}-1$이라 하면 $y_{i}$의 조건과 합은?","식":["$y_{i}=x_{i}-1\\ge0$","$y_{1}+y_{2}+y_{3}+y_{4}=8-4=4$"],"설명":"$x_{i}$가 $1$ 이상이면 중복조합으로 바로 셀 수 없으므로 $1$씩 빼서 $0$ 이상의 변수로 바꾼다. 네 변수에서 $1$씩 뺐으므로 합이 $4$ 줄어든다.","확인":"4","스킬":"P3","고비":true},{"제목":"중복조합으로 경우의 수 구하기","힌트":"음이 아닌 정수 $y_{1},\\,\\cdots,\\,y_{4}$의 합이 $4$인 해의 개수는 몇 가지인가?","식":["${}_{4}\\mathrm{H}_{4}={}_{7}\\mathrm{C}_{4}={}_{7}\\mathrm{C}_{3}=35$"],"설명":"서로 다른 $4$곳에 같은 것 $4$개를 나누어 놓는 중복조합이다. ${}_{n}\\mathrm{H}_{r}={}_{n+r-1}\\mathrm{C}_{r}$를 쓴다.","확인":"35","스킬":"P3"}]},"ns-02be68339d5b":{"길":"ㄱ, ㄴ은 직접 계산하고 ㄷ은 행 전체의 합을 이항계수의 합으로 정리한다","단계":[{"제목":"ㄱ의 값 구하기","힌트":"$f(3,\\,1)$은 ${}_{3}\\mathrm{C}_{1}$에 파스칼의 삼각형에서 이웃한 여섯 수를 더한 값이다. 이웃한 여섯 수의 합은 얼마인가?","식":["이웃한 여섯 수: ${}_{2}\\mathrm{C}_{0},\\,{}_{2}\\mathrm{C}_{1},\\,{}_{3}\\mathrm{C}_{0},\\,{}_{3}\\mathrm{C}_{2},\\,{}_{4}\\mathrm{C}_{1},\\,{}_{4}\\mathrm{C}_{2}$","$1+2+1+3+4+6=17$","$f(3,\\,1)={}_{3}\\mathrm{C}_{1}+17=20$"],"설명":"예시와 같이 ${}_{n}\\mathrm{C}_{r}$의 위쪽 두 수, 양옆 두 수, 아래쪽 두 수를 더한다. 값이 $20$이므로 ㄱ은 옳다.","확인":"17","스킬":"C3"},{"제목":"ㄴ의 값 구하기","힌트":"$f(4,\\,1),\\,f(4,\\,2),\\,f(4,\\,3)$을 각각 구해 더하면 얼마인가?","식":["$f(4,\\,1)={}_{4}\\mathrm{C}_{1}+(1+3+1+6+5+10)=30$","$f(4,\\,2)={}_{4}\\mathrm{C}_{2}+(3+3+4+4+10+10)=40$","$f(4,\\,3)={}_{4}\\mathrm{C}_{3}+(3+1+6+1+10+5)=30$","$30+40+30=100$"],"설명":"ㄱ과 같은 방법으로 이웃한 여섯 수를 더한다. 합이 $100$이므로 ㄴ은 옳다.","확인":"40","스킬":"C3"},{"제목":"행 전체의 합을 이항계수의 합으로 정리하기","힌트":"$f(n,\\,r)$의 일곱 항을 $r=1$부터 $n-1$까지 항별로 더하면 각각 이항계수의 합이다. 항별 합은 얼마인가?","식":["${}_{n}\\mathrm{C}_{r}$의 합: $2^{n}-2$","${}_{n-1}\\mathrm{C}_{r-1}$, ${}_{n-1}\\mathrm{C}_{r}$ 각각의 합: $2^{n-1}-1$","${}_{n}\\mathrm{C}_{r-1}$, ${}_{n}\\mathrm{C}_{r+1}$ 각각의 합: $2^{n}-n-1$","${}_{n+1}\\mathrm{C}_{r}$, ${}_{n+1}\\mathrm{C}_{r+1}$ 각각의 합: $2^{n+1}-n-3$","$\\sum_{r=1}^{n-1}f(n,\\,r)=2^{n+3}-4n-12$"],"설명":"한 행의 이항계수를 모두 더하면 $2^{m}$이므로 빠진 양 끝의 항을 빼서 구한다. 예를 들어 ${}_{n}\\mathrm{C}_{r-1}$은 $r=1,\\,\\cdots,\\,n-1$에서 ${}_{n}\\mathrm{C}_{0}$부터 ${}_{n}\\mathrm{C}_{n-2}$까지이므로 $2^{n}$에서 ${}_{n}\\mathrm{C}_{n-1}+{}_{n}\\mathrm{C}_{n}=n+1$을 뺀다.","확인":null,"스킬":"P6","고비":true},{"제목":"ㄷ의 참거짓 판정하기","힌트":"$n=2012$를 대입한 값을 $8$로 나눈 나머지는 얼마인가?","식":["$n=2012$: $2^{2015}-4\\times2012-12=2^{2015}-8060$","$2^{2015}$은 $8$의 배수이고 $8060=8\\times1007+4$","$2^{2015}-8060$을 $8$로 나눈 나머지는 $4$"],"설명":"나머지가 $0$이 아니므로 $8$의 배수가 아니다. 따라서 ㄷ은 옳지 않다.","확인":"4","스킬":"N3"},{"제목":"옳은 보기 고르기","힌트":"ㄱ, ㄴ, ㄷ 중 옳은 것은 무엇인가?","식":["ㄱ 옳음, ㄴ 옳음, ㄷ 옳지 않음","옳은 것: ㄱ, ㄴ"],"설명":"ㄱ과 ㄴ은 직접 계산한 값이 맞고 ㄷ은 $8$로 나눈 나머지가 $4$여서 옳지 않다.","확인":null,"스킬":"C3"}]},"ns-1087862d88b3":{"길":"x에 1과 -1을 대입한 두 식으로 (B+C)²-A²을 a의 식으로 바꾼다","단계":[{"제목":"x=1, x=-1을 대입해 식 세우기","힌트":"$x=1$을 대입하면 모든 항의 계수가 더해지고, $x=-1$을 대입하면 차수가 홀수인 항은 부호가 바뀐다. 두 식을 $A,\\,B,\\,C$로 나타내면?","식":["$x=1$: $A+B+C=(a+1)^{99}$","$x=-1$: $-A+B+C=(a-1)^{99}$"],"설명":"차수가 홀수인 항의 계수의 합이 $A$이고 차수가 짝수인 항과 상수항의 계수의 합이 $B+C$이다. $x=-1$이면 홀수 차수의 항만 부호가 바뀌어 $-A$가 된다.","확인":null,"스킬":"A3"},{"제목":"(B+C)²-A²을 a의 식으로 나타내기","힌트":"$(B+C)^{2}-A^{2}$을 곱셈공식으로 인수분해하고 앞의 두 식을 이용하면?","식":["$(B+C)^{2}-A^{2}=(B+C+A)(B+C-A)$","$=(a+1)^{99}(a-1)^{99}=(a^{2}-1)^{99}$"],"설명":"두 인수가 앞에서 구한 두 식의 좌변이므로 값을 바로 넣을 수 있다. 지수가 같으므로 밑을 먼저 곱한다.","확인":null,"스킬":"A3","고비":true},{"제목":"a의 값 구하기","힌트":"$(a^{2}-1)^{99}=8^{99}$에서 지수가 같으면 밑은 어떠한가?","식":["$(a^{2}-1)^{99}=8^{99}$이므로 $a^{2}-1=8$","$a^{2}=9$","$a$는 자연수이므로 $a=3$"],"설명":"$99$가 홀수이므로 지수가 같은 두 실수는 밑이 같다. $a^{2}=9$에서 $a=\\pm3$이고 자연수이므로 $3$이다.","확인":"3","스킬":"A3"}]},"ns-23c450248fcb":{"길":"이항전개에서 7의 배수 항을 버리고 남은 일수를 7로 나눈 나머지로 요일을 정한다","단계":[{"제목":"(N+2)^7을 7의 배수를 버린 꼴로 정리하기","힌트":"$(N+2)^{7}$을 이항정리로 전개할 때 $N^{7}$과 $2^{7}$을 제외한 항의 계수는 $7$과 어떤 관계인가?","식":["$(N+2)^{7}={}_{7}\\mathrm{C}_{0}N^{7}+{}_{7}\\mathrm{C}_{1}N^{6}\\cdot2+\\cdots+{}_{7}\\mathrm{C}_{6}N\\cdot2^{6}+{}_{7}\\mathrm{C}_{7}2^{7}$","${}_{7}\\mathrm{C}_{1},\\,\\cdots,\\,{}_{7}\\mathrm{C}_{6}$은 모두 $7$의 배수","$(N+2)^{7}=N^{7}+2^{7}+7k$ ($k$는 정수)"],"설명":"$7$이 소수이므로 $1\\le k\\le6$인 ${}_{7}\\mathrm{C}_{k}=\\frac{7!}{k!\\,(7-k)!}$은 분자의 $7$이 약분되지 않아 $7$의 배수이다. 요일은 $7$일마다 반복되므로 $7$의 배수인 일수는 요일에 영향을 주지 않는다.","확인":null,"스킬":"N3","고비":true},{"제목":"2^7을 7로 나눈 나머지 구하기","힌트":"$(N+2)^{7}$일 후는 $N^{7}+2^{7}$일 후와 같은 요일이다. $2^{7}$을 $7$로 나눈 나머지는 얼마인가?","식":["$2^{7}=128=7\\times18+2$"],"설명":"$N^{7}$째 되는 날이 월요일이므로 $(N+2)^{7}$째 되는 날은 월요일에서 $2^{7}$일 뒤의 요일과 같다. $7$일마다 요일이 반복되므로 나머지 $2$일만 지난 요일이다.","확인":"2","스킬":"N3"},{"제목":"요일 정하기","힌트":"월요일에서 $2$일 뒤는 무슨 요일인가?","식":["월요일 $+2$일 $=$ 수요일"],"설명":"월요일의 하루 뒤는 화요일, 이틀 뒤는 수요일이다.","확인":null,"스킬":"N3"}]},"ns-328417e38003":{"길":"일반항을 k로 쓰고 이항계수의 합과 k를 곱한 합으로 나눈다","단계":[{"제목":"일반항을 이용해 합을 시그마로 나타내기","힌트":"등차수열의 일반항 $a_{k+1}$을 $k$로 나타내 주어진 합을 $\\sum$ 꼴로 쓰면?","식":["$a_{n}=5+2(n-1)$이므로 $a_{k+1}=5+2k$","합 $=\\sum_{k=0}^{11}(5+2k)\\,{}_{11}\\mathrm{C}_{k}=5\\sum_{k=0}^{11}{}_{11}\\mathrm{C}_{k}+2\\sum_{k=0}^{11}k\\,{}_{11}\\mathrm{C}_{k}$"],"설명":"$a_{1}$에는 ${}_{11}\\mathrm{C}_{0}$, $a_{2}$에는 ${}_{11}\\mathrm{C}_{1}$이 곱해지므로 $a_{k+1}$에 ${}_{11}\\mathrm{C}_{k}$가 곱해진다. 합을 상수 부분과 $k$가 곱해진 부분으로 나눈다.","확인":null,"스킬":"P6"},{"제목":"이항계수의 합 구하기","힌트":"$(1+x)^{11}$을 이항정리로 전개한 식에 $x=1$을 대입하면 ${}_{11}\\mathrm{C}_{k}$를 모두 더한 값은?","식":["$\\sum_{k=0}^{11}{}_{11}\\mathrm{C}_{k}=2^{11}=2048$"],"설명":"이항정리 $(1+x)^{11}=\\sum_{k=0}^{11}{}_{11}\\mathrm{C}_{k}x^{k}$에 $x=1$을 넣으면 계수의 합이 $2^{11}$이다.","확인":"2048","스킬":"P6"},{"제목":"k를 곱한 이항계수의 합 구하기","힌트":"$k\\,{}_{11}\\mathrm{C}_{k}$를 ${}_{10}\\mathrm{C}_{k-1}$ 꼴로 바꾸어 합하면 얼마인가?","식":["$k\\,{}_{11}\\mathrm{C}_{k}=11\\,{}_{10}\\mathrm{C}_{k-1}$","$\\sum_{k=1}^{11}k\\,{}_{11}\\mathrm{C}_{k}=11\\sum_{k=1}^{11}{}_{10}\\mathrm{C}_{k-1}=11\\times2^{10}=11264$"],"설명":"$k=0$인 항은 $0$이므로 $k=1$부터 더한다. $k\\,{}_{11}\\mathrm{C}_{k}=\\frac{11!}{(k-1)!\\,(11-k)!}$이고 이는 $11\\times\\frac{10!}{(k-1)!\\,(11-k)!}=11\\,{}_{10}\\mathrm{C}_{k-1}$이다.","확인":"11264","스킬":"P6","고비":true},{"제목":"두 합을 합쳐 2의 거듭제곱으로 나타내기","힌트":"$5\\times2^{11}+2\\times11\\times2^{10}$을 $2$의 거듭제곱으로 나타내면?","식":["$5\\times2^{11}+2\\times11\\times2^{10}=5\\times2^{11}+11\\times2^{11}$","$=16\\times2^{11}=2^{15}$"],"설명":"$2\\times2^{10}=2^{11}$이므로 두 항에서 $2^{11}$을 묶을 수 있다.","확인":null,"스킬":"P6"}]},"ns-401a1a08150d":{"길":"지수의 순서쌍을 0 이상의 해로 바꿔 중복조합으로 세고 상한을 넘는 경우를 뺀다","단계":[{"제목":"곱해서 x^7이 되는 지수 조건 정하기","힌트":"세 괄호에서 항을 하나씩 골라 곱하면 $x^{7}$이 되는 경우를 세는 것이다. 고른 항의 지수를 $p,\\,q,\\,r$라 하면 조건은?","식":["$p+q+r=7$","$1\\le p,\\,q,\\,r\\le4$"],"설명":"각 괄호의 항은 $x,\\,x^{2},\\,x^{3},\\,x^{4}$이므로 지수는 $1$ 이상 $4$ 이하이다. 지수의 순서쌍 $(p,\\,q,\\,r)$ 하나가 곱해서 $x^{7}$이 되는 경우 하나이므로 순서쌍의 개수가 계수이다.","확인":null,"스킬":"P3"},{"제목":"0 이상의 변수로 바꿔 상한 없이 세기","힌트":"$p-1=a,\\ q-1=b,\\ r-1=c$로 바꾸면 합과 범위는? 상한을 무시하고 세면 몇 가지인가?","식":["$a+b+c=4$, $0\\le a,\\,b,\\,c\\le3$","상한 $3$을 무시하면 ${}_{3}\\mathrm{H}_{4}={}_{6}\\mathrm{C}_{4}=15$"],"설명":"$0$ 이상의 정수 $a,\\,b,\\,c$의 합이 $4$인 해의 개수는 중복조합이다. 이 중에는 한 변수가 $4$인 경우처럼 상한 $3$을 넘는 것이 섞여 있다.","확인":"15","스킬":"P3"},{"제목":"상한을 넘는 경우 빼기","힌트":"$a,\\,b,\\,c$ 중 하나가 $4$ 이상이면 합이 $4$인 해는 어떤 모양인가?","식":["한 변수가 $4$ 이상이면 그 변수는 $4$, 나머지는 $0$: $(4,\\,0,\\,0),\\,(0,\\,4,\\,0),\\,(0,\\,0,\\,4)$의 $3$가지","$15-3=12$"],"설명":"합이 $4$이므로 변수 하나가 $4$ 이상이면 정확히 $4$이고 나머지는 모두 $0$이다. 두 변수가 동시에 $4$ 이상일 수는 없으므로 겹쳐 빼는 경우가 없다.","확인":"12","스킬":"P3","고비":true}]},"ns-41876cf4b4ae":{"길":"빠진 마지막 항을 더해 이항정리 꼴로 만든 뒤 9로 나눈 나머지를 구한다","단계":[{"제목":"빠진 항을 더해 이항정리 꼴 만들기","힌트":"${}_{10}\\mathrm{C}_{10}\\cdot7^{0}=1$이 빠져 있다. $N$에 $1$을 더하면 어떤 식이 되는가?","식":["$N+1=\\sum_{k=0}^{10}{}_{10}\\mathrm{C}_{k}\\,7^{10-k}=(7+1)^{10}=8^{10}$"],"설명":"$N$은 ${}_{10}\\mathrm{C}_{0}7^{10}$부터 ${}_{10}\\mathrm{C}_{9}7$까지이고 마지막 항 ${}_{10}\\mathrm{C}_{10}7^{0}=1$이 없다. 이 항을 더하면 $(7+1)^{10}$의 전개식이 된다.","확인":null,"스킬":"N3","고비":true},{"제목":"8^10을 9로 나눈 나머지 구하기","힌트":"$8=9-1$로 보면 $8^{10}$을 $9$로 나눈 나머지는?","식":["$8^{10}=(9-1)^{10}$","전개하면 마지막 항 $(-1)^{10}=1$을 제외한 항은 모두 $9$의 배수","$8^{10}$을 $9$로 나눈 나머지는 $1$"],"설명":"합동식으로 쓰면 $8\\equiv-1\\pmod{9}$이므로 $8^{10}\\equiv(-1)^{10}=1$이다.","확인":"1","스킬":"N3"},{"제목":"N을 9로 나눈 나머지 구하기","힌트":"$N=8^{10}-1$이므로 $N$을 $9$로 나눈 나머지는?","식":["$N=8^{10}-1\\equiv1-1=0\\pmod{9}$"],"설명":"$8^{10}$을 $9$로 나눈 나머지가 $1$이므로 $1$을 뺀 $N$은 $9$의 배수이다.","확인":"0","스킬":"N3"}]},"ns-4b355973f724":{"길":"이항전개에서 7의 배수 항을 버리고 7로 나눈 나머지로 요일을 정한다","단계":[{"제목":"(n+2)^7을 7의 배수를 버린 꼴로 정리하기","힌트":"$(n+2)^{7}$을 이항정리로 전개할 때 $n^{7}$과 $2^{7}$을 제외한 항의 계수는 $7$과 어떤 관계인가?","식":["$(n+2)^{7}={}_{7}\\mathrm{C}_{0}n^{7}+{}_{7}\\mathrm{C}_{1}n^{6}\\cdot2+\\cdots+{}_{7}\\mathrm{C}_{6}n\\cdot2^{6}+{}_{7}\\mathrm{C}_{7}2^{7}$","${}_{7}\\mathrm{C}_{1},\\,\\cdots,\\,{}_{7}\\mathrm{C}_{6}$은 모두 $7$의 배수","$(n+2)^{7}=n^{7}+2^{7}+7k$ ($k$는 정수)"],"설명":"$7$이 소수이므로 $1\\le k\\le6$인 ${}_{7}\\mathrm{C}_{k}=\\frac{7!}{k!\\,(7-k)!}$은 분자의 $7$이 약분되지 않아 $7$의 배수이다. 요일은 $7$일마다 반복되므로 $7$의 배수인 일수는 요일에 영향을 주지 않는다.","확인":null,"스킬":"N3","고비":true},{"제목":"(n+2)^7을 7로 나눈 나머지 구하기","힌트":"오늘이 월요일이고 $n^{7}$일 후가 수요일이므로 $n^{7}$을 $7$로 나눈 나머지는 얼마인가? $2^{7}$을 $7$로 나눈 나머지와 합하면?","식":["월요일에서 수요일까지 $2$일이므로 $n^{7}\\equiv2\\pmod{7}$","$2^{7}=128\\equiv2\\pmod{7}$","$(n+2)^{7}\\equiv n^{7}+2^{7}\\equiv2+2=4\\pmod{7}$"],"설명":"요일은 $7$일마다 반복되므로 일수를 $7$로 나눈 나머지만 따진다. 나머지가 $4$이면 월요일에서 $4$일 뒤의 요일이다.","확인":"4","스킬":"N3"},{"제목":"요일 정하기","힌트":"월요일에서 $4$일 뒤는 무슨 요일인가?","식":["월 $\\to$ 화 $\\to$ 수 $\\to$ 목 $\\to$ 금","금요일"],"설명":"월요일의 하루 뒤는 화요일, 이틀 뒤는 수요일, 사흘 뒤는 목요일, 나흘 뒤는 금요일이다.","확인":null,"스킬":"N3"}]},"ns-577640bd777b":{"길":"지수 하나가 0인 순서쌍을 합이 7인 양의 정수 구성별로 나누어 센다","단계":[{"제목":"항의 지수 조건 정하기","힌트":"항을 $a^{v}b^{w}c^{x}d^{y}$라 하면 지수의 합은 얼마이며, 세 종류의 문자를 포함하려면 지수는 어떠해야 하는가?","식":["$v+w+x+y=7$","문자 $3$종류 포함: 네 지수 중 하나는 $0$, 나머지 셋은 $1$ 이상"],"설명":"전개식의 각 항은 $7$개의 괄호에서 문자를 하나씩 골라 곱한 것이므로 지수의 합이 $7$이다. 지수가 $0$이 아닌 문자가 정확히 $3$개여야 하고, 지수의 순서쌍 하나가 서로 다른 항 하나이다.","확인":null,"스킬":"P3"},{"제목":"지수의 구성 나누기","힌트":"$0$이 아닌 세 지수는 합이 $7$인 양의 정수이다. 순서를 무시하면 어떤 구성이 가능한가?","식":["$\\{5,\\,1,\\,1\\},\\ \\{4,\\,2,\\,1\\},\\ \\{3,\\,3,\\,1\\},\\ \\{3,\\,2,\\,2\\}$","구성의 수: $4$가지"],"설명":"세 양의 정수의 합이 $7$인 경우를 순서를 무시하고 나열하면 $4$가지이다. 이 중 같은 수가 있는 구성은 세 가지, 모두 다른 구성은 $\\{4,\\,2,\\,1\\}$ 하나이다.","확인":"4","스킬":"P3","고비":true},{"제목":"같은 수가 있는 구성의 순서쌍 구하기","힌트":"$(5,\\,1,\\,1,\\,0)$처럼 같은 수가 두 번 나오는 구성을 네 자리에 나열하는 방법은 몇 가지이며, 이런 구성은 모두 몇 개인가?","식":["$(5,\\,1,\\,1,\\,0),\\ (3,\\,3,\\,1,\\,0),\\ (3,\\,2,\\,2,\\,0)$ 각각 $\\frac{4!}{2!}=12$","$12\\times3=36$"],"설명":"같은 수 두 개는 구별되지 않으므로 같은 것이 있는 순열이다.","확인":"36","스킬":"P3"},{"제목":"모두 다른 구성을 더해 항의 개수 구하기","힌트":"$(4,\\,2,\\,1,\\,0)$을 네 자리에 나열하는 방법을 구해 앞의 값과 더하면?","식":["$(4,\\,2,\\,1,\\,0)$: $4!=24$","$36+24=60$"],"설명":"네 수가 모두 달라 $4!$가지이다. 구성이 다르면 서로 다른 순서쌍이므로 합의 법칙으로 더한다.","확인":"60","스킬":"P3"}]},"ns-5bdfbec2e3d6":{"길":"nCr+nCr+1=n+1Cr+1을 이어 써서 각 영역의 합을 한 항으로 모은다","단계":[{"제목":"영역 (1)의 합 A 구하기","힌트":"(1)은 ${}_{2}\\mathrm{C}_{2}$부터 ${}_{9}\\mathrm{C}_{2}$까지 ${}_{n}\\mathrm{C}_{2}$를 이은 줄이다. ${}_{n}\\mathrm{C}_{r}+{}_{n}\\mathrm{C}_{r+1}={}_{n+1}\\mathrm{C}_{r+1}$을 이어 쓰면 합은?","식":["$A={}_{2}\\mathrm{C}_{2}+{}_{3}\\mathrm{C}_{2}+\\cdots+{}_{9}\\mathrm{C}_{2}$","${}_{2}\\mathrm{C}_{2}={}_{3}\\mathrm{C}_{3}$이므로 ${}_{3}\\mathrm{C}_{3}+{}_{3}\\mathrm{C}_{2}={}_{4}\\mathrm{C}_{3}$","${}_{4}\\mathrm{C}_{3}+{}_{4}\\mathrm{C}_{2}={}_{5}\\mathrm{C}_{3},\\ \\cdots,\\ {}_{9}\\mathrm{C}_{3}+{}_{9}\\mathrm{C}_{2}={}_{10}\\mathrm{C}_{3}$","$A={}_{10}\\mathrm{C}_{3}=120$"],"설명":"맨 앞의 ${}_{2}\\mathrm{C}_{2}=1$을 ${}_{3}\\mathrm{C}_{3}$으로 바꾸면 이웃한 두 수의 합이 아래 수가 되는 성질을 계속 쓸 수 있다.","확인":"120","스킬":"P6"},{"제목":"영역 (2)의 합 B 구하기","힌트":"(2)는 ${}_{3}\\mathrm{C}_{0},\\,{}_{4}\\mathrm{C}_{1},\\,\\cdots,\\,{}_{9}\\mathrm{C}_{6}$을 이은 줄이다. 같은 방법으로 앞에서부터 묶으면 합은?","식":["$B={}_{3}\\mathrm{C}_{0}+{}_{4}\\mathrm{C}_{1}+{}_{5}\\mathrm{C}_{2}+\\cdots+{}_{9}\\mathrm{C}_{6}$","${}_{3}\\mathrm{C}_{0}={}_{4}\\mathrm{C}_{0}$이므로 ${}_{4}\\mathrm{C}_{0}+{}_{4}\\mathrm{C}_{1}={}_{5}\\mathrm{C}_{1}$","${}_{5}\\mathrm{C}_{1}+{}_{5}\\mathrm{C}_{2}={}_{6}\\mathrm{C}_{2},\\ \\cdots,\\ {}_{9}\\mathrm{C}_{5}+{}_{9}\\mathrm{C}_{6}={}_{10}\\mathrm{C}_{6}$","$B={}_{10}\\mathrm{C}_{6}=210$"],"설명":"(1)과 같은 방법으로 ${}_{3}\\mathrm{C}_{0}=1$을 ${}_{4}\\mathrm{C}_{0}$으로 바꾸어 앞의 두 수부터 차례로 합친다.","확인":"210","스킬":"P6","고비":true},{"제목":"영역 (3)의 합 C 구하기","힌트":"(3)은 파스칼의 삼각형 ${}_{4}\\mathrm{C}_{0}$부터 ${}_{4}\\mathrm{C}_{4}$까지의 한 줄이다. 이 줄의 합은?","식":["$C={}_{4}\\mathrm{C}_{0}+{}_{4}\\mathrm{C}_{1}+\\cdots+{}_{4}\\mathrm{C}_{4}=2^{4}=16$"],"설명":"이항정리 $(1+x)^{4}=\\sum_{k=0}^{4}{}_{4}\\mathrm{C}_{k}x^{k}$에 $x=1$을 대입하면 한 줄의 합이 $2^{4}$이다.","확인":"16","스킬":"P6"},{"제목":"세 영역의 합 구하기","힌트":"$A,\\,B,\\,C$를 모두 더하면?","식":["$A+B+C=120+210+16=346$"],"설명":"${}_{10}\\mathrm{C}_{3}=120$, ${}_{10}\\mathrm{C}_{6}={}_{10}\\mathrm{C}_{4}=210$이다. 세 값을 더한다.","확인":"346","스킬":"P1"}]},"ns-5e481e9eb914":{"길":"80과 9의 합으로 전개해 6400의 배수를 버리고 81^40을 x에 대한 식으로 나머지를 구한다","단계":[{"제목":"80과 9의 합으로 전개해 6400의 배수 버리기","힌트":"$89=80+9$로 보고 $(80+9)^{80}$을 이항정리로 전개할 때 $6400=80^{2}$의 배수인 항은 어느 것인가?","식":["$89^{80}=(80+9)^{80}={}_{80}\\mathrm{C}_{0}9^{80}+{}_{80}\\mathrm{C}_{1}\\cdot80\\cdot9^{79}+{}_{80}\\mathrm{C}_{2}\\cdot80^{2}\\cdot9^{78}+\\cdots+{}_{80}\\mathrm{C}_{80}80^{80}$","둘째 항부터는 $80^{2}$의 배수","$9^{80}=81^{40}$을 $6400$으로 나눈 나머지를 구하면 된다"],"설명":"둘째 항은 ${}_{80}\\mathrm{C}_{1}=80$ 때문에 $80\\times80\\times9^{79}$으로 $80^{2}$의 배수이고, 셋째 항부터는 $80^{2}$ 이상이 곱해져 있다.","확인":null,"스킬":"N3"},{"제목":"81^40을 x에 대한 식으로 나타내기","힌트":"$80=x$로 놓으면 $81^{40}=(x+1)^{40}$이다. 이를 $x^{2}$으로 나눈 나머지를 $ax+b$로 두면 어떤 식이 되는가?","식":["$(x+1)^{40}=x^{2}Q(x)+ax+b$"],"설명":"$x=80$이면 $x^{2}=6400$이므로 $x^{2}$으로 나눈 나머지 $ax+b$를 구해 $x=80$을 넣으면 $6400$으로 나눈 나머지를 얻는다. 나머지는 $x^{2}$보다 차수가 낮은 일차식이다.","확인":null,"스킬":"A4"},{"제목":"b의 값 구하기","힌트":"양변에 $x=0$을 대입하면 $b$는 얼마인가?","식":["$x=0$: $1=b$"],"설명":"$x=0$이면 $x^{2}Q(x)$와 $ax$가 모두 $0$이 된다.","확인":"1","스킬":"A3"},{"제목":"a의 값 구하기","힌트":"$b=1$을 넣고 $1$을 이항한 뒤 양변을 $x$로 나누어 다시 $x=0$을 대입하면 $a$는 얼마인가?","식":["$(x+1)^{40}-1=x^{2}Q(x)+ax$","$x\\{(x+1)^{39}+(x+1)^{38}+\\cdots+(x+1)+1\\}=x^{2}Q(x)+ax$","양변을 $x$로 나누면 $(x+1)^{39}+\\cdots+(x+1)+1=xQ(x)+a$","$x=0$: $1$이 $40$개이므로 $a=40$"],"설명":"$y^{40}-1=(y-1)(y^{39}+\\cdots+y+1)$에 $y=x+1$을 넣으면 $y-1=x$이므로 $(x+1)^{40}-1$이 $x$로 묶인다. 양변을 $x$로 나눈 뒤 $x=0$을 넣으면 $(x+1)$ 대신 $1$이 되어 $40$개의 합이다.","확인":"40","스킬":"A4","고비":true},{"제목":"x=80을 대입해 나머지 구하기","힌트":"나머지 $40x+1$에 $x=80$을 넣으면 얼마인가?","식":["$40\\times80+1=3201$"],"설명":"$3201$은 $6400$보다 작으므로 $6400$으로 나눈 나머지이다.","확인":"3201","스킬":"N3"}]}});
